INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acddb9b6-5880-4cf5-b4ba-2c72d926ab49', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3415a74e-4b98-4118-9c81-f092dc36bd38', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "D", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('59004d50-7b63-4f54-911f-22d4abdea6c5', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "B", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "C", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12a9fcb9-7e31-47f8-b883-b81848a8ed23', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "D", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d68ba22-403d-45fd-8621-6a78b6f7288f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c71bccb-5e47-49e7-a336-ebd02cd244ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: BGP path selection not optimal. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": true}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": false}]', 'local preference or MED configuration. Use show bgp 10.0.0.0, show route protocol bgp to diagnose.', '{}', 'Troubleshooting', 14.0, '8332bfc3943a4701_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f53a2502-52d2-4816-9fb1-c100e4121877', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e1be18f-7e86-404f-bea7-bc039bafcb11', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58489e92-d64d-4980-b1ac-a2dea51ab14d', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "D", "text": "too many concurrent translations exceeding pool size", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d245a5d-d02d-4226-8ee6-fcd222ce31de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "query not acknowledged from a neighbor", "is_correct": false}, {"id": "D", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01ceab7f-62cd-41fe-87b1-fd61254f3c9f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}, {"id": "B", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f2ba3a8b-b0a7-4d1a-946a-c045b0f7524a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523c8a7f-0e5a-4766-b5a6-9eee00cf8d57', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "D", "text": "peering receiving too many prefixes", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49edc74f-7524-473b-ac1f-ca8803029d2e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('721d988e-8df3-4471-92a1-16dd8f622d52', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('838cdc1a-a8ae-4384-a310-9ec01efd1f80', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''MPLS LSP not signaling'', which tool or command should be used?', '[{"id": "A", "text": "show ldp session, show route, ping transport-address", "is_correct": false}, {"id": "B", "text": "show lldp, show lldp interface ge-0/0/0", "is_correct": false}, {"id": "C", "text": "show route table mpls.0, show ldp session, ping mpls", "is_correct": false}, {"id": "D", "text": "show mpls lsp, show rsvp session, log messages", "is_correct": true}]', 'Use show mpls lsp, show rsvp session, log messages to check RSVP-TE path computation or CSPF failure.', '{}', 'Troubleshooting', 14.0, 'b0935c698699f2d6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a59634d2-8d52-4bed-a0ab-e178a70c50b9', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''LLDP neighbor not showing'', which tool or command should be used?', '[{"id": "A", "text": "show ip access-lists, debug ip icmp", "is_correct": false}, {"id": "B", "text": "show bgp 10.0.0.0, show route protocol bgp", "is_correct": false}, {"id": "C", "text": "show lldp, show lldp interface ge-0/0/0", "is_correct": true}, {"id": "D", "text": "show ldp session, show route, ping transport-address", "is_correct": false}]', 'Use show lldp, show lldp interface ge-0/0/0 to check LLDP disabled globally or per interface.', '{}', 'Troubleshooting', 14.0, 'd5f6d4fd4d73ff5b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9253d78-681d-4058-97fb-31bb7bc34c2a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''Port security violation on switch'', which tool or command should be used?', '[{"id": "A", "text": "show port-security, show interfaces status err-disabled", "is_correct": true}, {"id": "B", "text": "show policy-map interface, show interface", "is_correct": false}, {"id": "C", "text": "show security policies, show security flow session", "is_correct": false}, {"id": "D", "text": "show lldp, show lldp interface, set lldp interface", "is_correct": false}]', 'Use show port-security, show interfaces status err-disabled to check excessive MAC addresses or sticky MAC misconfiguration.', '{}', 'Troubleshooting', 14.0, '5e528c29f75e0bff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3443a6a9-ad1f-4e44-a8d5-fecfb362aa8f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''Interface flapping up and down'', which tool or command should be used?', '[{"id": "A", "text": "show policy-map interface, show interface", "is_correct": false}, {"id": "B", "text": "show interfaces, show interfaces diagnostics optics", "is_correct": true}, {"id": "C", "text": "show ipv6 interface, debug ipv6 nd", "is_correct": false}, {"id": "D", "text": "show bgp summary, show log, check max-prefix", "is_correct": false}]', 'Use show interfaces, show interfaces diagnostics optics to check faulty SFP, cable issue, or speed/duplex mismatch.', '{}', 'Troubleshooting', 14.0, 'c8b24c120a2ffcae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68dcb7ad-5824-4889-baf6-4ba96d7aa309', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''IPv6 router not advertising prefix'', which tool or command should be used?', '[{"id": "A", "text": "show lldp, show interfaces vxlan, traceroute", "is_correct": false}, {"id": "B", "text": "show ipv6 interface, debug ipv6 nd", "is_correct": true}, {"id": "C", "text": "show route advertising-protocol bgp, show policy", "is_correct": false}, {"id": "D", "text": "show evpn, show ethernet-switching table, show bgp evpn", "is_correct": false}]', 'Use show ipv6 interface, debug ipv6 nd to check RA suppression or no ipv6 enable on interface.', '{}', 'Troubleshooting', 14.0, '6472aaa6e039a95e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d86001c-f651-4e8c-b88a-4fc09fa6de86', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''DHCP server running out of addresses'', which tool or command should be used?', '[{"id": "A", "text": "show ip dhcp pool, show ip dhcp conflict", "is_correct": true}, {"id": "B", "text": "show spanning-tree, show interfaces counters", "is_correct": false}, {"id": "C", "text": "show processes cpu, show log, show ip bgp summary", "is_correct": false}, {"id": "D", "text": "show etherchannel summary, show lacp neighbor", "is_correct": false}]', 'Use show ip dhcp pool, show ip dhcp conflict to check lease time too long or subnet too small.', '{}', 'Troubleshooting', 14.0, '96fb35abfaf0788b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d186960f-a6cf-4024-990c-92a6f20db01f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''PIM neighbors not forming'', which tool or command should be used?', '[{"id": "A", "text": "show ip pim neighbor, show ip pim rp mapping", "is_correct": true}, {"id": "B", "text": "show ip access-lists, extended ping with TCP", "is_correct": false}, {"id": "C", "text": "show ospf neighbor, show ospf3 neighbor", "is_correct": false}, {"id": "D", "text": "show bgp 10.0.0.0, show route protocol bgp", "is_correct": false}]', 'Use show ip pim neighbor, show ip pim rp mapping to check PIM mode mismatch or RP unreachable.', '{}', 'Troubleshooting', 14.0, 'e1b14a07bb2ccebd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b79127-f9b2-478e-a4e7-7e4eb07de64b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'apply', 'To diagnose ''Ping fails to remote subnet'', which tool or command should be used?', '[{"id": "A", "text": "show lldp, show lldp interface ge-0/0/0", "is_correct": false}, {"id": "B", "text": "show etherchannel summary, show lacp neighbor", "is_correct": false}, {"id": "C", "text": "show route, show ip access-lists, ping extended", "is_correct": true}, {"id": "D", "text": "show mpls lsp, show rsvp session, log messages", "is_correct": false}]', 'Use show route, show ip access-lists, ping extended to check missing default gateway or ACL blocking ICMP.', '{}', 'Troubleshooting', 14.0, 'a438be1be2440612_gen_v6', true) ON CONFLICT (id) DO NOTHING;
