INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a46c10a-29a5-47b6-95cf-7fa16b1110c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 1 (Router) LSA and ASBR?', '[{"id": "A", "text": "Type 1 (Router) LSA is advertises router link states within its own area; ASBR is AS Boundary Router redistributing external routes.", "is_correct": true}, {"id": "B", "text": "Type 1 (Router) LSA is advertises router link states within its own area; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "C", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "D", "text": "Type 1 (Router) LSA is advertises router link states within its own area; ASBR is AS Boundary Router redistributing external routes.", "is_correct": true}]', 'Type 1 (Router) LSA advertises router link states within its own area. ASBR AS Boundary Router redistributing external routes.', '{}', 'OSPF Concepts', 14.0, '0b0d69e01fba8a21_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fcb3df4b-fb8c-400e-89c2-3e1827972780', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between ABR and Type 5 (External) LSA?', '[{"id": "A", "text": "ABR is Area Border Router connecting Area 0 to other areas; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": false}, {"id": "B", "text": "ABR is Area Border Router connecting Area 0 to other areas; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": true}, {"id": "C", "text": "ABR is Area Border Router connecting Area 0 to other areas; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "D", "text": "ABR is Area Border Router connecting Area 0 to other areas; Virtual Link is connects non-backbone area to Area 0 through transit area.", "is_correct": false}]', 'ABR Area Border Router connecting Area 0 to other areas. Type 5 (External) LSA external route advertisement from ASBR.', '{}', 'OSPF Concepts', 14.0, 'b6d73d5d2a0fd263_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54641566-2ab4-49d2-8129-d41334046298', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 2 (Network) LSA and Type 3 (Summary) LSA?', '[{"id": "A", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only.", "is_correct": false}, {"id": "B", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "C", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}, {"id": "D", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": true}]', 'Type 2 (Network) LSA advertises network segment info; generated by DR. Type 3 (Summary) LSA inter-area route advertisement from ABR.', '{}', 'OSPF Concepts', 14.0, 'dd42bf0c8d4929ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
