INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61e1c59d-d85e-4f3b-a204-edd361abe192', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between DR and NSSA?', '[{"id": "A", "text": "DR is Designated Router elected on multi-access networks; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": true}, {"id": "B", "text": "DR is Designated Router elected on multi-access networks; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": false}, {"id": "C", "text": "DR is Designated Router elected on multi-access networks; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": false}, {"id": "D", "text": "DR is Designated Router elected on multi-access networks; Stub Area is blocks Type 5 LSAs; default route for external.", "is_correct": false}]', 'DR Designated Router elected on multi-access networks. NSSA stub area that imports externals via Type 7 LSAs.', '{}', 'OSPF Concepts', 14.0, 'a0547b00d2a1ec85_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('369acd66-d086-41a6-8708-4de8cd911a3a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 5 (External) LSA and Type 3 (Summary) LSA?', '[{"id": "A", "text": "Type 5 (External) LSA is external route advertisement from ASBR; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "B", "text": "Type 5 (External) LSA is external route advertisement from ASBR; ABR is Area Border Router connecting Area 0 to other areas.", "is_correct": false}, {"id": "C", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": false}, {"id": "D", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": true}]', 'Type 5 (External) LSA external route advertisement from ASBR. Type 3 (Summary) LSA inter-area route advertisement from ABR.', '{}', 'OSPF Concepts', 14.0, '4bb5e26f878fbc12_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('252e397e-2364-4c7c-9770-3a4f142454b4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between SPF Algorithm and Area 0?', '[{"id": "A", "text": "SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "B", "text": "SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": true}, {"id": "C", "text": "SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "D", "text": "SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": false}]', 'SPF Algorithm Shortest Path First (Dijkstra) computes loop-free routes. Area 0 OSPF backbone area connecting all other areas.', '{}', 'OSPF Concepts', 14.0, 'ca4fb535d15b7fa3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
