INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74981d96-7774-4f8a-8d8d-957b35e17b46', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Totally Stubby Area and Area 0?', '[{"id": "A", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": true}, {"id": "B", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": false}, {"id": "C", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Virtual Link is connects non-backbone area to Area 0 through transit area.", "is_correct": false}, {"id": "D", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": true}]', 'Totally Stubby Area blocks Type 3/4/5 LSAs; default route only. Area 0 OSPF backbone area connecting all other areas.', '{}', 'OSPF Concepts', 14.0, 'ad663c0f0a3f8be1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c2a955a-4461-4a12-be1c-092fba2766f2', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 4 (ASBR Summary) LSA and BDR?', '[{"id": "A", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; Stub Area is blocks Type 5 LSAs; default route for external.", "is_correct": false}, {"id": "B", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "C", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": true}, {"id": "D", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": true}]', 'Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas. BDR Backup Designated Router; takes over if DR fails.', '{}', 'OSPF Concepts', 14.0, 'b14b4decd2464523_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('86b23cd1-978d-4867-8ea8-47192b29df05', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 3 (Summary) LSA and Type 5 (External) LSA?', '[{"id": "A", "text": "Type 3 (Summary) LSA is inter-area route advertisement from ABR; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": false}, {"id": "B", "text": "Type 3 (Summary) LSA is inter-area route advertisement from ABR; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}, {"id": "C", "text": "Type 3 (Summary) LSA is inter-area route advertisement from ABR; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": false}, {"id": "D", "text": "Type 3 (Summary) LSA is inter-area route advertisement from ABR; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": true}]', 'Type 3 (Summary) LSA inter-area route advertisement from ABR. Type 5 (External) LSA external route advertisement from ASBR.', '{}', 'OSPF Concepts', 14.0, '0471db42983114b0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f31e0c26-8988-48d4-a71e-d044849c29c3', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Virtual Link and SPF Algorithm?', '[{"id": "A", "text": "Virtual Link is connects non-backbone area to Area 0 through transit area; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": false}, {"id": "B", "text": "Virtual Link is connects non-backbone area to Area 0 through transit area; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": true}, {"id": "C", "text": "Virtual Link is connects non-backbone area to Area 0 through transit area; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": false}, {"id": "D", "text": "Virtual Link is connects non-backbone area to Area 0 through transit area; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": false}]', 'Virtual Link connects non-backbone area to Area 0 through transit area. SPF Algorithm Shortest Path First (Dijkstra) computes loop-free routes.', '{}', 'OSPF Concepts', 14.0, '553d3716112e4b66_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('becb86ae-a7f4-45f9-8ad9-fff17ef67a27', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between DROTHER and NSSA?', '[{"id": "A", "text": "DROTHER is non-DR/BDR router on multi-access segment; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": true}, {"id": "B", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": false}, {"id": "C", "text": "DROTHER is non-DR/BDR router on multi-access segment; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": false}, {"id": "D", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": false}]', 'DROTHER non-DR/BDR router on multi-access segment. NSSA stub area that imports externals via Type 7 LSAs.', '{}', 'OSPF Concepts', 14.0, '3f9010a63995fe51_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2496ef2e-b357-4d01-858d-30551236f0cd', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Stub Area and Router ID?', '[{"id": "A", "text": "Stub Area is blocks Type 5 LSAs; default route for external; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}, {"id": "B", "text": "Stub Area is blocks Type 5 LSAs; default route for external; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": false}, {"id": "C", "text": "Stub Area is blocks Type 5 LSAs; default route for external; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": true}, {"id": "D", "text": "Stub Area is blocks Type 5 LSAs; default route for external; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": true}]', 'Stub Area blocks Type 5 LSAs; default route for external. Router ID unique 32-bit identifier for OSPF router identification.', '{}', 'OSPF Concepts', 14.0, '621d8a67e74e7854_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('907c0c5e-1da5-46bc-8c5c-504bad8e11f7', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Network Type and Totally Stubby Area?', '[{"id": "A", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "B", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); ASBR is AS Boundary Router redistributing external routes.", "is_correct": false}, {"id": "C", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only.", "is_correct": true}, {"id": "D", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}]', 'Network Type OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint). Totally Stubby Area blocks Type 3/4/5 LSAs; default route only.', '{}', 'OSPF Concepts', 14.0, 'd3054e14d0e36997_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e84c6395-4ca6-4948-a05b-5bf5d905954a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Network Type and Stub Area?', '[{"id": "A", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "B", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Stub Area is blocks Type 5 LSAs; default route for external.", "is_correct": true}, {"id": "C", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "D", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Stub Area is blocks Type 5 LSAs; default route for external.", "is_correct": true}]', 'Network Type OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint). Stub Area blocks Type 5 LSAs; default route for external.', '{}', 'OSPF Concepts', 14.0, '6661b6cad881ede8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65415db6-3109-436c-b60c-331af4bd97de', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between PortFast and Edge Port?', '[{"id": "A", "text": "PortFast is immediately transitions access port to forwarding; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}, {"id": "B", "text": "PortFast is immediately transitions access port to forwarding; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": false}, {"id": "C", "text": "PortFast is immediately transitions access port to forwarding; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}, {"id": "D", "text": "PortFast is immediately transitions access port to forwarding; Edge Port is port connected to end host; immediate forwarding.", "is_correct": true}]', 'PortFast immediately transitions access port to forwarding. Edge Port port connected to end host; immediate forwarding.', '{}', 'STP Feature Comparison', 14.0, '91a02844cfe7bd8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97650211-3be3-4099-a14c-1dd738a1f1b0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Bridge and BPDU Filter?', '[{"id": "A", "text": "Root Bridge is elected root of spanning tree; all ports are designated; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "B", "text": "Root Bridge is elected root of spanning tree; all ports are designated; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}, {"id": "C", "text": "Root Bridge is elected root of spanning tree; all ports are designated; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": true}, {"id": "D", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}]', 'Root Bridge elected root of spanning tree; all ports are designated. BPDU Filter suppresses sending/receiving BPDUs on a port.', '{}', 'STP Feature Comparison', 14.0, '143bacc699f63721_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4f285156-988e-4348-99ac-b838033196eb', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between PVST+ and Rapid PVST+?', '[{"id": "A", "text": "PVST+ is Cisco per-VLAN STP with separate instance per VLAN; Edge Port is port connected to end host; immediate forwarding.", "is_correct": false}, {"id": "B", "text": "PVST+ is Cisco per-VLAN STP with separate instance per VLAN; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": true}, {"id": "C", "text": "PVST+ is Cisco per-VLAN STP with separate instance per VLAN; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}, {"id": "D", "text": "PVST+ is Cisco per-VLAN STP with separate instance per VLAN; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}]', 'PVST+ Cisco per-VLAN STP with separate instance per VLAN. Rapid PVST+ Cisco per-VLAN RSTP.', '{}', 'STP Feature Comparison', 14.0, 'e1afd2a58c05952d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b14b85f-ab52-4cb4-8261-9faed45de81f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Alternate Port and MSTP 802.1s?', '[{"id": "A", "text": "Alternate Port is backup to root port; blocked in steady state; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "B", "text": "Alternate Port is backup to root port; blocked in steady state; Edge Port is port connected to end host; immediate forwarding.", "is_correct": false}, {"id": "C", "text": "Alternate Port is backup to root port; blocked in steady state; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": true}, {"id": "D", "text": "Alternate Port is backup to root port; blocked in steady state; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}]', 'Alternate Port backup to root port; blocked in steady state. MSTP 802.1s multiple spanning tree instances with VLAN mapping.', '{}', 'STP Feature Comparison', 14.0, 'ea8425ef054f7dee_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaa62a56-f29d-49db-9895-c86891340aec', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Bridge ID and Rapid PVST+?', '[{"id": "A", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; BackboneFast is Cisco fast convergence after indirect link failure.", "is_correct": false}, {"id": "B", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}, {"id": "C", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}, {"id": "D", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": true}]', 'Bridge ID 8-byte ID: 2-byte priority + 6-byte MAC address. Rapid PVST+ Cisco per-VLAN RSTP.', '{}', 'STP Feature Comparison', 14.0, 'eb6b5d69891c4461_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c91ab79c-d334-4420-974a-6e68c9efc318', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Edge Port and Bridge ID?', '[{"id": "A", "text": "Edge Port is port connected to end host; immediate forwarding; BackboneFast is Cisco fast convergence after indirect link failure.", "is_correct": false}, {"id": "B", "text": "Edge Port is port connected to end host; immediate forwarding; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": false}, {"id": "C", "text": "Edge Port is port connected to end host; immediate forwarding; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": true}, {"id": "D", "text": "Edge Port is port connected to end host; immediate forwarding; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}]', 'Edge Port port connected to end host; immediate forwarding. Bridge ID 8-byte ID: 2-byte priority + 6-byte MAC address.', '{}', 'STP Feature Comparison', 14.0, 'eab6e9c2abe14e15_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d25f862-3373-4fb7-a871-25217f187487', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Designated Port and PortFast?', '[{"id": "A", "text": "Designated Port is best port on a link toward the root; one per segment; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "B", "text": "Designated Port is best port on a link toward the root; one per segment; PortFast is immediately transitions access port to forwarding.", "is_correct": true}, {"id": "C", "text": "Designated Port is best port on a link toward the root; one per segment; Root Guard is prevents receiving superior BPDUs on designated ports.", "is_correct": false}, {"id": "D", "text": "Designated Port is best port on a link toward the root; one per segment; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}]', 'Designated Port best port on a link toward the root; one per segment. PortFast immediately transitions access port to forwarding.', '{}', 'STP Feature Comparison', 14.0, '65befe7d3a89593f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72c7f6c6-42fc-404c-8bf4-3da3b7f86367', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Bridge and UplinkFast?', '[{"id": "A", "text": "Root Bridge is elected root of spanning tree; all ports are designated; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}, {"id": "B", "text": "Root Bridge is elected root of spanning tree; all ports are designated; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": true}, {"id": "C", "text": "Root Bridge is elected root of spanning tree; all ports are designated; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}, {"id": "D", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}]', 'Root Bridge elected root of spanning tree; all ports are designated. UplinkFast Cisco fast convergence on root port failure.', '{}', 'STP Feature Comparison', 14.0, '7c3b2e707b79ae13_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef5b2db9-090b-4e65-bf98-cbcfca683345', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Port and RSTP 802.1w?', '[{"id": "A", "text": "Root Port is best path to the root bridge; one per non-root switch; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": false}, {"id": "B", "text": "Root Port is best path to the root bridge; one per non-root switch; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": true}, {"id": "C", "text": "Root Port is best path to the root bridge; one per non-root switch; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": true}, {"id": "D", "text": "Root Port is best path to the root bridge; one per non-root switch; Backup Port is backup to designated port on shared segments.", "is_correct": false}]', 'Root Port best path to the root bridge; one per non-root switch. RSTP 802.1w rapid STP with discarding/learning/forwarding; fast convergence.', '{}', 'STP Feature Comparison', 14.0, 'f484d4ba7049397c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec68c3f4-3239-4954-b250-10cae439258f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BPDU Guard and Edge Port?', '[{"id": "A", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; PortFast is immediately transitions access port to forwarding.", "is_correct": false}, {"id": "B", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "C", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}, {"id": "D", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; Edge Port is port connected to end host; immediate forwarding.", "is_correct": true}]', 'BPDU Guard disables port if a BPDU is received on an edge port. Edge Port port connected to end host; immediate forwarding.', '{}', 'STP Feature Comparison', 14.0, '17d6031408d2a68a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8cdc1f9-4303-4bfd-bbf9-1f0641be7332', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Loop Guard and Edge Port?', '[{"id": "A", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Edge Port is port connected to end host; immediate forwarding.", "is_correct": true}, {"id": "B", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "C", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "D", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}]', 'Loop Guard prevents alternate/root ports from becoming designated if BPDUs stop. Edge Port port connected to end host; immediate forwarding.', '{}', 'STP Feature Comparison', 14.0, '0210c9877805b6d0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c5d67d8-5ef9-420a-aaee-68023b80cf6f', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Rapid PVST+ and Backup Port?', '[{"id": "A", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Backup Port is backup to designated port on shared segments.", "is_correct": true}, {"id": "B", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "C", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}, {"id": "D", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": false}]', 'Rapid PVST+ Cisco per-VLAN RSTP. Backup Port backup to designated port on shared segments.', '{}', 'STP Feature Comparison', 14.0, 'd96d739fb73aa292_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64c25b2c-81ec-4bb3-9a9d-94a1300dcf0a', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Bridge and Path Cost?', '[{"id": "A", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Path Cost is port cost toward the root bridge; inversely proportional to speed.", "is_correct": true}, {"id": "B", "text": "Root Bridge is elected root of spanning tree; all ports are designated; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "C", "text": "Root Bridge is elected root of spanning tree; all ports are designated; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": false}, {"id": "D", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}]', 'Root Bridge elected root of spanning tree; all ports are designated. Path Cost port cost toward the root bridge; inversely proportional to speed.', '{}', 'STP Feature Comparison', 14.0, '2010aa53d27658f5_gen_v6', true) ON CONFLICT (id) DO NOTHING;
