INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66b8e20d-b833-4112-a110-1c1b4b650d8e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Alternate Port and Root Bridge?', '[{"id": "A", "text": "Alternate Port is backup to root port; blocked in steady state; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "B", "text": "Alternate Port is backup to root port; blocked in steady state; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "C", "text": "Alternate Port is backup to root port; blocked in steady state; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": true}, {"id": "D", "text": "Alternate Port is backup to root port; blocked in steady state; Root Guard is prevents receiving superior BPDUs on designated ports.", "is_correct": false}]', 'Alternate Port backup to root port; blocked in steady state. Root Bridge elected root of spanning tree; all ports are designated.', '{}', 'STP Feature Comparison', 14.0, '54cb9ad8b9731428_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b93cac70-2c51-48f0-a481-504a98a7946b', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BackboneFast and Backup Port?', '[{"id": "A", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "B", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Backup Port is backup to designated port on shared segments.", "is_correct": true}, {"id": "C", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "D", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Edge Port is port connected to end host; immediate forwarding.", "is_correct": false}]', 'BackboneFast Cisco fast convergence after indirect link failure. Backup Port backup to designated port on shared segments.', '{}', 'STP Feature Comparison', 14.0, '6ca059306c448bea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
