INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('850bbc58-61b2-4617-bd1c-265d7345b053', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Interface flapping up and down. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "C", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "D", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": true}]', 'faulty SFP, cable issue, or speed/duplex mismatch. Use show interfaces, show interfaces diagnostics optics to diagnose.', '{}', 'Troubleshooting', 14.0, 'e7762a500dbd0227_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b70c085a-bab8-4e9e-9c09-262103e3f1e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('557e6df3-03ba-4471-9e76-5cba755bf5f0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "C", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d95195ec-5c78-4bc5-8b5a-aade91e9d173', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4907aa69-ff90-40f1-ba25-850cef0cd48e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "C", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3aa62fa5-ca54-40e9-86b4-b9a9f0c1fa03', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "B", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "C", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": true}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20887790-1143-4424-9d53-ac90611af6f2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LDP session flapping. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": true}, {"id": "B", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": false}]', 'hello interval mismatch or transport address unreachable. Use show ldp session, show route, ping transport-address to diagnose.', '{}', 'Troubleshooting', 14.0, '1bb56e98b1420486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('07774737-ac2e-4cd3-a395-17cdfbe20650', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}, {"id": "D", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6bfaacf2-0056-4286-9a9c-7169402844be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "C", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "D", "text": "attacker sending fake ARP replies", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9466ed84-fbaa-4407-a6b3-eb31129bf644', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: NAT not translating addresses. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": true}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "D", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}]', 'missing ip nat inside/outside interface or overload keyword. Use show ip nat translations, debug ip nat to diagnose.', '{}', 'Troubleshooting', 14.0, 'e36837feec2e6362_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('49f5b4fb-d82a-4e74-9be1-cda60636983c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1c8bbc6b-924e-4b3f-a6ae-92200d873fe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "D", "text": "missing LSP or label binding", "is_correct": true}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba13d08a-ae6c-4cb0-98e4-7127cc9830a1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "area ID mismatch or passive interface configuration", "is_correct": true}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae46060b-21a9-468e-a928-02d1ea900c4f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82cd3bac-2299-4b06-b25c-73b75d96b814', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "B", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "C", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "D", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dcad143-ab23-47b7-a32b-11189d538263', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": true}, {"id": "B", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "C", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "D", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f3308ec-0a4a-4ba9-97d9-ff89caa4b916', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: 802.1X authentication failing. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": true}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'RADIUS server unreachable or EAP type mismatch. Use show authentication sessions, debug radius authentication to diagnose.', '{}', 'Troubleshooting', 14.0, 'bafce4e1105d5d56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0ae942b-6e6e-4ca5-ad45-9f5df771ffac', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c799b241-2077-4871-a3ea-f48cb0823438', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98ea973b-91a8-4884-9cee-fbd48d4f9ffd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "missing underlay route or VNI configuration error", "is_correct": true}, {"id": "B", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('918ddb56-43fe-404e-8397-eea0b44f35b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "C", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0aa6ce7-a2a4-4ecd-a9b2-a1715a93e72c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": true}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be02d323-aea8-484a-8db2-51947777af45', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51a06613-e29c-433f-8593-f462ec7679af', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Firewall filter blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "term order incorrect or missing accept term", "is_correct": true}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'term order incorrect or missing accept term. Use show firewall log, show log messages, monitor traffic to diagnose.', '{}', 'Troubleshooting', 14.0, '4c7b5ac264d85a1c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6c0c954e-b415-457a-b10b-9ff3ce633f5e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00dd92c5-1ce9-44cb-885b-e5fbb5244520', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "LLDP disabled globally or per interface", "is_correct": true}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'LLDP disabled globally or per interface. Use show lldp, show lldp interface ge-0/0/0 to diagnose.', '{}', 'Troubleshooting', 14.0, '41d8508150266f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e6f396b-684c-4796-a90d-f60b7d330fbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "B", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26fdf536-ec3f-4493-9674-a8a0aa720235', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666d3e50-2eda-49ca-8dc0-fd941c2e5f95', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP server running out of addresses. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": true}, {"id": "D", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}]', 'lease time too long or subnet too small. Use show ip dhcp pool, show ip dhcp conflict to diagnose.', '{}', 'Troubleshooting', 14.0, '0be06d09ca787cdf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d1ae45cc-7272-4d1c-95e1-afb6437eb369', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3b619bb-8d47-4c28-aea4-cd1531ce47dc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}, {"id": "B", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7c58806c-6519-4d50-a6fa-0fcd5495a87d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "B", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0eb05c2e-ac14-4f98-a137-a096317b138d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "D", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cac584eb-74bb-4709-b2ce-da3b105dfd5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "D", "text": "too many concurrent translations exceeding pool size", "is_correct": false}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
