INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed7d6ae6-4641-4c7f-ad2e-929f61fad146', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between STP 802.1D and Edge Port?', '[{"id": "A", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Edge Port is port connected to end host; immediate forwarding.", "is_correct": true}, {"id": "B", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "C", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; BackboneFast is Cisco fast convergence after indirect link failure.", "is_correct": false}, {"id": "D", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}]', 'STP 802.1D spanning tree with blocking/listening/learning/forwarding; slow convergence. Edge Port port connected to end host; immediate forwarding.', '{}', 'STP Comparison', 14.0, 'fe1474beb91f0be5_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bcdbf6b-a642-43b8-8054-7fb54013ec7e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between UplinkFast and Alternate Port?', '[{"id": "A", "text": "UplinkFast is Cisco fast convergence on root port failure; Path Cost is port cost toward the root bridge; inversely proportional to speed.", "is_correct": false}, {"id": "B", "text": "UplinkFast is Cisco fast convergence on root port failure; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}, {"id": "C", "text": "UplinkFast is Cisco fast convergence on root port failure; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "D", "text": "UplinkFast is Cisco fast convergence on root port failure; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}]', 'UplinkFast Cisco fast convergence on root port failure. Alternate Port backup to root port; blocked in steady state.', '{}', 'STP Comparison', 14.0, '31bcf6a0fe27179c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2df7c476-6a8f-41c3-a070-3d2cac28145e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between RSTP 802.1w and UplinkFast?', '[{"id": "A", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}, {"id": "B", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": false}, {"id": "C", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}, {"id": "D", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": true}]', 'RSTP 802.1w rapid STP with discarding/learning/forwarding; fast convergence. UplinkFast Cisco fast convergence on root port failure.', '{}', 'STP Comparison', 14.0, '9d2f53f3b1dadfc6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e05538d-d168-4de7-9cc4-c29822d51fe4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between Backup Port and MSTP 802.1s?', '[{"id": "A", "text": "Backup Port is backup to designated port on shared segments; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": false}, {"id": "B", "text": "Backup Port is backup to designated port on shared segments; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "C", "text": "Backup Port is backup to designated port on shared segments; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": true}, {"id": "D", "text": "Backup Port is backup to designated port on shared segments; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}]', 'Backup Port backup to designated port on shared segments. MSTP 802.1s multiple spanning tree instances with VLAN mapping.', '{}', 'STP Comparison', 14.0, 'ebcf8fa70180c44d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8eb4113-cd5b-4170-819c-f00136eac204', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between BackboneFast and Root Guard?', '[{"id": "A", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Root Guard is prevents receiving superior BPDUs on designated ports.", "is_correct": true}, {"id": "B", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Path Cost is port cost toward the root bridge; inversely proportional to speed.", "is_correct": false}, {"id": "C", "text": "BackboneFast is Cisco fast convergence after indirect link failure; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": false}, {"id": "D", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}]', 'BackboneFast Cisco fast convergence after indirect link failure. Root Guard prevents receiving superior BPDUs on designated ports.', '{}', 'STP Comparison', 14.0, '17c84352dc285cbc_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54c47a13-227c-4996-b59a-7e53c9c039e3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between MSTP 802.1s and Rapid PVST+?', '[{"id": "A", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": true}, {"id": "B", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "C", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}, {"id": "D", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}]', 'MSTP 802.1s multiple spanning tree instances with VLAN mapping. Rapid PVST+ Cisco per-VLAN RSTP.', '{}', 'STP Comparison', 14.0, '0044ace8d8019a50_gen_v6', true) ON CONFLICT (id) DO NOTHING;
