INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4eb5a1f4-dc9a-46d2-9639-271647abdb2b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between Rapid PVST+ and Backup Port?', '[{"id": "A", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Backup Port is backup to designated port on shared segments.", "is_correct": true}, {"id": "B", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "C", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "D", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; PortFast is immediately transitions access port to forwarding.", "is_correct": false}]', 'Rapid PVST+ Cisco per-VLAN RSTP. Backup Port backup to designated port on shared segments.', '{}', 'STP Comparison', 14.0, 'd96d739fb73aa292_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f16ba8b-5aef-41b9-b8a4-29734ef3dbfd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between RSTP 802.1w and BPDU Guard?', '[{"id": "A", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": true}, {"id": "B", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "C", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": false}, {"id": "D", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}]', 'RSTP 802.1w rapid STP with discarding/learning/forwarding; fast convergence. BPDU Guard disables port if a BPDU is received on an edge port.', '{}', 'STP Comparison', 14.0, 'fc80ac93f5c79092_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd45b70c-ee2a-48f1-a523-2f975bb73ee9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between PortFast and Alternate Port?', '[{"id": "A", "text": "PortFast is immediately transitions access port to forwarding; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": false}, {"id": "B", "text": "PortFast is immediately transitions access port to forwarding; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "C", "text": "PortFast is immediately transitions access port to forwarding; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}, {"id": "D", "text": "PortFast is immediately transitions access port to forwarding; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}]', 'PortFast immediately transitions access port to forwarding. Alternate Port backup to root port; blocked in steady state.', '{}', 'STP Comparison', 14.0, 'fbda9610907bc734_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cc82ac2e-e87d-42cd-ada6-9c2ea409b597', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', 'What is the difference between Path Cost and Backup Port?', '[{"id": "A", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Backup Port is backup to designated port on shared segments.", "is_correct": true}, {"id": "B", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}, {"id": "C", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": false}, {"id": "D", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}]', 'Path Cost port cost toward the root bridge; inversely proportional to speed. Backup Port backup to designated port on shared segments.', '{}', 'STP Comparison', 14.0, '7b1460f2019d69e2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
