INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f0dfcdc-87ea-4423-be1d-d884710e712f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'To diagnose ''Security policy blocking traffic'', which tool or command should be used?', '[{"id": "A", "text": "show ipv6 interface, debug ipv6 nd", "is_correct": false}, {"id": "B", "text": "show security policies, show security flow session", "is_correct": true}, {"id": "C", "text": "show ip dhcp pool, show ip dhcp conflict", "is_correct": false}, {"id": "D", "text": "show processes cpu, show log, show ip bgp summary", "is_correct": false}]', 'Use show security policies, show security flow session to check missing policy or wrong zone-pair configuration.', '{}', 'Cisco Troubleshooting', 14.0, 'd84102dcdfb31d98_gen_v6', true) ON CONFLICT (id) DO NOTHING;
