INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9ab2aa3-70a2-433b-a86d-af81dcc7fa34', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show ip ospf virtual-links and show ip interface brief?', '[{"id": "A", "text": "show ip ospf virtual-links is displays OSPF virtual link status; show ip interface brief is displays summary of IP interface status.", "is_correct": true}, {"id": "B", "text": "show ip ospf virtual-links is displays OSPF virtual link status; show mpls ldp neighbor is displays LDP neighbors.", "is_correct": false}, {"id": "C", "text": "show ip ospf virtual-links is displays OSPF virtual link status; debug ip ospf adj is displays real-time OSPF adjacency events.", "is_correct": false}, {"id": "D", "text": "show ip ospf virtual-links is displays OSPF virtual link status; show ip nat translations is displays active NAT translations.", "is_correct": false}]', 'show ip ospf virtual-links displays OSPF virtual link status. show ip interface brief displays summary of IP interface status.', '{}', 'Command Comparison', 14.0, 'cf4847521bb3b778_gen_v6', true) ON CONFLICT (id) DO NOTHING;
