INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4337c91f-7fd5-45ce-ad10-05473d8c5e55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show environment all and show ip device tracking?', '[{"id": "A", "text": "show environment all is displays environmental status (power, fans, temp); show ip device tracking is displays IP device tracking entries for IP source guard.", "is_correct": true}, {"id": "B", "text": "show environment all is displays environmental status (power, fans, temp); show ipv6 route is displays IPv6 routing table.", "is_correct": false}, {"id": "C", "text": "show environment all is displays environmental status (power, fans, temp); show ip arp is displays the ARP cache.", "is_correct": false}, {"id": "D", "text": "show environment all is displays environmental status (power, fans, temp); show ip route ospf is displays OSPF-learned routes only.", "is_correct": false}]', 'show environment all displays environmental status (power, fans, temp). show ip device tracking displays IP device tracking entries for IP source guard.', '{}', 'Command Comparison', 14.0, '0542603197f42192_gen_v6', true) ON CONFLICT (id) DO NOTHING;
