INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3820c1bd-c218-4f61-93a8-f93552a914b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show ip access-lists and show etherchannel summary?', '[{"id": "A", "text": "show ip access-lists is displays access-list configuration and hit counts; show etherchannel summary is displays EtherChannel (LACP) status.", "is_correct": true}, {"id": "B", "text": "show ip access-lists is displays access-list configuration and hit counts; show ip interface brief is displays summary of IP interface status.", "is_correct": false}, {"id": "C", "text": "show ip access-lists is displays access-list configuration and hit counts; show port-security is displays port security configuration and violations.", "is_correct": false}, {"id": "D", "text": "show ip access-lists is displays access-list configuration and hit counts; show mpls forwarding-table is displays MPLS label forwarding table.", "is_correct": false}]', 'show ip access-lists displays access-list configuration and hit counts. show etherchannel summary displays EtherChannel (LACP) status.', '{}', 'Command Comparison', 14.0, '000713cd98598a92_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f1a95fda-82c5-4747-925d-1c8eb8e85c0c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show ip device tracking and show ip ssh?', '[{"id": "A", "text": "show ip device tracking is displays IP device tracking entries for IP source guard; show ip ospf virtual-links is displays OSPF virtual link status.", "is_correct": false}, {"id": "B", "text": "show ip device tracking is displays IP device tracking entries for IP source guard; show ip protocols is displays routing protocol status and timers.", "is_correct": false}, {"id": "C", "text": "show ip device tracking is displays IP device tracking entries for IP source guard; show ip ssh is displays SSH server status and version.", "is_correct": true}, {"id": "D", "text": "show ip device tracking is displays IP device tracking entries for IP source guard; show ip ospf database is displays the OSPF link-state database.", "is_correct": false}]', 'show ip device tracking displays IP device tracking entries for IP source guard. show ip ssh displays SSH server status and version.', '{}', 'Command Comparison', 14.0, 'ef5f010f32ac0800_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('246f0025-4d52-4d13-943b-1c9a1c8bcb75', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show crypto isakmp sa and show policy-map interface gigabitethernet0/1?', '[{"id": "A", "text": "show crypto isakmp sa is displays IKE security associations; show policy-map interface gigabitethernet0/1 is displays QoS policy statistics on interface.", "is_correct": true}, {"id": "B", "text": "show crypto isakmp sa is displays IKE security associations; show flash: is displays flash file system contents.", "is_correct": false}, {"id": "C", "text": "show crypto isakmp sa is displays IKE security associations; show ip ospf neighbor is displays OSPF neighbor adjacencies.", "is_correct": false}, {"id": "D", "text": "show crypto isakmp sa is displays IKE security associations; show ip bgp summary is displays BGP neighbor summary.", "is_correct": false}]', 'show crypto isakmp sa displays IKE security associations. show policy-map interface gigabitethernet0/1 displays QoS policy statistics on interface.', '{}', 'Command Comparison', 14.0, '469c2d7a705b11d5_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e8dd7a1-d6fd-42b1-b895-ee4b52052e5f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show version and show ipv6 ospf neighbor?', '[{"id": "A", "text": "show version is displays IOS version, uptime, and hardware info; show ipv6 ospf neighbor is displays OSPFv3 neighbors.", "is_correct": true}, {"id": "B", "text": "show version is displays IOS version, uptime, and hardware info; show ip route is displays the IPv4 routing table.", "is_correct": false}, {"id": "C", "text": "show version is displays IOS version, uptime, and hardware info; show startup-config is displays saved startup configuration in NVRAM.", "is_correct": false}, {"id": "D", "text": "show version is displays IOS version, uptime, and hardware info; debug ip bgp updates is displays real-time BGP update messages.", "is_correct": false}]', 'show version displays IOS version, uptime, and hardware info. show ipv6 ospf neighbor displays OSPFv3 neighbors.', '{}', 'Command Comparison', 14.0, '743455b0b0e5c9e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
