INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c823dc54-19ee-4be7-ad8d-b7d02e66b7e2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show inventory and show ip interface brief?', '[{"id": "A", "text": "show inventory is displays hardware inventory with serial numbers; show ip interface brief is displays summary of IP interface status.", "is_correct": true}, {"id": "B", "text": "show inventory is displays hardware inventory with serial numbers; show clock is displays system clock and timezone.", "is_correct": false}, {"id": "C", "text": "show inventory is displays hardware inventory with serial numbers; show ip ospf database is displays the OSPF link-state database.", "is_correct": false}, {"id": "D", "text": "show inventory is displays hardware inventory with serial numbers; show crypto isakmp sa is displays IKE security associations.", "is_correct": false}]', 'show inventory displays hardware inventory with serial numbers. show ip interface brief displays summary of IP interface status.', '{}', 'Command Comparison', 14.0, '4121df3713d88cc1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3091d0e5-dec7-40c4-bda2-f3ec60e8d1db', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show ip protocols and show ip eigrp neighbors?', '[{"id": "A", "text": "show ip protocols is displays routing protocol status and timers; debug ip ospf adj is displays real-time OSPF adjacency events.", "is_correct": false}, {"id": "B", "text": "show ip protocols is displays routing protocol status and timers; show spanning-tree is displays spanning-tree topology and port roles.", "is_correct": false}, {"id": "C", "text": "show ip protocols is displays routing protocol status and timers; debug ip bgp updates is displays real-time BGP update messages.", "is_correct": false}, {"id": "D", "text": "show ip protocols is displays routing protocol status and timers; show ip eigrp neighbors is displays EIGRP neighbor table.", "is_correct": true}]', 'show ip protocols displays routing protocol status and timers. show ip eigrp neighbors displays EIGRP neighbor table.', '{}', 'Command Comparison', 14.0, 'ac86e6bfb5499a5f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cdc2048-b45a-4783-92d9-eaf115d9cf2d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between show interfaces and debug ip bgp updates?', '[{"id": "A", "text": "show interfaces is displays all interface status/counters; show ipv6 ospf neighbor is displays OSPFv3 neighbors.", "is_correct": false}, {"id": "B", "text": "show interfaces is displays all interface status/counters; show ip eigrp neighbors is displays EIGRP neighbor table.", "is_correct": false}, {"id": "C", "text": "show interfaces is displays all interface status/counters; debug ip bgp updates is displays real-time BGP update messages.", "is_correct": true}, {"id": "D", "text": "show interfaces is displays all interface status/counters; show mac address-table is displays CAM table with MAC-to-port mappings.", "is_correct": false}]', 'show interfaces displays all interface status/counters. debug ip bgp updates displays real-time BGP update messages.', '{}', 'Command Comparison', 14.0, '5414fffe3d3c7f44_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b3ba00f-8af7-44ed-8b20-380326f1afe3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Trunking and Floating Static Route?', '[{"id": "A", "text": "Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging; ARP is resolving IPv4 addresses to MAC addresses on broadcast segments.", "is_correct": false}, {"id": "B", "text": "Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging; EtherChannel is link aggregation bundling multiple physical links into one logical link.", "is_correct": false}, {"id": "C", "text": "Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging; Floating Static Route is static route with higher AD for backup path.", "is_correct": true}, {"id": "D", "text": "Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging; NTP is time synchronization across network infrastructure.", "is_correct": false}]', 'Trunking carrying multiple VLAN frames over a single link with 802.1Q tagging. Floating Static Route static route with higher AD for backup path.', '{}', 'Network Concept Comparison', 14.0, '5e4a004afae33014_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a5639e0-d442-43a4-a969-4f3f838fa9b2', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between IPSLA and UDLD?', '[{"id": "A", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); Syslog is centralized logging for network device events.", "is_correct": false}, {"id": "B", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": true}, {"id": "C", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": true}, {"id": "D", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); IP SLA is measure network performance metrics (latency, jitter, loss).", "is_correct": false}]', 'IPSLA Cisco IP SLA for performance measurement (latency, jitter, loss). UDLD UniDirectional Link Detection for fiber link monitoring.', '{}', 'Network Concept Comparison', 14.0, '6c991616fe5c5897_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a6826b1-aa4d-4f8d-9af3-067781d30093', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CIS and LACP?', '[{"id": "A", "text": "CIS is Cisco ISE; identity services engine for policy enforcement; TrustSec is Cisco security group tagging for role-based access control.", "is_correct": false}, {"id": "B", "text": "CIS is Cisco ISE; identity services engine for policy enforcement; IPFIX is NetFlow v10 standardized flow export protocol.", "is_correct": false}, {"id": "C", "text": "CIS is Cisco ISE; identity services engine for policy enforcement; LACP is Link Aggregation Control Protocol for dynamic port bundling.", "is_correct": true}, {"id": "D", "text": "CIS is Cisco ISE; identity services engine for policy enforcement; CoS is Layer 2 class of service using 802.1p priority bits.", "is_correct": false}]', 'CIS Cisco ISE; identity services engine for policy enforcement. LACP Link Aggregation Control Protocol for dynamic port bundling.', '{}', 'Network Concept Comparison', 14.0, 'a8cb0041194299bf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9f1faf2-8f25-4155-839e-739aaa2a6387', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between vPC and SGT?', '[{"id": "A", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; ARP is resolving IPv4 addresses to MAC addresses on broadcast segments.", "is_correct": false}, {"id": "B", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; NTP is time synchronization across network infrastructure.", "is_correct": false}, {"id": "C", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": false}, {"id": "D", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; SGT is Security Group Tag for Cisco TrustSec policy enforcement.", "is_correct": true}]', 'vPC virtual Port Channel for cross-chassis multi-homing. SGT Security Group Tag for Cisco TrustSec policy enforcement.', '{}', 'Network Concept Comparison', 14.0, 'a3b7b2d3fcbf73bb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef2a334-1c9d-43a9-bfe8-facc4234996a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between LACP and FEX?', '[{"id": "A", "text": "LACP is Link Aggregation Control Protocol for dynamic port bundling; TRILL is transparent interconnection of lots of links for Layer 2 multipathing.", "is_correct": false}, {"id": "B", "text": "LACP is Link Aggregation Control Protocol for dynamic port bundling; RSTP is rapid STP with fast convergence using port roles and proposal-agreement.", "is_correct": false}, {"id": "C", "text": "LACP is Link Aggregation Control Protocol for dynamic port bundling; MAB is MAC Authentication Bypass for 802.1X incapable devices.", "is_correct": false}, {"id": "D", "text": "LACP is Link Aggregation Control Protocol for dynamic port bundling; FEX is Cisco Fabric Extender for remote line card connectivity.", "is_correct": true}]', 'LACP Link Aggregation Control Protocol for dynamic port bundling. FEX Cisco Fabric Extender for remote line card connectivity.', '{}', 'Network Concept Comparison', 14.0, '6ac062f4252359f2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0415b658-7cc4-4ce1-837c-af4ba53ea5b8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between ACL and CWMP/TR-069?', '[{"id": "A", "text": "ACL is access control list filtering traffic by IP, port, and protocol; CWMP/TR-069 is CPE WAN management protocol for auto-configuration.", "is_correct": true}, {"id": "B", "text": "ACL is access control list filtering traffic by IP, port, and protocol; IPFIX is NetFlow v10 standardized flow export protocol.", "is_correct": false}, {"id": "C", "text": "ACL is access control list filtering traffic by IP, port, and protocol; RADIUS is UDP-based AAA protocol for network access control.", "is_correct": false}, {"id": "D", "text": "ACL is access control list filtering traffic by IP, port, and protocol; AAA is authentication, authorization, and accounting framework.", "is_correct": false}]', 'ACL access control list filtering traffic by IP, port, and protocol. CWMP/TR-069 CPE WAN management protocol for auto-configuration.', '{}', 'Network Concept Comparison', 14.0, 'd79ee51c644fb59f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e7290a6d-1abe-4c11-b473-628e656b061d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between VPC and MAB?', '[{"id": "A", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; vPC is virtual Port Channel for cross-chassis multi-homing.", "is_correct": false}, {"id": "B", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; SNMPv3 is SNMP with encryption and authentication security.", "is_correct": false}, {"id": "C", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; MAB is MAC Authentication Bypass for 802.1X incapable devices.", "is_correct": true}, {"id": "D", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; FHRP is first-hop redundancy for default gateway high availability.", "is_correct": false}]', 'VPC virtual Port Channel for cross-chassis multi-homing on NX-OS. MAB MAC Authentication Bypass for 802.1X incapable devices.', '{}', 'Network Concept Comparison', 14.0, 'da67627dcb05b97e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8880b417-cc96-4a94-bd00-a09355c3fda8', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between TRILL and EIGRP?', '[{"id": "A", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; EIGRP is Cisco hybrid routing protocol using DUAL algorithm.", "is_correct": true}, {"id": "B", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; LISP is Locator/ID Separation Protocol for routing scalability.", "is_correct": false}, {"id": "C", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; STP Guard is BPDU guard, root guard, and loop guard protections.", "is_correct": false}, {"id": "D", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; EIGRP is Cisco hybrid routing protocol using DUAL algorithm.", "is_correct": true}]', 'TRILL transparent interconnection of lots of links for Layer 2 multipathing. EIGRP Cisco hybrid routing protocol using DUAL algorithm.', '{}', 'Network Concept Comparison', 14.0, '141ad384ed724a11_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddcfcd2c-b239-4463-8601-61dcb4e53cc1', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Switching and VTP?', '[{"id": "A", "text": "Switching is forwarding frames within a network based on destination MAC; WFQ is Weighted Fair Queueing providing fair bandwidth allocation.", "is_correct": false}, {"id": "B", "text": "Switching is forwarding frames within a network based on destination MAC; Floating Static Route is static route with higher AD for backup path.", "is_correct": false}, {"id": "C", "text": "Switching is forwarding frames within a network based on destination MAC; VTP is VLAN Trunking Protocol for VLAN database synchronization.", "is_correct": true}, {"id": "D", "text": "Switching is forwarding frames within a network based on destination MAC; STP Guard is BPDU guard, root guard, and loop guard protections.", "is_correct": false}]', 'Switching forwarding frames within a network based on destination MAC. VTP VLAN Trunking Protocol for VLAN database synchronization.', '{}', 'Network Concept Comparison', 14.0, 'c6adadf7363e9f62_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f444f58-dede-4745-b286-2c4fc6f48476', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between PoE+ and YANG?', '[{"id": "A", "text": "PoE+ is IEEE 802.3at PoE with 30W per port; YANG is data modeling language for network configuration and state.", "is_correct": true}, {"id": "B", "text": "PoE+ is IEEE 802.3at PoE with 30W per port; Route Redistribution is importing routes from one routing protocol into another.", "is_correct": false}, {"id": "C", "text": "PoE+ is IEEE 802.3at PoE with 30W per port; Route Summarization is aggregating multiple prefixes into a shorter prefix.", "is_correct": false}, {"id": "D", "text": "PoE+ is IEEE 802.3at PoE with 30W per port; FHRP is first-hop redundancy for default gateway high availability.", "is_correct": false}]', 'PoE+ IEEE 802.3at PoE with 30W per port. YANG data modeling language for network configuration and state.', '{}', 'Network Concept Comparison', 14.0, '5db205ef14cc659a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43f8729c-063b-4099-9a7b-3d32f34148ba', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between NetFlow and Chef?', '[{"id": "A", "text": "NetFlow is Cisco IP traffic flow monitoring and export; GMPLS is Generalized MPLS for optical and TDM network control.", "is_correct": false}, {"id": "B", "text": "NetFlow is Cisco IP traffic flow monitoring and export; RSVP-TE is RSVP with traffic engineering for constraint-based MPLS LSP setup.", "is_correct": false}, {"id": "C", "text": "NetFlow is Cisco IP traffic flow monitoring and export; Chef is configuration management using Ruby DSL cookbooks.", "is_correct": true}, {"id": "D", "text": "NetFlow is Cisco IP traffic flow monitoring and export; Route Redistribution is importing routes from one routing protocol into another.", "is_correct": false}]', 'NetFlow Cisco IP traffic flow monitoring and export. Chef configuration management using Ruby DSL cookbooks.', '{}', 'Network Concept Comparison', 14.0, '974bf2e18340d287_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8cc11d59-0e20-4411-acad-f7259cebc3fd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Ansible and MAB?', '[{"id": "A", "text": "Ansible is agentless automation tool using YAML playbooks; MAB is MAC Authentication Bypass for 802.1X incapable devices.", "is_correct": true}, {"id": "B", "text": "Ansible is agentless automation tool using YAML playbooks; IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss).", "is_correct": false}, {"id": "C", "text": "Ansible is agentless automation tool using YAML playbooks; VPN is securely extending a private network across a public infrastructure.", "is_correct": false}, {"id": "D", "text": "Ansible is agentless automation tool using YAML playbooks; DHCP Snooping is man-in-the-middle attack prevention by filtering DHCP messages.", "is_correct": false}]', 'Ansible agentless automation tool using YAML playbooks. MAB MAC Authentication Bypass for 802.1X incapable devices.', '{}', 'Network Concept Comparison', 14.0, '36271a54b4fe80e7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('511c958c-e29e-4ee1-9760-04f3de641293', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SDN and LLQ?', '[{"id": "A", "text": "SDN is software-defined networking decoupling control and data planes; DHCP Snooping is man-in-the-middle attack prevention by filtering DHCP messages.", "is_correct": false}, {"id": "B", "text": "SDN is software-defined networking decoupling control and data planes; MAB is MAC Authentication Bypass for 802.1X incapable devices.", "is_correct": false}, {"id": "C", "text": "SDN is software-defined networking decoupling control and data planes; LLQ is Low Latency Queueing for real-time traffic guaranteed bandwidth.", "is_correct": true}, {"id": "D", "text": "SDN is software-defined networking decoupling control and data planes; VTP is VLAN Trunking Protocol for VLAN database synchronization.", "is_correct": false}]', 'SDN software-defined networking decoupling control and data planes. LLQ Low Latency Queueing for real-time traffic guaranteed bandwidth.', '{}', 'Network Concept Comparison', 14.0, 'ed80577a37e55636_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('063c22eb-80a9-4913-b6dc-bcddbf88ee98', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Chef and EIGRP?', '[{"id": "A", "text": "Chef is configuration management using Ruby DSL cookbooks; CIS is Cisco ISE; identity services engine for policy enforcement.", "is_correct": false}, {"id": "B", "text": "Chef is configuration management using Ruby DSL cookbooks; EVPN is control plane for VXLAN using MP-BGP for MAC/VNI distribution.", "is_correct": false}, {"id": "C", "text": "Chef is configuration management using Ruby DSL cookbooks; EIGRP is Cisco hybrid routing protocol using DUAL algorithm.", "is_correct": true}, {"id": "D", "text": "Chef is configuration management using Ruby DSL cookbooks; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}]', 'Chef configuration management using Ruby DSL cookbooks. EIGRP Cisco hybrid routing protocol using DUAL algorithm.', '{}', 'Network Concept Comparison', 14.0, '8c9e1f6f2ecc661e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7a0498df-12a9-436c-b9f6-e62c433804cd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CBWFQ and NetFlow?', '[{"id": "A", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; NetFlow is Cisco IP traffic flow monitoring and export.", "is_correct": true}, {"id": "B", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; NFV is virtualizing network functions on commodity hardware.", "is_correct": false}, {"id": "C", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; VSS is Cisco Virtual Switching System combining two 6500 chassis.", "is_correct": false}, {"id": "D", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; SSL VPN is VPN using TLS for web-based remote access.", "is_correct": false}]', 'CBWFQ Class-Based Weighted Fair Queueing for per-class bandwidth guarantees. NetFlow Cisco IP traffic flow monitoring and export.', '{}', 'Network Concept Comparison', 14.0, '95906eb0af3c5280_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('590b9a7c-7e52-47b7-84e8-634d62773dbb', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between FEX and NTP?', '[{"id": "A", "text": "FEX is Cisco Fabric Extender for remote line card connectivity; VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3.", "is_correct": false}, {"id": "B", "text": "FEX is Cisco Fabric Extender for remote line card connectivity; SGT is Security Group Tag for Cisco TrustSec policy enforcement.", "is_correct": false}, {"id": "C", "text": "FEX is Cisco Fabric Extender for remote line card connectivity; NTP is time synchronization across network infrastructure.", "is_correct": true}, {"id": "D", "text": "FEX is Cisco Fabric Extender for remote line card connectivity; DHCP is automatically assigning IP configuration to hosts.", "is_correct": false}]', 'FEX Cisco Fabric Extender for remote line card connectivity. NTP time synchronization across network infrastructure.', '{}', 'Network Concept Comparison', 14.0, '9fae54880cd9348d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5cde904-cedc-4b7f-8153-51bf51e9e2ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between BFD and SGT?', '[{"id": "A", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; SGT is Security Group Tag for Cisco TrustSec policy enforcement.", "is_correct": true}, {"id": "B", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}, {"id": "C", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; PoE is Power over Ethernet delivering power over data cables.", "is_correct": false}, {"id": "D", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3.", "is_correct": false}]', 'BFD Bidirectional Forwarding Detection for sub-second failure detection. SGT Security Group Tag for Cisco TrustSec policy enforcement.', '{}', 'Network Concept Comparison', 14.0, '6d6a238a0b52dba1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e13608d6-d172-46e0-840b-754dc3177121', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CWMP/TR-069 and VPC?', '[{"id": "A", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; PoE+ is IEEE 802.3at PoE with 30W per port.", "is_correct": false}, {"id": "B", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS.", "is_correct": true}, {"id": "C", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; Ansible is agentless automation tool using YAML playbooks.", "is_correct": false}, {"id": "D", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; SPB is Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.", "is_correct": false}]', 'CWMP/TR-069 CPE WAN management protocol for auto-configuration. VPC virtual Port Channel for cross-chassis multi-homing on NX-OS.', '{}', 'Network Concept Comparison', 14.0, 'e9c5d9191b576ceb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('03cda9f4-17d0-4f36-a3ce-da1184882dcc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Port Security and QoS?', '[{"id": "A", "text": "Port Security is restricting MAC addresses allowed on a switch port; QoS is prioritizing certain traffic classes over others.", "is_correct": true}, {"id": "B", "text": "Port Security is restricting MAC addresses allowed on a switch port; ARP is resolving IPv4 addresses to MAC addresses on broadcast segments.", "is_correct": false}, {"id": "C", "text": "Port Security is restricting MAC addresses allowed on a switch port; SPB is Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.", "is_correct": false}, {"id": "D", "text": "Port Security is restricting MAC addresses allowed on a switch port; Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging.", "is_correct": false}]', 'Port Security restricting MAC addresses allowed on a switch port. QoS prioritizing certain traffic classes over others.', '{}', 'Network Concept Comparison', 14.0, 'd9b5a6035f17fffc_gen_v6', true) ON CONFLICT (id) DO NOTHING;
