INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce5e009d-39b2-4fd7-bb68-19577bd38542', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between NetFlow and SSH?', '[{"id": "A", "text": "NetFlow is Cisco flow monitoring exporting IP traffic metadata; SSH is encrypted remote access protocol for CLI management.", "is_correct": true}, {"id": "B", "text": "NetFlow is Cisco flow monitoring exporting IP traffic metadata; UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": false}, {"id": "C", "text": "NetFlow is Cisco flow monitoring exporting IP traffic metadata; EIGRP is Cisco hybrid routing protocol using DUAL algorithm.", "is_correct": false}, {"id": "D", "text": "NetFlow is Cisco flow monitoring exporting IP traffic metadata; FHRP is first-hop redundancy for default gateway high availability.", "is_correct": false}]', 'NetFlow Cisco flow monitoring exporting IP traffic metadata. SSH encrypted remote access protocol for CLI management.', '{}', 'Network Concept Comparison', 14.0, '44ee9695cb307f33_gen_v6', true) ON CONFLICT (id) DO NOTHING;
