INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ddb5e79a-63b6-4a25-a68c-426ca9980104', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CWMP/TR-069 and AAA?', '[{"id": "A", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; IPS is intrusion prevention system inspecting traffic for threats.", "is_correct": false}, {"id": "B", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; DTP is Dynamic Trunking Protocol for automatic trunk negotiation.", "is_correct": false}, {"id": "C", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}, {"id": "D", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; AAA is authentication, authorization, and accounting framework.", "is_correct": true}]', 'CWMP/TR-069 CPE WAN management protocol for auto-configuration. AAA authentication, authorization, and accounting framework.', '{}', 'Network Concept Comparison', 14.0, 'bc2ff12d287d5df3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28848e8-5ec6-45e2-bd87-24833106f2b9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between FHRP and BGP?', '[{"id": "A", "text": "FHRP is first-hop redundancy for default gateway high availability; Port Security is restricting MAC addresses allowed on a switch port.", "is_correct": false}, {"id": "B", "text": "FHRP is first-hop redundancy for default gateway high availability; SNMPv3 is SNMP with encryption and authentication security.", "is_correct": false}, {"id": "C", "text": "FHRP is first-hop redundancy for default gateway high availability; BGP is exchanging routing information between autonomous systems.", "is_correct": true}, {"id": "D", "text": "FHRP is first-hop redundancy for default gateway high availability; QoS is prioritizing certain traffic classes over others.", "is_correct": false}]', 'FHRP first-hop redundancy for default gateway high availability. BGP exchanging routing information between autonomous systems.', '{}', 'Network Concept Comparison', 14.0, '46ff019703eb215c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b0864ce-122e-41f0-b7d1-d817b28d4e6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CoS and Switching?', '[{"id": "A", "text": "CoS is Layer 2 class of service using 802.1p priority bits; Trunking is carrying multiple VLAN frames over a single link with 802.1Q tagging.", "is_correct": false}, {"id": "B", "text": "CoS is Layer 2 class of service using 802.1p priority bits; FlexLinks is Cisco failover mechanism for dual-homed access.", "is_correct": false}, {"id": "C", "text": "CoS is Layer 2 class of service using 802.1p priority bits; SPB is Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.", "is_correct": false}, {"id": "D", "text": "CoS is Layer 2 class of service using 802.1p priority bits; Switching is forwarding frames within a network based on destination MAC.", "is_correct": true}]', 'CoS Layer 2 class of service using 802.1p priority bits. Switching forwarding frames within a network based on destination MAC.', '{}', 'Network Concept Comparison', 14.0, '699587b322ce73fe_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c912fbc5-2407-47cc-ab4a-a4655683275a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Route Redistribution and NetFlow?', '[{"id": "A", "text": "Route Redistribution is importing routes from one routing protocol into another; FEX is Cisco Fabric Extender for remote line card connectivity.", "is_correct": false}, {"id": "B", "text": "Route Redistribution is importing routes from one routing protocol into another; TWAMP is Two-Way Active Measurement Protocol for network performance.", "is_correct": false}, {"id": "C", "text": "Route Redistribution is importing routes from one routing protocol into another; OAM is Operations, Administration, and Management for network OAM.", "is_correct": false}, {"id": "D", "text": "Route Redistribution is importing routes from one routing protocol into another; NetFlow is Cisco IP traffic flow monitoring and export.", "is_correct": true}]', 'Route Redistribution importing routes from one routing protocol into another. NetFlow Cisco IP traffic flow monitoring and export.', '{}', 'Network Concept Comparison', 14.0, '8175e84e78809c8f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50ffae80-1517-4e40-a520-ef77ee3f358a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Policy-Based Routing and IPSLA?', '[{"id": "A", "text": "Policy-Based Routing is forwarding based on policies other than destination IP; TWAMP is Two-Way Active Measurement Protocol for network performance.", "is_correct": false}, {"id": "B", "text": "Policy-Based Routing is forwarding based on policies other than destination IP; IPS is intrusion prevention system inspecting traffic for threats.", "is_correct": false}, {"id": "C", "text": "Policy-Based Routing is forwarding based on policies other than destination IP; IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss).", "is_correct": true}, {"id": "D", "text": "Policy-Based Routing is forwarding based on policies other than destination IP; VPN is securely extending a private network across a public infrastructure.", "is_correct": false}]', 'Policy-Based Routing forwarding based on policies other than destination IP. IPSLA Cisco IP SLA for performance measurement (latency, jitter, loss).', '{}', 'Network Concept Comparison', 14.0, '76175c2b65f87c15_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3736e505-0d95-4a43-a9d9-70e5b68e02df', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between TrustSec and VTEP?', '[{"id": "A", "text": "TrustSec is Cisco security group tagging for role-based access control; vPC is virtual Port Channel for cross-chassis multi-homing.", "is_correct": false}, {"id": "B", "text": "TrustSec is Cisco security group tagging for role-based access control; VTEP is VXLAN tunnel endpoint performing encapsulation and decapsulation.", "is_correct": true}, {"id": "C", "text": "TrustSec is Cisco security group tagging for role-based access control; VPN is securely extending a private network across a public infrastructure.", "is_correct": false}, {"id": "D", "text": "TrustSec is Cisco security group tagging for role-based access control; HSRP is Cisco active/standby gateway redundancy.", "is_correct": false}]', 'TrustSec Cisco security group tagging for role-based access control. VTEP VXLAN tunnel endpoint performing encapsulation and decapsulation.', '{}', 'Network Concept Comparison', 14.0, 'feee1b5f218865b7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fafb203-4ced-4133-bd86-4abf0505971a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SDN and vPC?', '[{"id": "A", "text": "SDN is software-defined networking decoupling control and data planes; vPC is virtual Port Channel for cross-chassis multi-homing.", "is_correct": true}, {"id": "B", "text": "SDN is software-defined networking decoupling control and data planes; GETVPN is Group Encrypted Transport VPN with any-to-any connectivity.", "is_correct": false}, {"id": "C", "text": "SDN is software-defined networking decoupling control and data planes; Policy-Based Routing is forwarding based on policies other than destination IP.", "is_correct": false}, {"id": "D", "text": "SDN is software-defined networking decoupling control and data planes; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}]', 'SDN software-defined networking decoupling control and data planes. vPC virtual Port Channel for cross-chassis multi-homing.', '{}', 'Network Concept Comparison', 14.0, 'dc560cff37566515_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9169514-d1fc-4d25-b7b0-c4fbaef943be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between STP and BGP?', '[{"id": "A", "text": "STP is preventing Layer 2 loops in redundant switched topologies; QoS is prioritizing certain traffic classes over others.", "is_correct": false}, {"id": "B", "text": "STP is preventing Layer 2 loops in redundant switched topologies; BGP is exchanging routing information between autonomous systems.", "is_correct": true}, {"id": "C", "text": "STP is preventing Layer 2 loops in redundant switched topologies; CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees.", "is_correct": false}, {"id": "D", "text": "STP is preventing Layer 2 loops in redundant switched topologies; DTP is Dynamic Trunking Protocol for automatic trunk negotiation.", "is_correct": false}]', 'STP preventing Layer 2 loops in redundant switched topologies. BGP exchanging routing information between autonomous systems.', '{}', 'Network Concept Comparison', 14.0, '9f8d4373ce6e8936_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78dc668c-09a6-40fc-a0ae-b63b35bc06cc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between NetFlow and DTP?', '[{"id": "A", "text": "NetFlow is Cisco IP traffic flow monitoring and export; NFV is virtualizing network functions on commodity hardware.", "is_correct": false}, {"id": "B", "text": "NetFlow is Cisco IP traffic flow monitoring and export; DMVPN is dynamic multi-point VPN for hub-and-spoke topologies.", "is_correct": false}, {"id": "C", "text": "NetFlow is Cisco IP traffic flow monitoring and export; DTP is Dynamic Trunking Protocol for automatic trunk negotiation.", "is_correct": true}, {"id": "D", "text": "NetFlow is Cisco IP traffic flow monitoring and export; 802.1X is port-based network access control with EAP authentication.", "is_correct": false}]', 'NetFlow Cisco IP traffic flow monitoring and export. DTP Dynamic Trunking Protocol for automatic trunk negotiation.', '{}', 'Network Concept Comparison', 14.0, '72bffde52cf46e9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('835504ef-ce12-45ab-9fd1-55b2ad623d30', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Y.1731 and WFQ?', '[{"id": "A", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; STP Guard is BPDU guard, root guard, and loop guard protections.", "is_correct": false}, {"id": "B", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; WFQ is Weighted Fair Queueing providing fair bandwidth allocation.", "is_correct": true}, {"id": "C", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; BGP is exchanging routing information between autonomous systems.", "is_correct": false}, {"id": "D", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; TrustSec is Cisco security group tagging for role-based access control.", "is_correct": false}]', 'Y.1731 ITU-T Ethernet OAM performance monitoring. WFQ Weighted Fair Queueing providing fair bandwidth allocation.', '{}', 'Network Concept Comparison', 14.0, 'fd53e4f1276931ff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac79a5f4-2212-4581-ad53-7487eda8f39a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between TACACS+ and ACL?', '[{"id": "A", "text": "TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP; VLAN is segmenting a physical network into multiple logical broadcast domains.", "is_correct": false}, {"id": "B", "text": "TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP; ACL is access control list filtering traffic by IP, port, and protocol.", "is_correct": true}, {"id": "C", "text": "TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP; CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees.", "is_correct": false}, {"id": "D", "text": "TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP; Switching is forwarding frames within a network based on destination MAC.", "is_correct": false}]', 'TACACS+ Cisco AAA protocol; separate auth/authorization with TCP. ACL access control list filtering traffic by IP, port, and protocol.', '{}', 'Network Concept Comparison', 14.0, 'ef91ca8b05cdcf4e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64afa874-39e9-4d33-8aca-02664e686fee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SaltStack and RADIUS?', '[{"id": "A", "text": "SaltStack is event-driven automation with remote execution; RADIUS is UDP-based AAA protocol for network access control.", "is_correct": true}, {"id": "B", "text": "SaltStack is event-driven automation with remote execution; PoE is Power over Ethernet delivering power over data cables.", "is_correct": false}, {"id": "C", "text": "SaltStack is event-driven automation with remote execution; ACL is access control list filtering traffic by IP, port, and protocol.", "is_correct": false}, {"id": "D", "text": "SaltStack is event-driven automation with remote execution; TRILL is transparent interconnection of lots of links for Layer 2 multipathing.", "is_correct": false}]', 'SaltStack event-driven automation with remote execution. RADIUS UDP-based AAA protocol for network access control.', '{}', 'Network Concept Comparison', 14.0, 'bbaa9d4b1fd06bdc_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8947ab7-8f9a-4ca4-81dd-2b94b6f63a4b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between 802.1X and STP Guard?', '[{"id": "A", "text": "802.1X is port-based network access control with EAP authentication; Policy-Based Routing is forwarding based on policies other than destination IP.", "is_correct": false}, {"id": "B", "text": "802.1X is port-based network access control with EAP authentication; STP Guard is BPDU guard, root guard, and loop guard protections.", "is_correct": true}, {"id": "C", "text": "802.1X is port-based network access control with EAP authentication; WebAuth is web-based captive portal authentication for guest access.", "is_correct": false}, {"id": "D", "text": "802.1X is port-based network access control with EAP authentication; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}]', '802.1X port-based network access control with EAP authentication. STP Guard BPDU guard, root guard, and loop guard protections.', '{}', 'Network Concept Comparison', 14.0, '1fb0c397ce1508bd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fd0720b-ced5-4e26-b244-c37f553619f4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between IPSLA and PoE?', '[{"id": "A", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); PoE is Power over Ethernet delivering power over data cables.", "is_correct": true}, {"id": "B", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); AAA is authentication, authorization, and accounting framework.", "is_correct": false}, {"id": "C", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); RSVP-TE is RSVP with traffic engineering for constraint-based MPLS LSP setup.", "is_correct": false}, {"id": "D", "text": "IPSLA is Cisco IP SLA for performance measurement (latency, jitter, loss); SGT is Security Group Tag for Cisco TrustSec policy enforcement.", "is_correct": false}]', 'IPSLA Cisco IP SLA for performance measurement (latency, jitter, loss). PoE Power over Ethernet delivering power over data cables.', '{}', 'Network Concept Comparison', 14.0, '5e84fb86e5b1bbb2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
