INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('133cbab6-f17d-49aa-b558-bde7ede15b6e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Chef and UDLD?', '[{"id": "A", "text": "Chef is configuration management using Ruby DSL cookbooks; Syslog is centralized logging for network device events.", "is_correct": false}, {"id": "B", "text": "Chef is configuration management using Ruby DSL cookbooks; TRILL is transparent interconnection of lots of links for Layer 2 multipathing.", "is_correct": false}, {"id": "C", "text": "Chef is configuration management using Ruby DSL cookbooks; UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": true}, {"id": "D", "text": "Chef is configuration management using Ruby DSL cookbooks; FCoE is Fibre Channel over Ethernet for storage networking.", "is_correct": false}]', 'Chef configuration management using Ruby DSL cookbooks. UDLD UniDirectional Link Detection for fiber link monitoring.', '{}', 'Network Concept Comparison', 14.0, '24d4168122797347_gen_v6', true) ON CONFLICT (id) DO NOTHING;
