INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14e51b46-ec25-42d1-9ea6-4d3ceb91b934', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between TRILL and IP SLA?', '[{"id": "A", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; VLAN is segmenting a physical network into multiple logical broadcast domains.", "is_correct": false}, {"id": "B", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; IP SLA is measure network performance metrics (latency, jitter, loss).", "is_correct": true}, {"id": "C", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; GMPLS is Generalized MPLS for optical and TDM network control.", "is_correct": false}, {"id": "D", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; QoS is prioritizing certain traffic classes over others.", "is_correct": false}]', 'TRILL transparent interconnection of lots of links for Layer 2 multipathing. IP SLA measure network performance metrics (latency, jitter, loss).', '{}', 'Network Concept Comparison', 14.0, 'fe49b6a09db94b67_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96dce71c-763b-4e4e-8f2f-21a14ef936ee', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between OTV and IS-IS?', '[{"id": "A", "text": "OTV is Overlay Transport Virtualization for Layer 2 DCI; VSS is Virtual Switching System combining two chassis.", "is_correct": false}, {"id": "B", "text": "OTV is Overlay Transport Virtualization for Layer 2 DCI; FCoE is Fibre Channel over Ethernet for storage networking.", "is_correct": false}, {"id": "C", "text": "OTV is Overlay Transport Virtualization for Layer 2 DCI; IS-IS is link-state IGP used in service provider networks.", "is_correct": true}, {"id": "D", "text": "OTV is Overlay Transport Virtualization for Layer 2 DCI; 802.1X is port-based network access control with EAP authentication.", "is_correct": false}]', 'OTV Overlay Transport Virtualization for Layer 2 DCI. IS-IS link-state IGP used in service provider networks.', '{}', 'Network Concept Comparison', 14.0, '010b833f86770650_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3543411b-09ad-4692-af83-778056510cfc', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between YANG and DTP?', '[{"id": "A", "text": "YANG is data modeling language for network configuration and state; LISP is Locator/ID Separation Protocol for routing scalability.", "is_correct": false}, {"id": "B", "text": "YANG is data modeling language for network configuration and state; DTP is Dynamic Trunking Protocol for automatic trunk negotiation.", "is_correct": true}, {"id": "C", "text": "YANG is data modeling language for network configuration and state; PoE+ is IEEE 802.3at PoE with 30W per port.", "is_correct": false}, {"id": "D", "text": "YANG is data modeling language for network configuration and state; RestConf is RESTful API for network configuration using YANG models.", "is_correct": false}]', 'YANG data modeling language for network configuration and state. DTP Dynamic Trunking Protocol for automatic trunk negotiation.', '{}', 'Network Concept Comparison', 14.0, 'b456f4031a34528f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('986ac197-7fa5-4174-b81b-7a4bfe487b9e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SDN and FCoE?', '[{"id": "A", "text": "SDN is software-defined networking decoupling control and data planes; LDP is label distribution protocol distributing labels for IGP routes.", "is_correct": false}, {"id": "B", "text": "SDN is software-defined networking decoupling control and data planes; FCoE is Fibre Channel over Ethernet for storage networking.", "is_correct": true}, {"id": "C", "text": "SDN is software-defined networking decoupling control and data planes; VTP is VLAN Trunking Protocol for VLAN database synchronization.", "is_correct": false}, {"id": "D", "text": "SDN is software-defined networking decoupling control and data planes; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}]', 'SDN software-defined networking decoupling control and data planes. FCoE Fibre Channel over Ethernet for storage networking.', '{}', 'Network Concept Comparison', 14.0, '466d13a458234e1f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e16e2ba-e12f-475e-92c5-38e5f1839e3d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between BFD and VTEP?', '[{"id": "A", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; STP is preventing Layer 2 loops in redundant switched topologies.", "is_correct": false}, {"id": "B", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; Port Security is restricting MAC addresses allowed on a switch port.", "is_correct": false}, {"id": "C", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; VTEP is VXLAN tunnel endpoint performing encapsulation and decapsulation.", "is_correct": true}, {"id": "D", "text": "BFD is Bidirectional Forwarding Detection for sub-second failure detection; Puppet is declarative configuration management with pull model.", "is_correct": false}]', 'BFD Bidirectional Forwarding Detection for sub-second failure detection. VTEP VXLAN tunnel endpoint performing encapsulation and decapsulation.', '{}', 'Network Concept Comparison', 14.0, 'ad4035f147513819_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5e34cc0-929b-4c38-8602-4e11b5b99b19', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between OAM and Switching?', '[{"id": "A", "text": "OAM is Operations, Administration, and Management for network OAM; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}, {"id": "B", "text": "OAM is Operations, Administration, and Management for network OAM; Routing is forwarding packets between networks based on destination IP.", "is_correct": false}, {"id": "C", "text": "OAM is Operations, Administration, and Management for network OAM; Ansible is agentless automation tool using YAML playbooks.", "is_correct": false}, {"id": "D", "text": "OAM is Operations, Administration, and Management for network OAM; Switching is forwarding frames within a network based on destination MAC.", "is_correct": true}]', 'OAM Operations, Administration, and Management for network OAM. Switching forwarding frames within a network based on destination MAC.', '{}', 'Network Concept Comparison', 14.0, 'fe98cf2144cc0ab7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6315d0e8-39d9-4d06-a076-37cba783411a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between FlexLinks and TWAMP?', '[{"id": "A", "text": "FlexLinks is Cisco failover mechanism for dual-homed access; Route Summarization is aggregating multiple prefixes into a shorter prefix.", "is_correct": false}, {"id": "B", "text": "FlexLinks is Cisco failover mechanism for dual-homed access; TWAMP is Two-Way Active Measurement Protocol for network performance.", "is_correct": true}, {"id": "C", "text": "FlexLinks is Cisco failover mechanism for dual-homed access; VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3.", "is_correct": false}, {"id": "D", "text": "FlexLinks is Cisco failover mechanism for dual-homed access; Port Security is restricting MAC addresses allowed on a switch port.", "is_correct": false}]', 'FlexLinks Cisco failover mechanism for dual-homed access. TWAMP Two-Way Active Measurement Protocol for network performance.', '{}', 'Network Concept Comparison', 14.0, '8517125e41fb3aac_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df51c72d-5d95-4800-a38e-63faf6f3977b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between Y.1731 and NTP?', '[{"id": "A", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; NTP is time synchronization across network infrastructure.", "is_correct": true}, {"id": "B", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; TRILL is transparent interconnection of lots of links for Layer 2 multipathing.", "is_correct": false}, {"id": "C", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; TWAMP is Two-Way Active Measurement Protocol for network performance.", "is_correct": false}, {"id": "D", "text": "Y.1731 is ITU-T Ethernet OAM performance monitoring; LISP is Locator/ID Separation Protocol for routing scalability.", "is_correct": false}]', 'Y.1731 ITU-T Ethernet OAM performance monitoring. NTP time synchronization across network infrastructure.', '{}', 'Network Concept Comparison', 14.0, '81d66e3cc708cbea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f6fa04b-344d-4aed-a8af-e5dac2a89850', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CBWFQ and LISP?', '[{"id": "A", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP.", "is_correct": false}, {"id": "B", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; NTP is time synchronization across network infrastructure.", "is_correct": false}, {"id": "C", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; RSVP-TE is RSVP with traffic engineering for constraint-based MPLS LSP setup.", "is_correct": false}, {"id": "D", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; LISP is Locator/ID Separation Protocol for routing scalability.", "is_correct": true}]', 'CBWFQ Class-Based Weighted Fair Queueing for per-class bandwidth guarantees. LISP Locator/ID Separation Protocol for routing scalability.', '{}', 'Network Concept Comparison', 14.0, '3e31454e7282c82d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('884ab69f-443f-41d8-a30f-d26f07cf24a9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between VNI and Syslog?', '[{"id": "A", "text": "VNI is VXLAN network identifier for segment isolation; ZTP is Zero-Touch Provisioning for automated device deployment.", "is_correct": false}, {"id": "B", "text": "VNI is VXLAN network identifier for segment isolation; CFM is Connectivity Fault Management IEEE 802.1ag for Ethernet OAM.", "is_correct": false}, {"id": "C", "text": "VNI is VXLAN network identifier for segment isolation; Switching is forwarding frames within a network based on destination MAC.", "is_correct": false}, {"id": "D", "text": "VNI is VXLAN network identifier for segment isolation; Syslog is centralized logging for network device events.", "is_correct": true}]', 'VNI VXLAN network identifier for segment isolation. Syslog centralized logging for network device events.', '{}', 'Network Concept Comparison', 14.0, '81e1f9c65b136283_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cc0122f-64a0-4693-b508-2b3a19b31952', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between LLQ and TRILL?', '[{"id": "A", "text": "LLQ is Low Latency Queueing for real-time traffic guaranteed bandwidth; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}, {"id": "B", "text": "LLQ is Low Latency Queueing for real-time traffic guaranteed bandwidth; FHRP is first-hop redundancy for default gateway high availability.", "is_correct": false}, {"id": "C", "text": "LLQ is Low Latency Queueing for real-time traffic guaranteed bandwidth; TRILL is transparent interconnection of lots of links for Layer 2 multipathing.", "is_correct": true}, {"id": "D", "text": "LLQ is Low Latency Queueing for real-time traffic guaranteed bandwidth; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}]', 'LLQ Low Latency Queueing for real-time traffic guaranteed bandwidth. TRILL transparent interconnection of lots of links for Layer 2 multipathing.', '{}', 'Network Concept Comparison', 14.0, '46a925c3aeb8ec26_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19ec3d76-c615-4541-ba86-70d5cba52fe9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between NTP and Floating Static Route?', '[{"id": "A", "text": "NTP is time synchronization across network infrastructure; Floating Static Route is static route with higher AD for backup path.", "is_correct": true}, {"id": "B", "text": "NTP is time synchronization across network infrastructure; RADIUS is UDP-based AAA protocol for network access control.", "is_correct": false}, {"id": "C", "text": "NTP is time synchronization across network infrastructure; VPN is securely extending a private network across a public infrastructure.", "is_correct": false}, {"id": "D", "text": "NTP is time synchronization across network infrastructure; VRRP is standards-based virtual router redundancy.", "is_correct": false}]', 'NTP time synchronization across network infrastructure. Floating Static Route static route with higher AD for backup path.', '{}', 'Network Concept Comparison', 14.0, 'cc13febe26dd98ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5ae9933-40e7-4582-93e1-dcb456a9ecb4', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between ARP and vPC?', '[{"id": "A", "text": "ARP is resolving IPv4 addresses to MAC addresses on broadcast segments; PAgP is Cisco port aggregation protocol for EtherChannel.", "is_correct": false}, {"id": "B", "text": "ARP is resolving IPv4 addresses to MAC addresses on broadcast segments; Syslog is centralized logging for network device events.", "is_correct": false}, {"id": "C", "text": "ARP is resolving IPv4 addresses to MAC addresses on broadcast segments; SPB is Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.", "is_correct": false}, {"id": "D", "text": "ARP is resolving IPv4 addresses to MAC addresses on broadcast segments; vPC is virtual Port Channel for cross-chassis multi-homing.", "is_correct": true}]', 'ARP resolving IPv4 addresses to MAC addresses on broadcast segments. vPC virtual Port Channel for cross-chassis multi-homing.', '{}', 'Network Concept Comparison', 14.0, '8f1d408abbb48269_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60c09d77-6a61-4b66-9095-94b0ef09c016', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between NAT and ARP?', '[{"id": "A", "text": "NAT is translating private IPs to public IPs for Internet connectivity; IP SLA is measure network performance metrics (latency, jitter, loss).", "is_correct": false}, {"id": "B", "text": "NAT is translating private IPs to public IPs for Internet connectivity; ARP is resolving IPv4 addresses to MAC addresses on broadcast segments.", "is_correct": true}, {"id": "C", "text": "NAT is translating private IPs to public IPs for Internet connectivity; SNMPv3 is SNMP with encryption and authentication security.", "is_correct": false}, {"id": "D", "text": "NAT is translating private IPs to public IPs for Internet connectivity; IPS is intrusion prevention system inspecting traffic for threats.", "is_correct": false}]', 'NAT translating private IPs to public IPs for Internet connectivity. ARP resolving IPv4 addresses to MAC addresses on broadcast segments.', '{}', 'Network Concept Comparison', 14.0, '73bad9cffa7b5f18_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1f98400-a613-425e-a00e-406998deecb3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CWMP/TR-069 and SNMP?', '[{"id": "A", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; ZTP is Zero-Touch Provisioning for automated device deployment.", "is_correct": false}, {"id": "B", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; OSPF is link-state IGP using SPF algorithm for loop-free routing.", "is_correct": false}, {"id": "C", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; SNMP is protocol for monitoring and managing network devices.", "is_correct": true}, {"id": "D", "text": "CWMP/TR-069 is CPE WAN management protocol for auto-configuration; HSRP is Cisco active/standby gateway redundancy.", "is_correct": false}]', 'CWMP/TR-069 CPE WAN management protocol for auto-configuration. SNMP protocol for monitoring and managing network devices.', '{}', 'Network Concept Comparison', 14.0, 'cf15539824e1fd0a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c7a5b1d-ada5-4f0a-9999-e3ff609cd4e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SSH and VPN?', '[{"id": "A", "text": "SSH is encrypted remote access protocol for CLI management; IPS is intrusion prevention system inspecting traffic for threats.", "is_correct": false}, {"id": "B", "text": "SSH is encrypted remote access protocol for CLI management; Floating Static Route is static route with higher AD for backup path.", "is_correct": false}, {"id": "C", "text": "SSH is encrypted remote access protocol for CLI management; VPN is securely extending a private network across a public infrastructure.", "is_correct": true}, {"id": "D", "text": "SSH is encrypted remote access protocol for CLI management; NTP is time synchronization across network infrastructure.", "is_correct": false}]', 'SSH encrypted remote access protocol for CLI management. VPN securely extending a private network across a public infrastructure.', '{}', 'Network Concept Comparison', 14.0, '0a605cb732a420ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb016542-5363-4a48-baa4-0838e552cbbd', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between CBWFQ and DHCP Snooping?', '[{"id": "A", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; DHCP Snooping is man-in-the-middle attack prevention by filtering DHCP messages.", "is_correct": true}, {"id": "B", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; 802.1X is port-based network access control with EAP authentication.", "is_correct": false}, {"id": "C", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; Dynamic ARP Inspection is ARP spoofing prevention by validating ARP packets.", "is_correct": false}, {"id": "D", "text": "CBWFQ is Class-Based Weighted Fair Queueing for per-class bandwidth guarantees; Syslog is centralized logging for network device events.", "is_correct": false}]', 'CBWFQ Class-Based Weighted Fair Queueing for per-class bandwidth guarantees. DHCP Snooping man-in-the-middle attack prevention by filtering DHCP messages.', '{}', 'Network Concept Comparison', 14.0, '5bb1f93788e1921d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c537cd42-3006-4b83-b2ee-b10aea35e8f3', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between PAgP and ARP?', '[{"id": "A", "text": "PAgP is Cisco port aggregation protocol for EtherChannel; QoS is prioritizing certain traffic classes over others.", "is_correct": false}, {"id": "B", "text": "PAgP is Cisco port aggregation protocol for EtherChannel; ARP is resolving IPv4 addresses to MAC addresses on broadcast segments.", "is_correct": true}, {"id": "C", "text": "PAgP is Cisco port aggregation protocol for EtherChannel; Routing is forwarding packets between networks based on destination IP.", "is_correct": false}, {"id": "D", "text": "PAgP is Cisco port aggregation protocol for EtherChannel; Zone-Based Firewall is Cisco zone-pair firewall policy architecture.", "is_correct": false}]', 'PAgP Cisco port aggregation protocol for EtherChannel. ARP resolving IPv4 addresses to MAC addresses on broadcast segments.', '{}', 'Network Concept Comparison', 14.0, 'e439d58ec735959a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4674e5cb-ce08-40ae-8cc2-b0fd6946dbc0', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between vPC and ACL?', '[{"id": "A", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3.", "is_correct": false}, {"id": "B", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; ACL is access control list filtering traffic by IP, port, and protocol.", "is_correct": true}, {"id": "C", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; PoE+ is IEEE 802.3at PoE with 30W per port.", "is_correct": false}, {"id": "D", "text": "vPC is virtual Port Channel for cross-chassis multi-homing; IPFIX is NetFlow v10 standardized flow export protocol.", "is_correct": false}]', 'vPC virtual Port Channel for cross-chassis multi-homing. ACL access control list filtering traffic by IP, port, and protocol.', '{}', 'Network Concept Comparison', 14.0, '9f7eadc0180c50d4_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bcbdb935-ae21-4997-b7d6-93edf7228561', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between IPFIX and OAM?', '[{"id": "A", "text": "IPFIX is NetFlow v10 standardized flow export protocol; OAM is Operations, Administration, and Management for network OAM.", "is_correct": true}, {"id": "B", "text": "IPFIX is NetFlow v10 standardized flow export protocol; SNMPv3 is SNMP with encryption and authentication security.", "is_correct": false}, {"id": "C", "text": "IPFIX is NetFlow v10 standardized flow export protocol; Access Port is switch port carrying traffic for a single VLAN.", "is_correct": false}, {"id": "D", "text": "IPFIX is NetFlow v10 standardized flow export protocol; SGT is Security Group Tag for Cisco TrustSec policy enforcement.", "is_correct": false}]', 'IPFIX NetFlow v10 standardized flow export protocol. OAM Operations, Administration, and Management for network OAM.', '{}', 'Network Concept Comparison', 14.0, '451a1d9c35ab269f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fe4fcc94-28d8-46e8-911d-3369cc008898', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between TRILL and Route Redistribution?', '[{"id": "A", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; Chef is configuration management using Ruby DSL cookbooks.", "is_correct": false}, {"id": "B", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; Syslog is centralized logging for network device events.", "is_correct": false}, {"id": "C", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; SDN is software-defined networking decoupling control and data planes.", "is_correct": false}, {"id": "D", "text": "TRILL is transparent interconnection of lots of links for Layer 2 multipathing; Route Redistribution is importing routes from one routing protocol into another.", "is_correct": true}]', 'TRILL transparent interconnection of lots of links for Layer 2 multipathing. Route Redistribution importing routes from one routing protocol into another.', '{}', 'Network Concept Comparison', 14.0, '4eb61fcd2fc13bca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f72df2b8-ac12-4348-bf8a-0a3740f1d41f', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between VPC and UDLD?', '[{"id": "A", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; UDLD is UniDirectional Link Detection for fiber link monitoring.", "is_correct": true}, {"id": "B", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; VTP is VLAN Trunking Protocol for VLAN database synchronization.", "is_correct": false}, {"id": "C", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; GETVPN is Group Encrypted Transport VPN with any-to-any connectivity.", "is_correct": false}, {"id": "D", "text": "VPC is virtual Port Channel for cross-chassis multi-homing on NX-OS; DSCP is Differentiated Services Code Point for Layer 3 QoS marking.", "is_correct": false}]', 'VPC virtual Port Channel for cross-chassis multi-homing on NX-OS. UDLD UniDirectional Link Detection for fiber link monitoring.', '{}', 'Network Concept Comparison', 14.0, 'ea204cec82c869f1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2d95a98-6ba6-4260-a1fd-ec2e56bdf3ca', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between RADIUS and VXLAN?', '[{"id": "A", "text": "RADIUS is UDP-based AAA protocol for network access control; VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3.", "is_correct": true}, {"id": "B", "text": "RADIUS is UDP-based AAA protocol for network access control; CoS is Layer 2 class of service using 802.1p priority bits.", "is_correct": false}, {"id": "C", "text": "RADIUS is UDP-based AAA protocol for network access control; MPLS is label switching forwarding paradigm for traffic engineering.", "is_correct": false}, {"id": "D", "text": "RADIUS is UDP-based AAA protocol for network access control; FHRP is first-hop redundancy for default gateway high availability.", "is_correct": false}]', 'RADIUS UDP-based AAA protocol for network access control. VXLAN MAC-in-UDP overlay for Layer 2 extension over Layer 3.', '{}', 'Network Concept Comparison', 14.0, '67e052c533db07db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13f1d04c-3e6f-4c3d-a7e9-a51874e2935c', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between DMVPN and CFM?', '[{"id": "A", "text": "DMVPN is dynamic multi-point VPN for hub-and-spoke topologies; CFM is Connectivity Fault Management IEEE 802.1ag for Ethernet OAM.", "is_correct": true}, {"id": "B", "text": "DMVPN is dynamic multi-point VPN for hub-and-spoke topologies; WebAuth is web-based captive portal authentication for guest access.", "is_correct": false}, {"id": "C", "text": "DMVPN is dynamic multi-point VPN for hub-and-spoke topologies; IPS is intrusion prevention system inspecting traffic for threats.", "is_correct": false}, {"id": "D", "text": "DMVPN is dynamic multi-point VPN for hub-and-spoke topologies; DNS is resolving human-readable hostnames to numeric IP addresses.", "is_correct": false}]', 'DMVPN dynamic multi-point VPN for hub-and-spoke topologies. CFM Connectivity Fault Management IEEE 802.1ag for Ethernet OAM.', '{}', 'Network Concept Comparison', 14.0, '06b1344569765d7c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd6352b4-3a6f-4293-b886-3585b54e443a', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between DSCP and AAA?', '[{"id": "A", "text": "DSCP is Differentiated Services Code Point for Layer 3 QoS marking; AAA is authentication, authorization, and accounting framework.", "is_correct": true}, {"id": "B", "text": "DSCP is Differentiated Services Code Point for Layer 3 QoS marking; TrustSec is Cisco security group tagging for role-based access control.", "is_correct": false}, {"id": "C", "text": "DSCP is Differentiated Services Code Point for Layer 3 QoS marking; VSS is Cisco Virtual Switching System combining two 6500 chassis.", "is_correct": false}, {"id": "D", "text": "DSCP is Differentiated Services Code Point for Layer 3 QoS marking; TACACS+ is Cisco AAA protocol; separate auth/authorization with TCP.", "is_correct": false}]', 'DSCP Differentiated Services Code Point for Layer 3 QoS marking. AAA authentication, authorization, and accounting framework.', '{}', 'Network Concept Comparison', 14.0, '686213a26e35a2b0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('278c050f-4707-4fe2-a37e-3360a2961c64', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between VXLAN and TrustSec?', '[{"id": "A", "text": "VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}, {"id": "B", "text": "VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3; TrustSec is Cisco security group tagging for role-based access control.", "is_correct": true}, {"id": "C", "text": "VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3; TrustSec is Cisco security group tagging for role-based access control.", "is_correct": true}, {"id": "D", "text": "VXLAN is MAC-in-UDP overlay for Layer 2 extension over Layer 3; Route Redistribution is importing routes from one routing protocol into another.", "is_correct": false}]', 'VXLAN MAC-in-UDP overlay for Layer 2 extension over Layer 3. TrustSec Cisco security group tagging for role-based access control.', '{}', 'Network Concept Comparison', 14.0, 'c86cdf75edf437a4_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9cdbf65-33e1-4129-80b7-d249c6a28c8d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between RestConf and WFQ?', '[{"id": "A", "text": "RestConf is RESTful API for network configuration using YANG models; WFQ is Weighted Fair Queueing providing fair bandwidth allocation.", "is_correct": true}, {"id": "B", "text": "RestConf is RESTful API for network configuration using YANG models; Chef is configuration management using Ruby DSL cookbooks.", "is_correct": false}, {"id": "C", "text": "RestConf is RESTful API for network configuration using YANG models; IS-IS is link-state IGP used in service provider networks.", "is_correct": false}, {"id": "D", "text": "RestConf is RESTful API for network configuration using YANG models; AAA is authentication, authorization, and accounting framework.", "is_correct": false}]', 'RestConf RESTful API for network configuration using YANG models. WFQ Weighted Fair Queueing providing fair bandwidth allocation.', '{}', 'Network Concept Comparison', 14.0, 'd9aa5567c71b6e5c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fade07e-884c-488c-a9a1-f8551829b825', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the difference between SNMPv3 and SPB?', '[{"id": "A", "text": "SNMPv3 is SNMP with encryption and authentication security; BFD is Bidirectional Forwarding Detection for sub-second failure detection.", "is_correct": false}, {"id": "B", "text": "SNMPv3 is SNMP with encryption and authentication security; QoS is prioritizing certain traffic classes over others.", "is_correct": false}, {"id": "C", "text": "SNMPv3 is SNMP with encryption and authentication security; SPB is Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.", "is_correct": true}, {"id": "D", "text": "SNMPv3 is SNMP with encryption and authentication security; VNI is VXLAN network identifier for segment isolation.", "is_correct": false}]', 'SNMPv3 SNMP with encryption and authentication security. SPB Shortest Path Bridging IEEE 802.1aq for Layer 2 IS-IS control.', '{}', 'Network Concept Comparison', 14.0, 'aea55a8717cf1dda_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b6ecdcc8-73e2-4846-a55b-31ba1d529cdf', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'Network Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60b9f698-a138-44d1-96f8-87fe942aa2ff', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "C", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Network Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36e7b769-2c11-41d0-a13d-06cb75a99b21', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'Network Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20ebc25b-3e0c-4bea-b943-ca1f9f315b55', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'Network Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2aef14cf-cc9d-4e75-82d9-25a4b33188b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is BDR?', '[{"id": "A", "text": "NSSA external route advertisement", "is_correct": false}, {"id": "B", "text": "Backup Designated Router; takes over if DR fails", "is_correct": true}, {"id": "C", "text": "Designated Router elected on multi-access networks", "is_correct": false}, {"id": "D", "text": "NSSA with Type 3/4 summary suppression", "is_correct": false}]', 'BDR: Backup Designated Router; takes over if DR fails.', '{}', 'OSPF', 14.0, '6d28a4f5d801a7ad_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ef026f2-ce3d-4f1a-8920-ac108d87a7df', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is Router ID?', '[{"id": "A", "text": "NSSA external route advertisement", "is_correct": false}, {"id": "B", "text": "NSSA with Type 3/4 summary suppression", "is_correct": false}, {"id": "C", "text": "unique 32-bit identifier for OSPF router identification", "is_correct": true}, {"id": "D", "text": "advertises ASBR reachability to other areas", "is_correct": false}]', 'Router ID: unique 32-bit identifier for OSPF router identification.', '{}', 'OSPF', 14.0, '61a6be30970891a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50b9a07b-653f-4386-a657-8f677f71e8b2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is Virtual Link?', '[{"id": "A", "text": "connects non-backbone area to Area 0 through transit area", "is_correct": true}, {"id": "B", "text": "NSSA external route advertisement", "is_correct": false}, {"id": "C", "text": "unique 32-bit identifier for OSPF router identification", "is_correct": false}, {"id": "D", "text": "blocks Type 5 LSAs; default route for external", "is_correct": false}]', 'Virtual Link: connects non-backbone area to Area 0 through transit area.', '{}', 'OSPF', 14.0, '17aaf37180d84b92_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e306afc0-3d6b-45b6-9c78-2026ff5772e7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is ASBR?', '[{"id": "A", "text": "NSSA external route advertisement", "is_correct": false}, {"id": "B", "text": "AS Boundary Router redistributing external routes", "is_correct": true}, {"id": "C", "text": "NSSA with Type 3/4 summary suppression", "is_correct": false}, {"id": "D", "text": "blocks Type 3/4/5 LSAs; default route only", "is_correct": false}]', 'ASBR: AS Boundary Router redistributing external routes.', '{}', 'OSPF', 14.0, '6041394811b4d40a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bafa4e7-cdec-4d64-971b-61704305fc27', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is Network Type?', '[{"id": "A", "text": "OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint)", "is_correct": true}, {"id": "B", "text": "AS Boundary Router redistributing external routes", "is_correct": false}, {"id": "C", "text": "inter-area route advertisement from ABR", "is_correct": false}, {"id": "D", "text": "NSSA external route advertisement", "is_correct": false}]', 'Network Type: OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).', '{}', 'OSPF', 14.0, '6eb38c2dd24a1260_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('100371de-30d7-4db1-abce-43b938704707', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is DR?', '[{"id": "A", "text": "external route advertisement from ASBR", "is_correct": false}, {"id": "B", "text": "advertises router link states within its own area", "is_correct": false}, {"id": "C", "text": "Designated Router elected on multi-access networks", "is_correct": true}, {"id": "D", "text": "blocks Type 3/4/5 LSAs; default route only", "is_correct": false}]', 'DR: Designated Router elected on multi-access networks.', '{}', 'OSPF', 14.0, 'eef8f01a9ae09b70_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b459611f-d020-4b97-960c-5fc9916391a9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is Type 4 (ASBR Summary) LSA?', '[{"id": "A", "text": "advertises ASBR reachability to other areas", "is_correct": true}, {"id": "B", "text": "stub area that imports externals via Type 7 LSAs", "is_correct": false}, {"id": "C", "text": "unique 32-bit identifier for OSPF router identification", "is_correct": false}, {"id": "D", "text": "connects non-backbone area to Area 0 through transit area", "is_correct": false}]', 'Type 4 (ASBR Summary) LSA: advertises ASBR reachability to other areas.', '{}', 'OSPF', 14.0, 'eab73d42149fad59_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a6f34fd-5ecb-4e5a-87ba-d8c84be7f229', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is Type 7 (NSSA) LSA?', '[{"id": "A", "text": "OSPF backbone area connecting all other areas", "is_correct": false}, {"id": "B", "text": "connects non-backbone area to Area 0 through transit area", "is_correct": false}, {"id": "C", "text": "NSSA external route advertisement", "is_correct": true}, {"id": "D", "text": "Shortest Path First (Dijkstra) computes loop-free routes", "is_correct": false}]', 'Type 7 (NSSA) LSA: NSSA external route advertisement.', '{}', 'OSPF', 14.0, '1826b78cdfe7e8d7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
