INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c33cfdd8-b944-4014-bcd4-61f8e39e4662', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": true}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'Advanced Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('901642f1-ca48-42ec-bca2-bdcc57ff3e79', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'Advanced Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d04bf44-564a-4594-8320-664b181f086d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'Advanced Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('854b7b17-a464-4c68-a411-fcf229a1ba5b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "C", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'Advanced Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec408a4f-abbb-4ba1-bcc3-d7ed22617657', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An EVPN with symmetric IRB configured for inter-subnet routing
Traffic between two VLANs on different VTEPs. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": true}, {"id": "C", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: An EVPN with symmetric IRB configured for inter-subnet routing. Traffic between two VLANs on different VTEPs. Result: Both ingress and egress VTEPs perform routing with VNI translation.', '{}', 'Advanced Scenarios', 14.0, '1bd6077f25fc11b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a4267b8-5675-4125-9d77-61d95034357d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "The session establishes with the lower hold timer value", "is_correct": true}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "D", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'Advanced Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f070ee4-5806-41d2-ad54-652d68adbc3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'Advanced Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9604e537-7d13-433e-bb90-7a32c45531d4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'Advanced Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c27718e6-b138-40fd-b0ee-06966eb8331a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'Advanced Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3eb024d0-917b-4a30-8346-6839dea4cfb3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'Advanced Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20a5a5b9-0920-4c21-86eb-348f63dc4d53', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'Advanced Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4dec239-bf4d-42e7-87e5-ef639c06c986', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'Advanced Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b46afe48-feac-4e91-8139-ba621229d085', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "C", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'Advanced Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d4d9092-232c-49ec-a726-2cd3e6c00ab2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "C", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'Advanced Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3a5e9b3-616e-413c-bfcc-ded6ad9989eb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'Advanced Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d14ffae0-4771-4385-8e79-e06928c11f49', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'Advanced Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c89a956f-3ff2-4424-8cc5-2d919acf65f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'Advanced Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05475f2c-bb93-42e5-923a-8651c0471b1e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A QFX switch with MAC learning disabled on a VXLAN VTEP
Unknown destination MAC arrives at the VTEP. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "B", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "C", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "D", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": true}]', 'Given: A QFX switch with MAC learning disabled on a VXLAN VTEP. Unknown destination MAC arrives at the VTEP. Result: The switch floods the packet as unknown unicast within the VNI.', '{}', 'Advanced Scenarios', 14.0, '9982eccfb7e4fe0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca316b55-f808-4d27-bb5b-0981ed63530e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'Advanced Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('809666d3-0959-4020-845d-0c244505e0e4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'Advanced Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c28fdf4a-a7df-42ab-b7cf-36534597a8ad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'Advanced Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a5ae816-61c1-4f98-b914-230b562856ab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers connected via serial link with OSPF enabled
MTU mismatch between the two sides. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": true}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}]', 'Given: Two routers connected via serial link with OSPF enabled. MTU mismatch between the two sides. Result: OSPF neighbors will be stuck in INIT state.', '{}', 'Advanced Scenarios', 14.0, '9960ccd3a83dd2e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f116880-c369-484d-80ba-34cff4451453', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'Advanced Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('557570d5-5400-4697-be4d-0a31918fac13', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'Advanced Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbf2a333-a517-4e5d-aafa-cbfa2f4c98ca', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'Advanced Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('031051e0-b120-4899-843d-c1d12c908b00', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Advanced Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666d0cb1-9381-4d4c-ba70-8956244afa6e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'Advanced Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3ee51034-56ae-4480-bc66-16cfb121533e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "D", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'Advanced Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d23405cc-ec4d-4f81-90d9-148697800853', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}, {"id": "B", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'Advanced Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3a2a7fb-6b8a-407b-a8e0-149ba7455fc7', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "B", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'Advanced Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12a50796-7547-41ed-ba22-ee22570b59cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 1 (Router) LSA and Area 0?', '[{"id": "A", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": false}, {"id": "B", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Stub Area is blocks Type 5 LSAs; default route for external.", "is_correct": false}, {"id": "C", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}, {"id": "D", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": true}]', 'Type 1 (Router) LSA advertises router link states within its own area. Area 0 OSPF backbone area connecting all other areas.', '{}', 'OSPF Comparison', 14.0, 'c213e0baf0441819_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36b940ad-79c7-4e23-935d-d22e4617dd6a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between ABR and Type 7 (NSSA) LSA?', '[{"id": "A", "text": "ABR is Area Border Router connecting Area 0 to other areas; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": true}, {"id": "B", "text": "ABR is Area Border Router connecting Area 0 to other areas; Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only.", "is_correct": false}, {"id": "C", "text": "ABR is Area Border Router connecting Area 0 to other areas; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "D", "text": "ABR is Area Border Router connecting Area 0 to other areas; ASBR is AS Boundary Router redistributing external routes.", "is_correct": false}]', 'ABR Area Border Router connecting Area 0 to other areas. Type 7 (NSSA) LSA NSSA external route advertisement.', '{}', 'OSPF Comparison', 14.0, 'a3f12e41e0e31596_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baf93071-e126-424e-9611-05d75450e0ae', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 4 (ASBR Summary) LSA and SPF Algorithm?', '[{"id": "A", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; ASBR is AS Boundary Router redistributing external routes.", "is_correct": false}, {"id": "B", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": true}, {"id": "C", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": false}, {"id": "D", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; ABR is Area Border Router connecting Area 0 to other areas.", "is_correct": false}]', 'Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas. SPF Algorithm Shortest Path First (Dijkstra) computes loop-free routes.', '{}', 'OSPF Comparison', 14.0, '4d220ae780102fc9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1bf4be0b-bbf6-42a1-951a-c8b0359fae43', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 5 (External) LSA and Type 1 (Router) LSA?', '[{"id": "A", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": true}, {"id": "B", "text": "Type 5 (External) LSA is external route advertisement from ASBR; ABR is Area Border Router connecting Area 0 to other areas.", "is_correct": false}, {"id": "C", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": true}, {"id": "D", "text": "Type 5 (External) LSA is external route advertisement from ASBR; DROTHER is non-DR/BDR router on multi-access segment.", "is_correct": false}]', 'Type 5 (External) LSA external route advertisement from ASBR. Type 1 (Router) LSA advertises router link states within its own area.', '{}', 'OSPF Comparison', 14.0, 'd7e437b5e2f9d566_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aac52b0b-65ef-4800-90f1-7318bc34fd02', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Router ID and Type 4 (ASBR Summary) LSA?', '[{"id": "A", "text": "Router ID is unique 32-bit identifier for OSPF router identification; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "B", "text": "Router ID is unique 32-bit identifier for OSPF router identification; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": true}, {"id": "C", "text": "Router ID is unique 32-bit identifier for OSPF router identification; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": true}, {"id": "D", "text": "Router ID is unique 32-bit identifier for OSPF router identification; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}]', 'Router ID unique 32-bit identifier for OSPF router identification. Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas.', '{}', 'OSPF Comparison', 14.0, 'f1ee4e52843f0859_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f331e56a-7410-4b6b-9c42-c0781d2f371c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 4 (ASBR Summary) LSA and ASBR?', '[{"id": "A", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "B", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "C", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; ASBR is AS Boundary Router redistributing external routes.", "is_correct": true}, {"id": "D", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": false}]', 'Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas. ASBR AS Boundary Router redistributing external routes.', '{}', 'OSPF Comparison', 14.0, 'b0cc71cee539a382_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6cf8a02-10b3-4e65-b18a-783a1b7fa8f3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BDR and Type 5 (External) LSA?', '[{"id": "A", "text": "BDR is Backup Designated Router; takes over if DR fails; ABR is Area Border Router connecting Area 0 to other areas.", "is_correct": false}, {"id": "B", "text": "BDR is Backup Designated Router; takes over if DR fails; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": false}, {"id": "C", "text": "BDR is Backup Designated Router; takes over if DR fails; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": true}, {"id": "D", "text": "BDR is Backup Designated Router; takes over if DR fails; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}]', 'BDR Backup Designated Router; takes over if DR fails. Type 5 (External) LSA external route advertisement from ASBR.', '{}', 'OSPF Comparison', 14.0, '3e63a0620b06c930_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fea3135-02bb-4aeb-ad8c-c2a922c33129', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between NSSA and Totally NSSA?', '[{"id": "A", "text": "NSSA is stub area that imports externals via Type 7 LSAs; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": true}, {"id": "B", "text": "NSSA is stub area that imports externals via Type 7 LSAs; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": false}, {"id": "C", "text": "NSSA is stub area that imports externals via Type 7 LSAs; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "D", "text": "NSSA is stub area that imports externals via Type 7 LSAs; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": true}]', 'NSSA stub area that imports externals via Type 7 LSAs. Totally NSSA NSSA with Type 3/4 summary suppression.', '{}', 'OSPF Comparison', 14.0, '69fe2121255ddca1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1abcd06b-58ad-4cf5-b071-228a7a40f014', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Totally NSSA and Type 4 (ASBR Summary) LSA?', '[{"id": "A", "text": "Totally NSSA is NSSA with Type 3/4 summary suppression; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "B", "text": "Totally NSSA is NSSA with Type 3/4 summary suppression; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": true}, {"id": "C", "text": "Totally NSSA is NSSA with Type 3/4 summary suppression; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": false}, {"id": "D", "text": "Totally NSSA is NSSA with Type 3/4 summary suppression; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}]', 'Totally NSSA NSSA with Type 3/4 summary suppression. Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas.', '{}', 'OSPF Comparison', 14.0, '9b5001aa314daf10_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c99c1595-6f1d-43b4-9d9b-6a5bb709634f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Network Type and Type 1 (Router) LSA?', '[{"id": "A", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": false}, {"id": "B", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": false}, {"id": "C", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": true}, {"id": "D", "text": "Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint); DROTHER is non-DR/BDR router on multi-access segment.", "is_correct": false}]', 'Network Type OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint). Type 1 (Router) LSA advertises router link states within its own area.', '{}', 'OSPF Comparison', 14.0, '180ab7e5b8c943e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('53545c93-587f-404e-9fed-588a8a7d4a9b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between ASBR and BDR?', '[{"id": "A", "text": "ASBR is AS Boundary Router redistributing external routes; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": true}, {"id": "B", "text": "ASBR is AS Boundary Router redistributing external routes; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "C", "text": "ASBR is AS Boundary Router redistributing external routes; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}, {"id": "D", "text": "ASBR is AS Boundary Router redistributing external routes; Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only.", "is_correct": false}]', 'ASBR AS Boundary Router redistributing external routes. BDR Backup Designated Router; takes over if DR fails.', '{}', 'OSPF Comparison', 14.0, '0c63526e716e72ef_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d79a40cb-059d-40b6-aa6b-a8173b75221b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Totally Stubby Area and Totally NSSA?', '[{"id": "A", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": true}, {"id": "B", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "C", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; Type 5 (External) LSA is external route advertisement from ASBR.", "is_correct": false}, {"id": "D", "text": "Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only; ABR is Area Border Router connecting Area 0 to other areas.", "is_correct": false}]', 'Totally Stubby Area blocks Type 3/4/5 LSAs; default route only. Totally NSSA NSSA with Type 3/4 summary suppression.', '{}', 'OSPF Comparison', 14.0, '9072d378f0ca1fad_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8a2dba3-c668-480a-b4c8-814ee78c8e16', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 1 (Router) LSA and Totally Stubby Area?', '[{"id": "A", "text": "Type 1 (Router) LSA is advertises router link states within its own area; DR is Designated Router elected on multi-access networks.", "is_correct": false}, {"id": "B", "text": "Type 1 (Router) LSA is advertises router link states within its own area; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": false}, {"id": "C", "text": "Type 1 (Router) LSA is advertises router link states within its own area; Totally Stubby Area is blocks Type 3/4/5 LSAs; default route only.", "is_correct": true}, {"id": "D", "text": "Type 1 (Router) LSA is advertises router link states within its own area; ASBR is AS Boundary Router redistributing external routes.", "is_correct": false}]', 'Type 1 (Router) LSA advertises router link states within its own area. Totally Stubby Area blocks Type 3/4/5 LSAs; default route only.', '{}', 'OSPF Comparison', 14.0, 'ffbfdc5656481b76_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69f7994f-22e0-4b09-b867-75729976c27d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Area 0 and Network Type?', '[{"id": "A", "text": "Area 0 is OSPF backbone area connecting all other areas; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": false}, {"id": "B", "text": "Area 0 is OSPF backbone area connecting all other areas; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}, {"id": "C", "text": "Area 0 is OSPF backbone area connecting all other areas; Type 2 (Network) LSA is advertises network segment info; generated by DR.", "is_correct": false}, {"id": "D", "text": "Area 0 is OSPF backbone area connecting all other areas; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": true}]', 'Area 0 OSPF backbone area connecting all other areas. Network Type OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).', '{}', 'OSPF Comparison', 14.0, 'ea87896965081949_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c194f599-e8da-46c3-b0ef-acfd30331161', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BDR and SPF Algorithm?', '[{"id": "A", "text": "BDR is Backup Designated Router; takes over if DR fails; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}, {"id": "B", "text": "BDR is Backup Designated Router; takes over if DR fails; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "C", "text": "BDR is Backup Designated Router; takes over if DR fails; SPF Algorithm is Shortest Path First (Dijkstra) computes loop-free routes.", "is_correct": true}, {"id": "D", "text": "BDR is Backup Designated Router; takes over if DR fails; DROTHER is non-DR/BDR router on multi-access segment.", "is_correct": false}]', 'BDR Backup Designated Router; takes over if DR fails. SPF Algorithm Shortest Path First (Dijkstra) computes loop-free routes.', '{}', 'OSPF Comparison', 14.0, '5e8762998d12eca5_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3dfc2a0-a7eb-4e71-ae92-8a7baef4ddbb', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 2 (Network) LSA and DR?', '[{"id": "A", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "B", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": false}, {"id": "C", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": false}, {"id": "D", "text": "Type 2 (Network) LSA is advertises network segment info; generated by DR; DR is Designated Router elected on multi-access networks.", "is_correct": true}]', 'Type 2 (Network) LSA advertises network segment info; generated by DR. DR Designated Router elected on multi-access networks.', '{}', 'OSPF Comparison', 14.0, 'b783467122aeb133_gen_v6', true) ON CONFLICT (id) DO NOTHING;
