INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d11ac56a-f7b4-4def-a73b-73293f9ce9b6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between DROTHER and Totally NSSA?', '[{"id": "A", "text": "DROTHER is non-DR/BDR router on multi-access segment; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": false}, {"id": "B", "text": "DROTHER is non-DR/BDR router on multi-access segment; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "C", "text": "DROTHER is non-DR/BDR router on multi-access segment; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": true}, {"id": "D", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas.", "is_correct": false}]', 'DROTHER non-DR/BDR router on multi-access segment. Totally NSSA NSSA with Type 3/4 summary suppression.', '{}', 'OSPF Comparison', 14.0, '76195436477749d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a72f86b1-752e-485c-a2fb-6cfafbacb70b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 4 (ASBR Summary) LSA and BDR?', '[{"id": "A", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; Totally NSSA is NSSA with Type 3/4 summary suppression.", "is_correct": false}, {"id": "B", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; NSSA is stub area that imports externals via Type 7 LSAs.", "is_correct": false}, {"id": "C", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; Type 2 (Network) LSA is advertises network segment info; generated by DR.", "is_correct": false}, {"id": "D", "text": "Type 4 (ASBR Summary) LSA is advertises ASBR reachability to other areas; BDR is Backup Designated Router; takes over if DR fails.", "is_correct": true}]', 'Type 4 (ASBR Summary) LSA advertises ASBR reachability to other areas. BDR Backup Designated Router; takes over if DR fails.', '{}', 'OSPF Comparison', 14.0, 'b14b4decd2464523_gen_v6', true) ON CONFLICT (id) DO NOTHING;
