INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc7729ce-22b9-4308-ad84-1b6b10d1a3f2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 5 (External) LSA and Area 0?', '[{"id": "A", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Area 0 is OSPF backbone area connecting all other areas.", "is_correct": true}, {"id": "B", "text": "Type 5 (External) LSA is external route advertisement from ASBR; ASBR is AS Boundary Router redistributing external routes.", "is_correct": false}, {"id": "C", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": false}, {"id": "D", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}]', 'Type 5 (External) LSA external route advertisement from ASBR. Area 0 OSPF backbone area connecting all other areas.', '{}', 'OSPF Comparison', 14.0, '4541cd6adb97689f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad891380-ca7e-48e8-a6c8-412f9e133604', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Type 5 (External) LSA and Type 3 (Summary) LSA?', '[{"id": "A", "text": "Type 5 (External) LSA is external route advertisement from ASBR; DROTHER is non-DR/BDR router on multi-access segment.", "is_correct": false}, {"id": "B", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": true}, {"id": "C", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Router ID is unique 32-bit identifier for OSPF router identification.", "is_correct": false}, {"id": "D", "text": "Type 5 (External) LSA is external route advertisement from ASBR; Network Type is OSPF network type (broadcast, point-to-point, NBMA, point-to-multipoint).", "is_correct": false}]', 'Type 5 (External) LSA external route advertisement from ASBR. Type 3 (Summary) LSA inter-area route advertisement from ABR.', '{}', 'OSPF Comparison', 14.0, '4bb5e26f878fbc12_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3a9d2cd-c955-415b-92b1-3e0319ea54e6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between DROTHER and Type 3 (Summary) LSA?', '[{"id": "A", "text": "DROTHER is non-DR/BDR router on multi-access segment; Virtual Link is connects non-backbone area to Area 0 through transit area.", "is_correct": false}, {"id": "B", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 1 (Router) LSA is advertises router link states within its own area.", "is_correct": false}, {"id": "C", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 3 (Summary) LSA is inter-area route advertisement from ABR.", "is_correct": true}, {"id": "D", "text": "DROTHER is non-DR/BDR router on multi-access segment; Type 7 (NSSA) LSA is NSSA external route advertisement.", "is_correct": false}]', 'DROTHER non-DR/BDR router on multi-access segment. Type 3 (Summary) LSA inter-area route advertisement from ABR.', '{}', 'OSPF Comparison', 14.0, '59dccc6887532555_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('71f8fa7b-0a50-4287-abdb-b186f84b5ef8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Loop Guard and Bridge ID?', '[{"id": "A", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}, {"id": "B", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "C", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": true}, {"id": "D", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": true}]', 'Loop Guard prevents alternate/root ports from becoming designated if BPDUs stop. Bridge ID 8-byte ID: 2-byte priority + 6-byte MAC address.', '{}', 'STP Comparison', 14.0, 'b715bd653bc10f4a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ec336f5-b447-4ad9-8277-6b33a3cb8b46', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Designated Port and Alternate Port?', '[{"id": "A", "text": "Designated Port is best port on a link toward the root; one per segment; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "B", "text": "Designated Port is best port on a link toward the root; one per segment; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}, {"id": "C", "text": "Designated Port is best port on a link toward the root; one per segment; Path Cost is port cost toward the root bridge; inversely proportional to speed.", "is_correct": false}, {"id": "D", "text": "Designated Port is best port on a link toward the root; one per segment; Edge Port is port connected to end host; immediate forwarding.", "is_correct": false}]', 'Designated Port best port on a link toward the root; one per segment. Alternate Port backup to root port; blocked in steady state.', '{}', 'STP Comparison', 14.0, '5fb4b0cdc87b97c2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6b36347-7f06-4fac-849b-dc437055d9b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Loop Guard and Designated Port?', '[{"id": "A", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "B", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}, {"id": "C", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Root Guard is prevents receiving superior BPDUs on designated ports.", "is_correct": false}, {"id": "D", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Designated Port is best port on a link toward the root; one per segment.", "is_correct": true}]', 'Loop Guard prevents alternate/root ports from becoming designated if BPDUs stop. Designated Port best port on a link toward the root; one per segment.', '{}', 'STP Comparison', 14.0, 'aea577aa985aa81e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e13765b0-d7d3-4f61-a104-f45e1b046cab', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Path Cost and Root Guard?', '[{"id": "A", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Root Guard is prevents receiving superior BPDUs on designated ports.", "is_correct": true}, {"id": "B", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": false}, {"id": "C", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "D", "text": "Path Cost is port cost toward the root bridge; inversely proportional to speed; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}]', 'Path Cost port cost toward the root bridge; inversely proportional to speed. Root Guard prevents receiving superior BPDUs on designated ports.', '{}', 'STP Comparison', 14.0, '80e3695aa788cf37_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46d5ea38-d12a-41e8-bb25-027059276e35', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Bridge and Alternate Port?', '[{"id": "A", "text": "Root Bridge is elected root of spanning tree; all ports are designated; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "B", "text": "Root Bridge is elected root of spanning tree; all ports are designated; BPDU Guard is disables port if a BPDU is received on an edge port.", "is_correct": false}, {"id": "C", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "D", "text": "Root Bridge is elected root of spanning tree; all ports are designated; Backup Port is backup to designated port on shared segments.", "is_correct": false}]', 'Root Bridge elected root of spanning tree; all ports are designated. Alternate Port backup to root port; blocked in steady state.', '{}', 'STP Comparison', 14.0, '72a078d4ab54bbaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32dbc8d5-fb9e-4d2d-8644-027400febc9e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BackboneFast and UplinkFast?', '[{"id": "A", "text": "BackboneFast is Cisco fast convergence after indirect link failure; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": true}, {"id": "B", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": false}, {"id": "C", "text": "BackboneFast is Cisco fast convergence after indirect link failure; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}, {"id": "D", "text": "BackboneFast is Cisco fast convergence after indirect link failure; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}]', 'BackboneFast Cisco fast convergence after indirect link failure. UplinkFast Cisco fast convergence on root port failure.', '{}', 'STP Comparison', 14.0, 'b23ed105d2ccc1d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76ad68b8-fc0c-4914-950e-b61ea1f53d2a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between MSTP 802.1s and RSTP 802.1w?', '[{"id": "A", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}, {"id": "B", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Backup Port is backup to designated port on shared segments.", "is_correct": false}, {"id": "C", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": true}, {"id": "D", "text": "MSTP 802.1s is multiple spanning tree instances with VLAN mapping; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}]', 'MSTP 802.1s multiple spanning tree instances with VLAN mapping. RSTP 802.1w rapid STP with discarding/learning/forwarding; fast convergence.', '{}', 'STP Comparison', 14.0, 'f81d6e0fb963326c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
