INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('605f5278-b1c9-47b1-af44-21a3028c16ee', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between STP 802.1D and Alternate Port?', '[{"id": "A", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}, {"id": "B", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "C", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Alternate Port is backup to root port; blocked in steady state.", "is_correct": true}, {"id": "D", "text": "STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence; Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address.", "is_correct": false}]', 'STP 802.1D spanning tree with blocking/listening/learning/forwarding; slow convergence. Alternate Port backup to root port; blocked in steady state.', '{}', 'STP Comparison', 14.0, '812f7d67cb77b014_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21a675fa-fdf1-43b5-bab1-99fcf613ac1b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Rapid PVST+ and UplinkFast?', '[{"id": "A", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Designated Port is best port on a link toward the root; one per segment.", "is_correct": false}, {"id": "B", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}, {"id": "C", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": false}, {"id": "D", "text": "Rapid PVST+ is Cisco per-VLAN RSTP; UplinkFast is Cisco fast convergence on root port failure.", "is_correct": true}]', 'Rapid PVST+ Cisco per-VLAN RSTP. UplinkFast Cisco fast convergence on root port failure.', '{}', 'STP Comparison', 14.0, 'bdff57feba836d97_gen_v6', true) ON CONFLICT (id) DO NOTHING;
