INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc3c1416-9ec4-4848-9c70-d181c9ffac2d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Bridge ID and BPDU Filter?', '[{"id": "A", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": false}, {"id": "B", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; BPDU Filter is suppresses sending/receiving BPDUs on a port.", "is_correct": true}, {"id": "C", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "D", "text": "Bridge ID is 8-byte ID: 2-byte priority + 6-byte MAC address; Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop.", "is_correct": false}]', 'Bridge ID 8-byte ID: 2-byte priority + 6-byte MAC address. BPDU Filter suppresses sending/receiving BPDUs on a port.', '{}', 'STP Comparison', 14.0, '6c70591849acb9c1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('90f3eaaa-7298-4833-a254-ce3493a03b64', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Root Guard and Backup Port?', '[{"id": "A", "text": "Root Guard is prevents receiving superior BPDUs on designated ports; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}, {"id": "B", "text": "Root Guard is prevents receiving superior BPDUs on designated ports; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}, {"id": "C", "text": "Root Guard is prevents receiving superior BPDUs on designated ports; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": false}, {"id": "D", "text": "Root Guard is prevents receiving superior BPDUs on designated ports; Backup Port is backup to designated port on shared segments.", "is_correct": true}]', 'Root Guard prevents receiving superior BPDUs on designated ports. Backup Port backup to designated port on shared segments.', '{}', 'STP Comparison', 14.0, 'dd361e7f8c47215a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dc8f6520-ee86-4fe4-9647-1bde47dd4b89', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between BPDU Guard and Rapid PVST+?', '[{"id": "A", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; Rapid PVST+ is Cisco per-VLAN RSTP.", "is_correct": true}, {"id": "B", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": false}, {"id": "C", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; Alternate Port is backup to root port; blocked in steady state.", "is_correct": false}, {"id": "D", "text": "BPDU Guard is disables port if a BPDU is received on an edge port; RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence.", "is_correct": false}]', 'BPDU Guard disables port if a BPDU is received on an edge port. Rapid PVST+ Cisco per-VLAN RSTP.', '{}', 'STP Comparison', 14.0, '40ab1cbfd6ba94b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aafbcdce-0563-4c60-8e7e-b0f533074cec', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between RSTP 802.1w and Root Port?', '[{"id": "A", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; BackboneFast is Cisco fast convergence after indirect link failure.", "is_correct": false}, {"id": "B", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": true}, {"id": "C", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; MSTP 802.1s is multiple spanning tree instances with VLAN mapping.", "is_correct": false}, {"id": "D", "text": "RSTP 802.1w is rapid STP with discarding/learning/forwarding; fast convergence; Root Bridge is elected root of spanning tree; all ports are designated.", "is_correct": false}]', 'RSTP 802.1w rapid STP with discarding/learning/forwarding; fast convergence. Root Port best path to the root bridge; one per non-root switch.', '{}', 'STP Comparison', 14.0, '3ecc516268a86bec_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10b23725-ac11-4744-9686-202396e1c455', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Loop Guard and STP 802.1D?', '[{"id": "A", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; STP 802.1D is spanning tree with blocking/listening/learning/forwarding; slow convergence.", "is_correct": true}, {"id": "B", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; Root Port is best path to the root bridge; one per non-root switch.", "is_correct": false}, {"id": "C", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; PVST+ is Cisco per-VLAN STP with separate instance per VLAN.", "is_correct": false}, {"id": "D", "text": "Loop Guard is prevents alternate/root ports from becoming designated if BPDUs stop; PortFast is immediately transitions access port to forwarding.", "is_correct": false}]', 'Loop Guard prevents alternate/root ports from becoming designated if BPDUs stop. STP 802.1D spanning tree with blocking/listening/learning/forwarding; slow convergence.', '{}', 'STP Comparison', 14.0, '2f7b01ccc58f493e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
