INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f896e0c-1335-48ec-9731-ed52c797ed15', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between IS-IS GR and LDP GR?', '[{"id": "A", "text": "IS-IS GR is IS-IS graceful restart for hitless IGP restart; HSRP is Cisco Hot Standby Router Protocol active/standby.", "is_correct": false}, {"id": "B", "text": "IS-IS GR is IS-IS graceful restart for hitless IGP restart; LDP GR is LDP graceful restart preserving label bindings.", "is_correct": true}, {"id": "C", "text": "IS-IS GR is IS-IS graceful restart for hitless IGP restart; Link Aggregation is bonding multiple links for bandwidth and redundancy.", "is_correct": false}, {"id": "D", "text": "IS-IS GR is IS-IS graceful restart for hitless IGP restart; Fabric LACP is LACP across chassis cluster members for MC-LAG.", "is_correct": false}]', 'IS-IS GR IS-IS graceful restart for hitless IGP restart. LDP GR LDP graceful restart preserving label bindings.', '{}', 'HA Feature Comparison', 14.0, '6f2864f2d0d9a1b8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
