INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1cc1e0a5-9142-41c4-8f19-f9478a1468f9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the difference between ESI and MAC Mobility?', '[{"id": "A", "text": "ESI is Ethernet Segment Identifier identifying a multi-homed segment; EVI is Ethernet VPN Instance; logical EVPN entity per VNI.", "is_correct": false}, {"id": "B", "text": "ESI is Ethernet Segment Identifier identifying a multi-homed segment; DF Election is Designated Forwarder election per VLAN for multi-homed segments.", "is_correct": false}, {"id": "C", "text": "ESI is Ethernet Segment Identifier identifying a multi-homed segment; MAC Mobility is MAC address movement detection and sequence number tracking.", "is_correct": true}, {"id": "D", "text": "ESI is Ethernet Segment Identifier identifying a multi-homed segment; VNI is VXLAN Network Identifier; 24-bit segment identifier.", "is_correct": false}]', 'ESI Ethernet Segment Identifier identifying a multi-homed segment. MAC Mobility MAC address movement detection and sequence number tracking.', '{}', 'EVPN Comparison', 14.0, 'c634fe08df907aea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da5ddcc2-6af7-40fe-b9e5-762901a01f4b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the difference between Anycast VTEP and EVI?', '[{"id": "A", "text": "Anycast VTEP is multiple VTEPs sharing the same IP for load balancing; EVI is Ethernet VPN Instance; logical EVPN entity per VNI.", "is_correct": true}, {"id": "B", "text": "Anycast VTEP is multiple VTEPs sharing the same IP for load balancing; Asymmetric IRB is ingress VTEP routes; egress VTEP bridges to destination.", "is_correct": false}, {"id": "C", "text": "Anycast VTEP is multiple VTEPs sharing the same IP for load balancing; EVI is Ethernet VPN Instance; logical EVPN entity per VNI.", "is_correct": true}, {"id": "D", "text": "Anycast VTEP is multiple VTEPs sharing the same IP for load balancing; VNI is VXLAN Network Identifier; 24-bit segment identifier.", "is_correct": false}]', 'Anycast VTEP multiple VTEPs sharing the same IP for load balancing. EVI Ethernet VPN Instance; logical EVPN entity per VNI.', '{}', 'EVPN Comparison', 14.0, '6f83e550110ace08_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72b93578-48c1-4bf9-8db6-b3cd3c6de862', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'understand', 'What is the difference between Symmetric IRB and Split Horizon?', '[{"id": "A", "text": "Symmetric IRB is both ingress and egress VTEPs perform routing with VNI translation; Type 4 Route is Ethernet Segment route for DF election.", "is_correct": false}, {"id": "B", "text": "Symmetric IRB is both ingress and egress VTEPs perform routing with VNI translation; VTEP is VXLAN Tunnel Endpoint encapsulating/decapsulating VXLAN traffic.", "is_correct": false}, {"id": "C", "text": "Symmetric IRB is both ingress and egress VTEPs perform routing with VNI translation; Split Horizon is preventing loops by filtering traffic from the same ES.", "is_correct": true}, {"id": "D", "text": "Symmetric IRB is both ingress and egress VTEPs perform routing with VNI translation; Asymmetric IRB is ingress VTEP routes; egress VTEP bridges to destination.", "is_correct": false}]', 'Symmetric IRB both ingress and egress VTEPs perform routing with VNI translation. Split Horizon preventing loops by filtering traffic from the same ES.', '{}', 'EVPN Comparison', 14.0, '9fd8f407081bc1f2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ec19b81-e163-4cca-98fc-852fe1bdb7b3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between MSDP and IGMPv1?', '[{"id": "A", "text": "MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery; (S,G) is Source-specific multicast tree from source to receivers.", "is_correct": false}, {"id": "B", "text": "MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery; IGMPv1 is original IGMP with membership query and report.", "is_correct": true}, {"id": "C", "text": "MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery; RP is Rendezvous Point; meeting point for PIM-SM sources and receivers.", "is_correct": false}, {"id": "D", "text": "MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery; MLDv1 is Multicast Listener Discovery for IPv6.", "is_correct": false}]', 'MSDP Multicast Source Discovery Protocol; inter-domain RP discovery. IGMPv1 original IGMP with membership query and report.', '{}', 'Multicast Protocol Comparison', 14.0, '9e1a63be27722e09_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ede49e4d-85bc-4f8b-acb2-dc6140a3444a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between RP and Assert?', '[{"id": "A", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": true}, {"id": "B", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; RPF Check is Reverse Path Forwarding; verifies multicast arrives on correct interface.", "is_correct": false}, {"id": "C", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; Register is PIM-SM source registration process with RP.", "is_correct": false}, {"id": "D", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; (*,G) is Any-source multicast tree shared RP to receivers.", "is_correct": false}]', 'RP Rendezvous Point; meeting point for PIM-SM sources and receivers. Assert PIM mechanism to elect a single forwarder on multi-access LAN.', '{}', 'Multicast Protocol Comparison', 14.0, '1bbd3cb06f8ba0b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e6f11588-12f5-4fbc-a23b-e98d97daebfd', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between MLDv1 and MSDP?', '[{"id": "A", "text": "MLDv1 is Multicast Listener Discovery for IPv6; MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery.", "is_correct": true}, {"id": "B", "text": "MLDv1 is Multicast Listener Discovery for IPv6; BSR is Bootstrap Router; distributes RP information in PIM domain.", "is_correct": false}, {"id": "C", "text": "MLDv1 is Multicast Listener Discovery for IPv6; IGMPv2 is IGMP with leave-group messages and query election.", "is_correct": false}, {"id": "D", "text": "MLDv1 is Multicast Listener Discovery for IPv6; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": false}]', 'MLDv1 Multicast Listener Discovery for IPv6. MSDP Multicast Source Discovery Protocol; inter-domain RP discovery.', '{}', 'Multicast Protocol Comparison', 14.0, 'd2d4abf37da36c01_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('75d253d8-7336-4f5c-8e83-8c819d9508ea', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between (S,G) and IGMPv2?', '[{"id": "A", "text": "(S,G) is Source-specific multicast tree from source to receivers; MLDv1 is Multicast Listener Discovery for IPv6.", "is_correct": false}, {"id": "B", "text": "(S,G) is Source-specific multicast tree from source to receivers; IGMPv2 is IGMP with leave-group messages and query election.", "is_correct": true}, {"id": "C", "text": "(S,G) is Source-specific multicast tree from source to receivers; (*,G) is Any-source multicast tree shared RP to receivers.", "is_correct": false}, {"id": "D", "text": "(S,G) is Source-specific multicast tree from source to receivers; RP is Rendezvous Point; meeting point for PIM-SM sources and receivers.", "is_correct": false}]', '(S,G) Source-specific multicast tree from source to receivers. IGMPv2 IGMP with leave-group messages and query election.', '{}', 'Multicast Protocol Comparison', 14.0, 'e6a41b2b77223f5e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27ea8ba5-2465-467a-bfb9-dbeebe7ba51f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between RP and BSR?', '[{"id": "A", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; PIM Sparse Mode is RP-based multicast distribution; receivers explicitly join.", "is_correct": false}, {"id": "B", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; IGMPv2 is IGMP with leave-group messages and query election.", "is_correct": false}, {"id": "C", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; PIM Dense Mode is flood-and-prune multicast; initial flood then prune branches.", "is_correct": false}, {"id": "D", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; BSR is Bootstrap Router; distributes RP information in PIM domain.", "is_correct": true}]', 'RP Rendezvous Point; meeting point for PIM-SM sources and receivers. BSR Bootstrap Router; distributes RP information in PIM domain.', '{}', 'Multicast Protocol Comparison', 14.0, '354a2014cfd3ec46_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('125d1935-fce5-4bab-b2f4-c83ae49eb268', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between Register and PIM Dense Mode?', '[{"id": "A", "text": "Register is PIM-SM source registration process with RP; IGMPv2 is IGMP with leave-group messages and query election.", "is_correct": false}, {"id": "B", "text": "Register is PIM-SM source registration process with RP; IGMPv1 is original IGMP with membership query and report.", "is_correct": false}, {"id": "C", "text": "Register is PIM-SM source registration process with RP; PIM Dense Mode is flood-and-prune multicast; initial flood then prune branches.", "is_correct": true}, {"id": "D", "text": "Register is PIM-SM source registration process with RP; (*,G) is Any-source multicast tree shared RP to receivers.", "is_correct": false}]', 'Register PIM-SM source registration process with RP. PIM Dense Mode flood-and-prune multicast; initial flood then prune branches.', '{}', 'Multicast Protocol Comparison', 14.0, '5ae92c83cca0a689_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('166157d9-5e96-4cc8-9606-f7fd99550062', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between (S,G) and PIM Bidirectional?', '[{"id": "A", "text": "(S,G) is Source-specific multicast tree from source to receivers; MLDv2 is MLD with source-specific filtering for IPv6.", "is_correct": false}, {"id": "B", "text": "(S,G) is Source-specific multicast tree from source to receivers; PIM Bidirectional is shared tree multicast; bidirectional traffic on RP tree.", "is_correct": true}, {"id": "C", "text": "(S,G) is Source-specific multicast tree from source to receivers; IGMPv3 is IGMP with source-specific filtering (INCLUDE/EXCLUDE).", "is_correct": false}, {"id": "D", "text": "(S,G) is Source-specific multicast tree from source to receivers; IGMPv2 is IGMP with leave-group messages and query election.", "is_correct": false}]', '(S,G) Source-specific multicast tree from source to receivers. PIM Bidirectional shared tree multicast; bidirectional traffic on RP tree.', '{}', 'Multicast Protocol Comparison', 14.0, '5a28fbd088d436d4_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a47e609-814b-492a-ba6d-589b330c7a0e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between IGMPv2 and IGMPv3?', '[{"id": "A", "text": "IGMPv2 is IGMP with leave-group messages and query election; IGMPv3 is IGMP with source-specific filtering (INCLUDE/EXCLUDE).", "is_correct": true}, {"id": "B", "text": "IGMPv2 is IGMP with leave-group messages and query election; RP is Rendezvous Point; meeting point for PIM-SM sources and receivers.", "is_correct": false}, {"id": "C", "text": "IGMPv2 is IGMP with leave-group messages and query election; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": false}, {"id": "D", "text": "IGMPv2 is IGMP with leave-group messages and query election; Register is PIM-SM source registration process with RP.", "is_correct": false}]', 'IGMPv2 IGMP with leave-group messages and query election. IGMPv3 IGMP with source-specific filtering (INCLUDE/EXCLUDE).', '{}', 'Multicast Protocol Comparison', 14.0, 'bf0faed1cb3baf25_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a1db37a-5c78-46ad-b50e-bd2bdd7e08cc', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between PIM-SSM and Assert?', '[{"id": "A", "text": "PIM-SSM is Source-Specific Multicast using (S,G) channels exclusively; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": true}, {"id": "B", "text": "PIM-SSM is Source-Specific Multicast using (S,G) channels exclusively; PIM Dense Mode is flood-and-prune multicast; initial flood then prune branches.", "is_correct": false}, {"id": "C", "text": "PIM-SSM is Source-Specific Multicast using (S,G) channels exclusively; (S,G) is Source-specific multicast tree from source to receivers.", "is_correct": false}, {"id": "D", "text": "PIM-SSM is Source-Specific Multicast using (S,G) channels exclusively; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": true}]', 'PIM-SSM Source-Specific Multicast using (S,G) channels exclusively. Assert PIM mechanism to elect a single forwarder on multi-access LAN.', '{}', 'Multicast Protocol Comparison', 14.0, 'd706a942bf21bdb6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('829bf6d8-f028-40ba-a320-7fba3a5953fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between PIM Bidirectional and RPF Check?', '[{"id": "A", "text": "PIM Bidirectional is shared tree multicast; bidirectional traffic on RP tree; RPF Check is Reverse Path Forwarding; verifies multicast arrives on correct interface.", "is_correct": true}, {"id": "B", "text": "PIM Bidirectional is shared tree multicast; bidirectional traffic on RP tree; MLDv2 is MLD with source-specific filtering for IPv6.", "is_correct": false}, {"id": "C", "text": "PIM Bidirectional is shared tree multicast; bidirectional traffic on RP tree; RPF Check is Reverse Path Forwarding; verifies multicast arrives on correct interface.", "is_correct": true}, {"id": "D", "text": "PIM Bidirectional is shared tree multicast; bidirectional traffic on RP tree; PIM Sparse Mode is RP-based multicast distribution; receivers explicitly join.", "is_correct": false}]', 'PIM Bidirectional shared tree multicast; bidirectional traffic on RP tree. RPF Check Reverse Path Forwarding; verifies multicast arrives on correct interface.', '{}', 'Multicast Protocol Comparison', 14.0, 'd5bdce82367d2421_gen_v6', true) ON CONFLICT (id) DO NOTHING;
