INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('67615a0e-cc10-4a80-93e5-a02bdd1b6b51', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between (*,G) and Assert?', '[{"id": "A", "text": "(*,G) is Any-source multicast tree shared RP to receivers; MLDv2 is MLD with source-specific filtering for IPv6.", "is_correct": false}, {"id": "B", "text": "(*,G) is Any-source multicast tree shared RP to receivers; MLDv1 is Multicast Listener Discovery for IPv6.", "is_correct": false}, {"id": "C", "text": "(*,G) is Any-source multicast tree shared RP to receivers; Assert is PIM mechanism to elect a single forwarder on multi-access LAN.", "is_correct": true}, {"id": "D", "text": "(*,G) is Any-source multicast tree shared RP to receivers; RP is Rendezvous Point; meeting point for PIM-SM sources and receivers.", "is_correct": false}]', '(*,G) Any-source multicast tree shared RP to receivers. Assert PIM mechanism to elect a single forwarder on multi-access LAN.', '{}', 'Multicast Protocol Comparison', 14.0, '5e1b3f65fee1d1d2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
