INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('402856a7-f09f-4ec2-9e7c-f94e84874926', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between (S,G) and MSDP?', '[{"id": "A", "text": "(S,G) is Source-specific multicast tree from source to receivers; PIM-SSM is Source-Specific Multicast using (S,G) channels exclusively.", "is_correct": false}, {"id": "B", "text": "(S,G) is Source-specific multicast tree from source to receivers; MSDP is Multicast Source Discovery Protocol; inter-domain RP discovery.", "is_correct": true}, {"id": "C", "text": "(S,G) is Source-specific multicast tree from source to receivers; IGMPv3 is IGMP with source-specific filtering (INCLUDE/EXCLUDE).", "is_correct": false}, {"id": "D", "text": "(S,G) is Source-specific multicast tree from source to receivers; MLDv2 is MLD with source-specific filtering for IPv6.", "is_correct": false}]', '(S,G) Source-specific multicast tree from source to receivers. MSDP Multicast Source Discovery Protocol; inter-domain RP discovery.', '{}', 'Multicast Protocol Comparison', 14.0, '4ca32979081d1fd9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c345f9a9-a7fd-450a-812e-7acce48ba2f0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between RP and MLDv2?', '[{"id": "A", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; PIM Dense Mode is flood-and-prune multicast; initial flood then prune branches.", "is_correct": false}, {"id": "B", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; MLDv2 is MLD with source-specific filtering for IPv6.", "is_correct": true}, {"id": "C", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; Register is PIM-SM source registration process with RP.", "is_correct": false}, {"id": "D", "text": "RP is Rendezvous Point; meeting point for PIM-SM sources and receivers; MLDv1 is Multicast Listener Discovery for IPv6.", "is_correct": false}]', 'RP Rendezvous Point; meeting point for PIM-SM sources and receivers. MLDv2 MLD with source-specific filtering for IPv6.', '{}', 'Multicast Protocol Comparison', 14.0, 'ba19607204aff030_gen_v6', true) ON CONFLICT (id) DO NOTHING;
