INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1aef782-a91c-434e-91dc-61634682251f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between AF33 (DSCP 30) and AF21 (DSCP 18)?', '[{"id": "A", "text": "AF33 (DSCP 30) is 011110; CS1 (DSCP 8) is 001000.", "is_correct": false}, {"id": "B", "text": "AF33 (DSCP 30) is 011110; AF42 (DSCP 36) is 100100.", "is_correct": false}, {"id": "C", "text": "AF33 (DSCP 30) is 011110; AF21 (DSCP 18) is 010010.", "is_correct": true}, {"id": "D", "text": "AF33 (DSCP 30) is 011110; AF32 (DSCP 28) is 011100.", "is_correct": false}]', 'AF33 (DSCP 30) 011110. AF21 (DSCP 18) 010010.', '{}', 'QoS Class Comparison', 14.0, 'f27be15e00877504_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('981ea88c-1416-4385-9196-1286634bf2fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between CS6 (DSCP 48) and CS5 (DSCP 40)?', '[{"id": "A", "text": "CS6 (DSCP 48) is 110000; EF (DSCP 46) is 101110.", "is_correct": false}, {"id": "B", "text": "CS6 (DSCP 48) is 110000; AF23 (DSCP 22) is 010110.", "is_correct": false}, {"id": "C", "text": "CS6 (DSCP 48) is 110000; AF11 (DSCP 10) is 001010.", "is_correct": false}, {"id": "D", "text": "CS6 (DSCP 48) is 110000; CS5 (DSCP 40) is 101000.", "is_correct": true}]', 'CS6 (DSCP 48) 110000. CS5 (DSCP 40) 101000.', '{}', 'QoS Class Comparison', 14.0, 'ec5d4a494cc73349_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17f69d7d-14ce-4686-889d-58d90fd0ddf4', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'understand', 'What is the difference between AF33 (DSCP 30) and AF32 (DSCP 28)?', '[{"id": "A", "text": "AF33 (DSCP 30) is 011110; AF32 (DSCP 28) is 011100.", "is_correct": true}, {"id": "B", "text": "AF33 (DSCP 30) is 011110; AF23 (DSCP 22) is 010110.", "is_correct": false}, {"id": "C", "text": "AF33 (DSCP 30) is 011110; AF42 (DSCP 36) is 100100.", "is_correct": false}, {"id": "D", "text": "AF33 (DSCP 30) is 011110; AF21 (DSCP 18) is 010010.", "is_correct": false}]', 'AF33 (DSCP 30) 011110. AF32 (DSCP 28) 011100.', '{}', 'QoS Class Comparison', 14.0, 'dba0a9ced54f0de0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2930f706-ac24-45c1-be25-f1b52e95838a', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'ENT Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3bcfc12-fc74-40ff-ac53-9607004b8a91', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'ENT Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31d07bb6-2b8a-4f68-a834-7c02bcb9aaad', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "The session establishes with the lower hold timer value", "is_correct": true}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'ENT Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('874c30de-69ca-4f57-a6b2-8e123419be07', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router with BGP multipath and two equal-cost eBGP paths
Two paths to the same prefix from different AS. What happens?', '[{"id": "A", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": true}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "C", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "D", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}]', 'Given: A router with BGP multipath and two equal-cost eBGP paths. Two paths to the same prefix from different AS. Result: Both paths are installed in routing table with ECMP if load-balancing is enabled.', '{}', 'ENT Scenarios', 14.0, 'c2dfd31bd6ecf86e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4028db9e-511b-495f-99cb-34de7fa31922', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'ENT Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c794bb1e-3769-4341-980f-5e827e9b6ed5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'ENT Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12125653-504d-40d8-ad81-c786e24a8037', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A QFX switch with MAC learning disabled on a VXLAN VTEP
Unknown destination MAC arrives at the VTEP. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "C", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": true}, {"id": "D", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}]', 'Given: A QFX switch with MAC learning disabled on a VXLAN VTEP. Unknown destination MAC arrives at the VTEP. Result: The switch floods the packet as unknown unicast within the VNI.', '{}', 'ENT Scenarios', 14.0, '9982eccfb7e4fe0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8db63c54-917d-4442-a410-6a852e3db653', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An MPLS network with LDP and RSVP-TE both operating
The same FEC has both LDP label and RSVP-TE label assigned. What happens?', '[{"id": "A", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": true}, {"id": "C", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}]', 'Given: An MPLS network with LDP and RSVP-TE both operating. The same FEC has both LDP label and RSVP-TE label assigned. Result: Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used.', '{}', 'ENT Scenarios', 14.0, '787e12051c214ef6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7becef65-db2a-4bea-8a36-b20aba9a4077', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'ENT Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7064b1be-1096-4dae-ac44-3c06e24be936', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'ENT Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c66e872-d7e6-4d31-8735-20d16b323c5e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'ENT Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7132a86-0dae-4caf-9220-b468b3c5f176', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}, {"id": "D", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'ENT Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a642d1c0-95c7-4fb5-b1b1-4f68d0158485', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A data center with VXLAN EVPN and symmetric IRB
A VM moves from one rack to another rack behind a different leaf. What happens?', '[{"id": "A", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": true}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}]', 'Given: A data center with VXLAN EVPN and symmetric IRB. A VM moves from one rack to another rack behind a different leaf. Result: EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows.', '{}', 'ENT Scenarios', 14.0, '465f900a64924d79_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ec438aca-60db-45d9-a176-ae3da8d4a2e3', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'ENT Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffb69948-8b6a-4cfe-91dd-704bc191dd33', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'ENT Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('898310e1-1c14-4e0e-8191-e975481763ac', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'ENT Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2eb90693-34c9-4528-b95b-c54c12904001', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "C", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'ENT Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('011f6200-a57c-438d-a30f-cef366b2e1e9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'ENT Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4413cce2-75df-4962-a078-65cd8240ba3e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'ENT Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bb23aaf6-b1ab-45ce-b442-a3f5955fb1aa', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": true}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'ENT Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('688c44a4-81b7-4856-b25a-774879f50f08', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers establishing BGP with different local preference defaults
Default local pref is 100 on both sides. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "D", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": true}]', 'Given: Two routers establishing BGP with different local preference defaults. Default local pref is 100 on both sides. Result: Best path selection uses AS path length as tiebreaker.', '{}', 'ENT Scenarios', 14.0, 'd4e7cf99e6074daf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a26acf73-bdc5-4dbd-8a83-509819b7ce09', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}, {"id": "C", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'ENT Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('991b4460-1235-4f49-a27a-8ae514092c4c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "C", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'ENT Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a42a5ac-5117-400b-98a8-377a6e3e647f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'ENT Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4f27026-08a3-44b5-8f3f-ad2be8fb1bc2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'ENT Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f214b0f0-ec3f-4484-9da4-ec03f3092ac2', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "B", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "C", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "D", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'ENT Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c3e25e2-2e9c-4589-845e-ce365b3669a8', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with IS-IS overload bit set on a router
The overloaded router still participates in IS-IS adjacencies. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "B", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": true}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}]', 'Given: A network with IS-IS overload bit set on a router. The overloaded router still participates in IS-IS adjacencies. Result: The router is bypassed for transit traffic but remains reachable for locally connected prefixes.', '{}', 'ENT Scenarios', 14.0, '1467c27797cc64ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d8bc169-4697-4fad-aca0-bd8f5deed7fe', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'ENT Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('570f1036-6970-4bf7-b72e-5c9e3e0b25c6', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'ENT Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df3253f2-5094-47b0-ac16-9a2d96e50822', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper MX router performing inline NAT with session-based logging
NAT session limit is reached during peak traffic. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": true}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}]', 'Given: A Juniper MX router performing inline NAT with session-based logging. NAT session limit is reached during peak traffic. Result: New translation requests are dropped until existing sessions expire or are cleared.', '{}', 'ENT Scenarios', 14.0, '4292b18e0ed185a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dded8761-20c3-4b07-9ed6-2329fb3fb5a5', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
IPv6 OSPFv3 running with link-local addresses only
OSPFv3 adjacency using link-local addresses. What happens?', '[{"id": "A", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": true}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}]', 'Given: IPv6 OSPFv3 running with link-local addresses only. OSPFv3 adjacency using link-local addresses. Result: Adjacency forms using link-local FE80 addresses; global addrs in LSAs only.', '{}', 'ENT Scenarios', 14.0, '35b3d258e1f65844_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca131bf3-efaf-4ac1-a965-777bd27e16e1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "C", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "D", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'ENT Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9df669d3-1d66-4682-a589-5e8b6d2e7fa0', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'ENT Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d2f0882-58c2-4c58-9186-91665e7d125f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX chassis cluster with control link failure
The control link (fab0) goes down but fabric link (fab1) remains up. What happens?', '[{"id": "A", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": true}]', 'Given: An SRX chassis cluster with control link failure. The control link (fab0) goes down but fabric link (fab1) remains up. Result: The cluster splits unless the control link recovers within the timeout.', '{}', 'ENT Scenarios', 14.0, 'a9e409dea06ed9af_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('806cb3c3-06f2-4e7a-97fb-70e5f484c7b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'ENT Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23514bf8-ad42-4a59-90e2-1c955ab0e93d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'ENT Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82aeb279-3bfd-4a26-ad8c-5ce218070170', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "D", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'ENT Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7711a75c-6203-41bd-a08e-a16378bfe100', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An EVPN with symmetric IRB configured for inter-subnet routing
Traffic between two VLANs on different VTEPs. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "B", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": true}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: An EVPN with symmetric IRB configured for inter-subnet routing. Traffic between two VLANs on different VTEPs. Result: Both ingress and egress VTEPs perform routing with VNI translation.', '{}', 'ENT Scenarios', 14.0, '1bd6077f25fc11b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b09df9c-ca2d-4525-8c91-a3ddd6508317', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers connected via serial link with OSPF enabled
MTU mismatch between the two sides. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": true}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "C", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "D", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}]', 'Given: Two routers connected via serial link with OSPF enabled. MTU mismatch between the two sides. Result: OSPF neighbors will be stuck in INIT state.', '{}', 'ENT Scenarios', 14.0, '9960ccd3a83dd2e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ca721638-a18e-417d-ab88-188461eb160d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "B", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'ENT Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc385b53-3139-4de0-86a9-6a06ebb3f5b9', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Spanning tree with root guard configured on an access port
A superior BPDU arrives on the root guard port. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": true}]', 'Given: Spanning tree with root guard configured on an access port. A superior BPDU arrives on the root guard port. Result: The port is moved to root-inconsistent state blocking traffic.', '{}', 'ENT Scenarios', 14.0, '5ad33a78a889c56c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2512492-0b24-4ea3-aed7-96bda86a000f', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'ENT Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3673e6c1-c0d4-49b3-98bb-95b3147e358d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}, {"id": "B", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "C", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "D", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'ENT Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12b02894-0209-436f-afb0-54e82b24451c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper router with GRES enabled and a route is being processed during RE switchover
RE switchover occurs during BGP convergence. What happens?', '[{"id": "A", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": true}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}]', 'Given: A Juniper router with GRES enabled and a route is being processed during RE switchover. RE switchover occurs during BGP convergence. Result: The forwarding table is preserved; BGP needs graceful restart to complete.', '{}', 'ENT Scenarios', 14.0, 'f3a980fe2526c1ce_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b46a5bee-d794-44eb-9b73-45122a3a648b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
BGP community being used to tag customer routes
Provider sets community 64510:100 on customer routes. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "C", "text": "Peers can match this community for traffic engineering and policy", "is_correct": true}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: BGP community being used to tag customer routes. Provider sets community 64510:100 on customer routes. Result: Peers can match this community for traffic engineering and policy.', '{}', 'ENT Scenarios', 14.0, '7dceb717fbccebca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9e57921d-3fd3-428c-93a5-16dccef5fb73', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'ENT Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65afdabe-5108-4750-b504-af5d11a8f61b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'ENT Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd4fa5ac-e0d0-40ec-b2ff-e362dbdd13be', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'ENT Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e10002bd-c002-471e-b61c-f5d5fe7f3e25', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "D", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'ENT Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c6aa4c9-2b95-48b4-af6f-40004812fe2b', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "C", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'ENT Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57500413-1a64-43e4-9c98-1e2aa9a18bdf', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is LDAP and what is its primary purpose?', '[{"id": "A", "text": "directory services and authentication", "is_correct": true}, {"id": "B", "text": "error reporting and network diagnostics", "is_correct": false}, {"id": "C", "text": "IP flow information export; NetFlow v10 standard", "is_correct": false}, {"id": "D", "text": "OSPF for IPv6 with link-local addressing", "is_correct": false}]', 'LDAP: directory services and authentication.', '{}', 'Routing Protocols', 14.0, '63b3fd01fc49b61b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68181390-4cac-4fca-b2cd-b37295cbf50e', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is RIP and what is its primary purpose?', '[{"id": "A", "text": "loop prevention in redundant switched topologies", "is_correct": false}, {"id": "B", "text": "Cisco AAA protocol with separate authentication/authorization", "is_correct": false}, {"id": "C", "text": "inter-domain RP discovery for PIM-SM", "is_correct": false}, {"id": "D", "text": "distance-vector routing using hop count as metric", "is_correct": true}]', 'RIP: distance-vector routing using hop count as metric.', '{}', 'Routing Protocols', 14.0, 'dd28e1b2ebe02caa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36fcf791-a835-463c-98ff-a3f35bfbd50d', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is REP and what is its primary purpose?', '[{"id": "A", "text": "MAC-in-UDP encapsulation for network virtualization", "is_correct": false}, {"id": "B", "text": "multi-link PPP for bonding multiple PPP links", "is_correct": false}, {"id": "C", "text": "link-state routing within a single AS", "is_correct": false}, {"id": "D", "text": "Cisco Resilient Ethernet Protocol for fast ring convergence", "is_correct": true}]', 'REP: Cisco Resilient Ethernet Protocol for fast ring convergence.', '{}', 'Routing Protocols', 14.0, '13e926c525e6d9ab_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21549723-051a-4677-9517-07e1b93d941c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is PAgP and what is its primary purpose?', '[{"id": "A", "text": "Cisco proprietary port aggregation protocol", "is_correct": true}, {"id": "B", "text": "Cisco legacy distance-vector routing (deprecated)", "is_correct": false}, {"id": "C", "text": "OSPF for IPv6 with link-local addressing", "is_correct": false}, {"id": "D", "text": "hypertext transfer for web content", "is_correct": false}]', 'PAgP: Cisco proprietary port aggregation protocol.', '{}', 'Routing Protocols', 14.0, 'ba3d00b2df2fc486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3902be1-07c4-49be-9891-61981a09a284', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is NetFlow and what is its primary purpose?', '[{"id": "A", "text": "multicast source discovery between domains", "is_correct": false}, {"id": "B", "text": "Cisco IP flow monitoring and export protocol", "is_correct": true}, {"id": "C", "text": "Layer 2 VPN with multipoint Ethernet bridging", "is_correct": false}, {"id": "D", "text": "network virtualization using GRE encapsulation", "is_correct": false}]', 'NetFlow: Cisco IP flow monitoring and export protocol.', '{}', 'Routing Protocols', 14.0, 'd2ccaa58a704b90c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('635f596c-e139-4ac7-8523-6e04d527d0b1', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is PIM-Bidir and what is its primary purpose?', '[{"id": "A", "text": "bidirectional shared-tree multicast with RP as root", "is_correct": true}, {"id": "B", "text": "multicast group membership management", "is_correct": false}, {"id": "C", "text": "inter-domain RP discovery for PIM-SM", "is_correct": false}, {"id": "D", "text": "multicast group snooping for IPv6 networks", "is_correct": false}]', 'PIM-Bidir: bidirectional shared-tree multicast with RP as root.', '{}', 'Routing Protocols', 14.0, 'a11d1bc94152c579_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('18c8a1a0-a48f-445b-866f-69d0dac6413c', 'b0000000-0000-0000-0000-000000000011', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 2, 'remember', 'What is DHCP Option 82 and what is its primary purpose?', '[{"id": "A", "text": "PPP encapsulation over Ethernet for broadband access", "is_correct": false}, {"id": "B", "text": "multicast source discovery between domains", "is_correct": false}, {"id": "C", "text": "DHCP relay agent information option for subscriber ID", "is_correct": true}, {"id": "D", "text": "hostname-to-IP resolution with hierarchy", "is_correct": false}]', 'DHCP Option 82: DHCP relay agent information option for subscriber ID.', '{}', 'Routing Protocols', 14.0, '02db78172d28af0c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
