INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0249c64c-d55c-4256-b46a-db8c85cf5ef8', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": true}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'SP Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d153f3c-ba00-46ed-a8bd-b232a6861be0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "C", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73b3b8d4-e191-4fa2-9f5b-c0d66f048e61', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Device not reachable via SNMP. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "C", "text": "community string mismatch or ACL blocking SNMP", "is_correct": true}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'community string mismatch or ACL blocking SNMP. Use show snmp, show ip access-lists to diagnose.', '{}', 'SP Troubleshooting', 14.0, '4629a4f19fc9bcc8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f773760-3614-4653-969c-500392782b24', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "B", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'SP Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e4402d0-9c22-4421-a374-105da5a3423d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": true}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'SP Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81e3901a-cbaf-4502-93a0-ff6f302d9610', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68cc36d3-5dc1-40ec-8882-6bff710c1798', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b853f9dc-5248-492b-81c1-1d5bd3d96de1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": true}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d20ddad4-169c-4ffc-85d6-3dcaa0513b10', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: ARP cache poisoning detected. What is the most likely cause?', '[{"id": "A", "text": "attacker sending fake ARP replies", "is_correct": true}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "D", "text": "priority same or preempt disabled on both routers", "is_correct": false}]', 'attacker sending fake ARP replies. Use show ip arp, show arp, DAI configuration check to diagnose.', '{}', 'SP Troubleshooting', 14.0, '5789f1b6516b4a9e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2474d629-735a-4ae5-8557-fc47afea23d4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fbe19d4b-267d-4c8c-949a-8c40bb4eda41', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "B", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0972abc-3591-4fd5-bcdd-ca40f1ba6c2e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: MLD not discovering IPv6 receivers. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": true}]', 'MLD version mismatch or snooping filter. Use show ipv6 mld groups, show mld snooping to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'b79c866d2f6de491_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dceefd65-fbe2-4727-bd53-d5e4eef9134c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": true}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'SP Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4dc4bc8d-3a56-4d64-b958-aad35c4c7b06', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": true}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'SP Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf15370b-794e-4fc8-8e85-e3f522b0ae70', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'SP Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd0bc8db-1811-4e61-8068-8085345c7823', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP/HSRP failover not working. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": true}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}]', 'priority misconfiguration or preempt disabled. Use show vrrp, show standby brief to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9d85f7c449fe7501_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05a379e1-04a0-4b29-9afe-0a5ab2770892', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d8c7541-e973-4607-a53d-85da17c580b9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd3f3121-4930-467f-bf72-3bf3b25220a3', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": true}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e48e916c-6c1a-4e25-a357-64c8df191f78', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}, {"id": "B", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'SP Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9769241-b63c-40e7-8855-c7d31fbce395', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "missing LSP or label binding", "is_correct": true}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'SP Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de04d0f9-ad95-4313-be0d-b6ff0e69dba9', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('535904ce-54ae-4967-8b9d-7dbcfdd793db', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'SP Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22e1d5d7-6e25-40d3-991b-93e5a46634bb', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "C", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('231d8106-bad8-47dd-8b0c-985002dde5a4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": true}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'SP Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('27496298-78fc-4212-9a67-04210c9fd7b5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": false}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33adfd56-9902-4b80-b7d4-dc61a150122f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'SP Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1f7f2b3-bc63-4d92-9e1b-43fed77eb66a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('632ab6f1-6605-44ea-964d-ff6ceccf9a5a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF neighbors stuck in INIT state. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "MTU mismatch or network type mismatch", "is_correct": true}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'MTU mismatch or network type mismatch. Use show ospf neighbor, monitor interface, check MTU to diagnose.', '{}', 'SP Troubleshooting', 14.0, '728dcf72679e0e0d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91bafe68-6bdf-4f07-9dc7-83b266f73f2e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "missing LSP or label binding", "is_correct": false}, {"id": "B", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'SP Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d37872f9-8d6f-4dd8-8af3-efec76fdf079', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "C", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "D", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'SP Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64b6d4c0-b364-441b-931e-cbe799fcf1f1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06641204-a681-4eb5-b25c-82d794388846', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "C", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}, {"id": "D", "text": "peering receiving too many prefixes", "is_correct": false}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f4ef46b-7532-4835-99f8-ddc3cb4dc9d1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "area ID mismatch or passive interface configuration", "is_correct": true}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'SP Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('64f6fe1e-0977-430c-a2f7-3f1c62e4dbce', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "C", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f8e354d-b307-489a-be7e-0c66cb74996f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MBB and Auto-bandwidth?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.', '{}', 'MPLS Concept Comparison', 14.0, '661139715dd9d34b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14d712af-d2c1-4d41-bbf5-90a965aaa624', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MPLS Label and CSPF?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": true}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": true}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints.', '{}', 'MPLS Concept Comparison', 14.0, '06d9670ec3894481_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c3a35b8-7dbc-420e-ae6c-e82f6e0314b3', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Node Protection and FEC?', '[{"id": "A", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "B", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "C", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "D", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}]', 'Node Protection FRR protecting a node failure bypassing the failed router. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Concept Comparison', 14.0, '96290476a4417b9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('322efd5d-1918-4603-a5ba-43589bbea929', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Label Swap and LDP?', '[{"id": "A", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "Label Swap is replacing the outer MPLS label at transit P routers; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": true}, {"id": "C", "text": "Label Swap is replacing the outer MPLS label at transit P routers; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "D", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'Label Swap replacing the outer MPLS label at transit P routers. LDP Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.', '{}', 'MPLS Concept Comparison', 14.0, 'd8c3d99a50c66f31_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8eb1546f-31a3-4965-a6e3-b0d96c43d6b4', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Link Protection and IGP Shortcut?', '[{"id": "A", "text": "Link Protection is FRR protecting a specific link failure; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "B", "text": "Link Protection is FRR protecting a specific link failure; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "C", "text": "Link Protection is FRR protecting a specific link failure; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "D", "text": "Link Protection is FRR protecting a specific link failure; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}]', 'Link Protection FRR protecting a specific link failure. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Concept Comparison', 14.0, '7ea57b8135a3bfab_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('175812b8-02e1-49d9-8f1f-af0a12a18fae', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between CSPF and Node Protection?', '[{"id": "A", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "B", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "C", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "D", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}]', 'CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'MPLS Concept Comparison', 14.0, 'bc8c0bf5b609485c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b9d1ce1-b561-4457-983c-6cfc35882b00', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between IGP Shortcut and Node Protection?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'MPLS Concept Comparison', 14.0, '4cf9b6514a45dc0a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de85ad94-d11e-4966-bc73-493eca7bf579', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MBB and LER?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. LER Label Edge Router; ingress/egress router pushing/popping labels.', '{}', 'MPLS Concept Comparison', 14.0, '28b77408e96792dc_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b7ffbe94-03a8-4c33-8326-abde74b42a2e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Bypass LSP and MBB?', '[{"id": "A", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "B", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "C", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "D", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}]', 'Bypass LSP FRR backup LSP protecting a set of LSPs through a point of failure. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'MPLS Concept Comparison', 14.0, '7602be234a0b103d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b94a1ab-207a-43dd-b607-5c338e5e4720', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between PE Router and MPLS Label?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": true}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}]', 'PE Router Provider Edge router with VRF and VPN awareness. MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.', '{}', 'MPLS Concept Comparison', 14.0, '3bb5d091680fa943_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db435e03-cc0c-427f-bace-68288823633b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between LDP-over-RSVP and FEC?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Concept Comparison', 14.0, '08a0a3fb55e9af5c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1ebed310-540c-4206-be9f-58e0608e5d82', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between P Router and DiffServ-aware TE?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Concept Comparison', 14.0, '9d3d5b56b5886baa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
