INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c7b020b-46a7-4acc-a425-bf0a24bf698f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Auto-bandwidth and PE Router?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": false}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'MPLS Concept Comparison', 14.0, '679395309ff50ea9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e795bfa5-2cc2-4c29-b61d-361ccd42195a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Label Imposition and Link Protection?', '[{"id": "A", "text": "Label Imposition is pushing a stack of multiple labels at ingress; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "B", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "C", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Link Protection is FRR protecting a specific link failure.", "is_correct": true}, {"id": "D", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}]', 'Label Imposition pushing a stack of multiple labels at ingress. Link Protection FRR protecting a specific link failure.', '{}', 'MPLS Concept Comparison', 14.0, '8f0f3fb7fc859b6b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0c428ba-2716-49c3-91a5-ec1b37c66c60', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MPLS-TE and Label Swap?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": true}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. Label Swap replacing the outer MPLS label at transit P routers.', '{}', 'MPLS Concept Comparison', 14.0, '82a7b32f011f76c2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('799df7c0-7ac0-430b-a3f9-1e4d6682aee7', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Label Swap and DiffServ-aware TE?', '[{"id": "A", "text": "Label Swap is replacing the outer MPLS label at transit P routers; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "B", "text": "Label Swap is replacing the outer MPLS label at transit P routers; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "C", "text": "Label Swap is replacing the outer MPLS label at transit P routers; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "D", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}]', 'Label Swap replacing the outer MPLS label at transit P routers. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Concept Comparison', 14.0, '3e8c1b775bbcbbe7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff45e58b-4ed6-47cd-a378-3e62b486413f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between LDP-over-RSVP and PE Router?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'MPLS Concept Comparison', 14.0, 'c48ea08c42a9f9fe_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11396bde-a5d0-4551-b730-dc1fb3c0620c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between IGP Shortcut and FEC?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Concept Comparison', 14.0, 'cd8f5df390ce713a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d4bc56a-9b1a-4e35-a989-4bed0247f624', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between PE Router and FEC?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}]', 'PE Router Provider Edge router with VRF and VPN awareness. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Concept Comparison', 14.0, '801b8704806b87d6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5d4a6bf-b324-4eaf-b62d-3e5d70fbe58b', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MPLS Label and FEC?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Concept Comparison', 14.0, '682a3513c746846c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4bef3c7-7f04-49f4-92ba-b46048bd8d47', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between FEC and DiffServ-aware TE?', '[{"id": "A", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "C", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}]', 'FEC Forwarding Equivalence Class; group of packets forwarded identically. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Concept Comparison', 14.0, '3846d3716c01576d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d14abded-524e-4393-aa6d-603cc300d113', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Label Push and LSR?', '[{"id": "A", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "B", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "C", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}, {"id": "D", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}]', 'Label Push adding an MPLS label to a packet at the ingress LER. LSR Label Switch Router; core router performing label swapping.', '{}', 'MPLS Concept Comparison', 14.0, '4a44bf2b60abba8c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e32e7515-371c-43d7-b6c4-66bc02bbbfe0', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between LDP-over-RSVP and MPLS-TE?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": true}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": false}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth.', '{}', 'MPLS Concept Comparison', 14.0, '72d96259be83c274_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('718aac99-2505-4d21-a10e-152413853fc6', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Label Imposition and Auto-bandwidth?', '[{"id": "A", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "B", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": true}, {"id": "C", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Link Protection is FRR protecting a specific link failure.", "is_correct": false}, {"id": "D", "text": "Label Imposition is pushing a stack of multiple labels at ingress; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}]', 'Label Imposition pushing a stack of multiple labels at ingress. Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.', '{}', 'MPLS Concept Comparison', 14.0, 'a75a3c90dde8504e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ae926b9-7651-4a54-b6ab-018381f7e424', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between CSPF and DiffServ-aware TE?', '[{"id": "A", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "B", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "C", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "D", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}]', 'CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Concept Comparison', 14.0, 'b615eefd541b735a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06f66108-1d15-4419-95bd-1159d5adad32', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between FRR and RSVP-TE?', '[{"id": "A", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "C", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": true}, {"id": "D", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}]', 'FRR Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover. RSVP-TE RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.', '{}', 'MPLS Concept Comparison', 14.0, '8fc339cc46f0308f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a5a8494-6cc6-40cf-b97d-8b6f09478a8d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between CSPF and LSR?', '[{"id": "A", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "B", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "C", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}]', 'CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints. LSR Label Switch Router; core router performing label swapping.', '{}', 'MPLS Concept Comparison', 14.0, 'ff11dce27a6307a6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfc94293-644d-4e77-892c-2c34c75012b1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Bypass LSP and Label Imposition?', '[{"id": "A", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": true}, {"id": "C", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "D", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}]', 'Bypass LSP FRR backup LSP protecting a set of LSPs through a point of failure. Label Imposition pushing a stack of multiple labels at ingress.', '{}', 'MPLS Concept Comparison', 14.0, 'fc9b85a2a57e48d9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bd702597-89ba-45ad-921a-81d3a2746998', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between Auto-bandwidth and IGP Shortcut?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Concept Comparison', 14.0, 'e443739ced7790d6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dad79f2-a295-4860-99f2-0426b34b660d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between LSR and P Router?', '[{"id": "A", "text": "LSR is Label Switch Router; core router performing label swapping; P Router is Provider core router label-switching without VPN awareness.", "is_correct": true}, {"id": "B", "text": "LSR is Label Switch Router; core router performing label swapping; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "C", "text": "LSR is Label Switch Router; core router performing label swapping; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "D", "text": "LSR is Label Switch Router; core router performing label swapping; P Router is Provider core router label-switching without VPN awareness.", "is_correct": true}]', 'LSR Label Switch Router; core router performing label swapping. P Router Provider core router label-switching without VPN awareness.', '{}', 'MPLS Concept Comparison', 14.0, 'bb5b52f574904879_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d0187287-6afd-403f-847b-a526a364bb8e', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between P Router and IGP Shortcut?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Concept Comparison', 14.0, '6a672338b40736c2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d7d7c05-3e54-46e0-985c-c5a84aa250af', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between PE Router and FRR?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": true}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": true}]', 'PE Router Provider Edge router with VRF and VPN awareness. FRR Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.', '{}', 'MPLS Concept Comparison', 14.0, 'c09af82e8f93c62a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c815ba3e-54d0-4b82-8622-62793b05a48a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between IGP Shortcut and Label Swap?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": true}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. Label Swap replacing the outer MPLS label at transit P routers.', '{}', 'MPLS Concept Comparison', 14.0, 'f7d4a1ba589dfc19_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9a0effbb-2697-40dc-add4-b2ff7a1ee954', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between P Router and LER?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. LER Label Edge Router; ingress/egress router pushing/popping labels.', '{}', 'MPLS Concept Comparison', 14.0, '2b5d0240306c65cf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01d212b8-e57f-4f9b-8ec1-b48ba5b4518f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between LDP and DiffServ-aware TE?', '[{"id": "A", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "B", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "C", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}]', 'LDP Label Distribution Protocol; distributes labels for IGP routes hop-by-hop. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Concept Comparison', 14.0, 'efae35a754ef060c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25a4dfd4-8b7e-4480-b866-a72ba5badedf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between MPLS-TE and LSR?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. LSR Label Switch Router; core router performing label swapping.', '{}', 'MPLS Concept Comparison', 14.0, 'f2381adfce40351a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9334df9-0880-42a2-80b4-0553817fb390', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between FRR and MBB?', '[{"id": "A", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}, {"id": "C", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}]', 'FRR Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'MPLS Concept Comparison', 14.0, '3ce813cde16cf816_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('25c1e2b4-896a-4703-b688-4a7e0be8bf88', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between RSVP-TE and PHP?', '[{"id": "A", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": true}, {"id": "B", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; Link Protection is FRR protecting a specific link failure.", "is_correct": false}, {"id": "C", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'RSVP-TE RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation. PHP Penultimate Hop Popping; penultimate router pops label before egress.', '{}', 'MPLS Concept Comparison', 14.0, '65ac611885b6ba09_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7bf8832-0660-488c-acfe-1fb7f09f1eeb', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', 'What is the difference between PHP and CSPF?', '[{"id": "A", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "B", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": true}, {"id": "C", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}, {"id": "D", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}]', 'PHP Penultimate Hop Popping; penultimate router pops label before egress. CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints.', '{}', 'MPLS Concept Comparison', 14.0, 'cfb1cb6bb7fa3e7d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('941368aa-f378-4459-8fd4-acf5eb399304', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "C", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "D", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'SP Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a8e1761-c847-42ba-ac7d-a099fa14a5cf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Two routers establishing BGP with different local preference defaults
Default local pref is 100 on both sides. What happens?', '[{"id": "A", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": true}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "D", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}]', 'Given: Two routers establishing BGP with different local preference defaults. Default local pref is 100 on both sides. Result: Best path selection uses AS path length as tiebreaker.', '{}', 'SP Scenarios', 14.0, 'd4e7cf99e6074daf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70db0820-dffb-441f-b4a4-665ab7e11142', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "D", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'SP Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24c873d3-f584-42eb-a604-e7c7e9bfcd5f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'SP Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05a27ef8-9416-4b90-b9c0-66a868da022d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'SP Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a97c79a-1329-4618-b514-b2a5a7a89183', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}, {"id": "B", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'SP Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('430721db-a42b-4d2c-a448-a36dd8900c01', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An MPLS network with LDP and RSVP-TE both operating
The same FEC has both LDP label and RSVP-TE label assigned. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": true}, {"id": "D", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}]', 'Given: An MPLS network with LDP and RSVP-TE both operating. The same FEC has both LDP label and RSVP-TE label assigned. Result: Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used.', '{}', 'SP Scenarios', 14.0, '787e12051c214ef6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6376d7be-62f2-46eb-a502-fa8c511d861c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "D", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'SP Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ed441b7-9ab5-4dc3-8be0-e55cdd4f6698', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}, {"id": "D", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'SP Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38977f8a-c1f2-48e3-8683-da26a7cd9326', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'SP Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8b7a1693-08f7-4be8-b876-1e0a421a70c7', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'SP Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff6f61a2-41d9-4a90-a0aa-61869ccf76fc', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'SP Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a47761d1-2b51-41ba-8a60-56498603a14c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Juniper router with GRES enabled and a route is being processed during RE switchover
RE switchover occurs during BGP convergence. What happens?', '[{"id": "A", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": true}, {"id": "B", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: A Juniper router with GRES enabled and a route is being processed during RE switchover. RE switchover occurs during BGP convergence. Result: The forwarding table is preserved; BGP needs graceful restart to complete.', '{}', 'SP Scenarios', 14.0, 'f3a980fe2526c1ce_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('24b88a55-984d-4310-b2ae-056ba8a94f36', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'SP Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('000198a6-3ee2-4fa6-9e59-d381ffacf179', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
BGP community being used to tag customer routes
Provider sets community 64510:100 on customer routes. What happens?', '[{"id": "A", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "Peers can match this community for traffic engineering and policy", "is_correct": true}]', 'Given: BGP community being used to tag customer routes. Provider sets community 64510:100 on customer routes. Result: Peers can match this community for traffic engineering and policy.', '{}', 'SP Scenarios', 14.0, '7dceb717fbccebca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e5896cb-7307-40dd-b6d6-4ea7ca0069e5', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": true}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'SP Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2929cfd5-9c7e-47e5-bfb3-c992de9d9c28', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "C", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'SP Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d04ce13c-0615-4c42-817e-025f343a7c37', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "C", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'SP Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fae2eda0-84cb-4309-96ed-446f6de526e3', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'SP Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ceae130-5191-4e43-a6fc-297a81ab818d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "C", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}, {"id": "D", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'SP Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30cfeefe-0b16-4a21-9943-0f360be1c650', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'SP Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f736cb7c-e5e0-4887-9a9d-a54feb355e45', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "C", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'SP Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('958bc415-dd4a-4de5-bf1c-63315c4e0542', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'SP Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c35eef0f-f121-4231-a87f-0a5eafbcf306', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'SP Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d28cf7e-3b2e-46f2-9c29-28ec13c4b2d1', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'SP Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f0e0419-bbee-4fd4-b4c9-dfb485dd24cf', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'SP Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e77100ff-2251-45e2-beb4-b9f647851e3a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "B", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'SP Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('92368730-a31e-471c-a84d-e8ccb6c6699c', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
Spanning tree with root guard configured on an access port
A superior BPDU arrives on the root guard port. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": true}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}]', 'Given: Spanning tree with root guard configured on an access port. A superior BPDU arrives on the root guard port. Result: The port is moved to root-inconsistent state blocking traffic.', '{}', 'SP Scenarios', 14.0, '5ad33a78a889c56c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ff884ff1-4900-4fcb-87e7-a96d73b66fac', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'SP Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d94b226b-f9b3-49ba-baae-e7929ed0816d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
