INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('60aab4e6-8d7e-4545-90e5-91aadd7b97ef', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Link Protection and LSP?', '[{"id": "A", "text": "Link Protection is FRR protecting a specific link failure; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}, {"id": "B", "text": "Link Protection is FRR protecting a specific link failure; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "C", "text": "Link Protection is FRR protecting a specific link failure; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "D", "text": "Link Protection is FRR protecting a specific link failure; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": true}]', 'Link Protection FRR protecting a specific link failure. LSP Label Switched Path; unidirectional MPLS tunnel path.', '{}', 'Concept Comparison', 14.0, '88d8152210261503_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fed7220d-b648-4f65-a16a-b2a43406b90a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Label Pop and FEC?', '[{"id": "A", "text": "Label Pop is removing the outermost MPLS label (PHP); DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "B", "text": "Label Pop is removing the outermost MPLS label (PHP); FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "C", "text": "Label Pop is removing the outermost MPLS label (PHP); Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "D", "text": "Label Pop is removing the outermost MPLS label (PHP); RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}]', 'Label Pop removing the outermost MPLS label (PHP). FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'Concept Comparison', 14.0, 'ff8ff82751e03747_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ed58fbc-f562-472d-940a-bbfe5e53575d', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Node Protection and Label Imposition?', '[{"id": "A", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "B", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": true}, {"id": "C", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "D", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}]', 'Node Protection FRR protecting a node failure bypassing the failed router. Label Imposition pushing a stack of multiple labels at ingress.', '{}', 'Concept Comparison', 14.0, '0df56b192bbcccc9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f3d80ae-3ed8-425e-b380-c7c8693c9a3f', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Auto-bandwidth and Node Protection?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'Concept Comparison', 14.0, 'd3a6004cb74fb48e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f7d6a9b0-e1ed-420a-8e0b-09bce7f9f776', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MPLS-TE and RSVP-TE?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": true}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": true}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. RSVP-TE RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.', '{}', 'Concept Comparison', 14.0, '54bb6551e034c36c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d96461f-2b62-4054-8c7c-55c5d2ca4305', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MBB and DiffServ-aware TE?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'Concept Comparison', 14.0, 'e0cc8d251ee233b3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
