INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dd409d43-d9a3-4352-b0b9-582171cab0ee', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 SLAAC not providing addresses. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "B", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": true}]', 'RA suppress enabled or M/O flags incorrectly set. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, '99f92805eac8301f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
