INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7fe84b6-ed6a-4fed-95f4-ce5179f02998', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'To diagnose ''Port security violation on switch'', which tool or command should be used?', '[{"id": "A", "text": "show lldp, show lldp interface, set lldp interface", "is_correct": false}, {"id": "B", "text": "show evpn, show ethernet-switching table, show bgp evpn", "is_correct": false}, {"id": "C", "text": "show interfaces, show interfaces diagnostics optics", "is_correct": false}, {"id": "D", "text": "show port-security, show interfaces status err-disabled", "is_correct": true}]', 'Use show port-security, show interfaces status err-disabled to check excessive MAC addresses or sticky MAC misconfiguration.', '{}', 'Troubleshooting Tools', 14.0, '5e528c29f75e0bff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76687aee-d6f4-4870-b7a5-96765c68b14a', 'b0000000-0000-0000-0000-000000000002', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'To diagnose ''Ping fails to remote subnet'', which tool or command should be used?', '[{"id": "A", "text": "show route, show ip access-lists, ping extended", "is_correct": true}, {"id": "B", "text": "show pim rp, show igmp snooping, show mroute", "is_correct": false}, {"id": "C", "text": "show ip dhcp pool, show ip dhcp conflict", "is_correct": false}, {"id": "D", "text": "show route, show route protocol, traceroute", "is_correct": false}]', 'Use show route, show ip access-lists, ping extended to check missing default gateway or ACL blocking ICMP.', '{}', 'Troubleshooting Tools', 14.0, 'a438be1be2440612_gen_v6', true) ON CONFLICT (id) DO NOTHING;
