INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1a85eb03-4d51-4ebe-b09b-eab84413ea7d', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between AppSecure and SecIntel?', '[{"id": "A", "text": "AppSecure is application identification and application-based policies; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": true}, {"id": "B", "text": "AppSecure is application identification and application-based policies; Packet Mode is fast forwarding without stateful inspection.", "is_correct": false}, {"id": "C", "text": "AppSecure is application identification and application-based policies; UserFirewall is identity-based policies using Active Directory integration.", "is_correct": false}, {"id": "D", "text": "AppSecure is application identification and application-based policies; NAT Source is translating private source IPs to public IPs.", "is_correct": false}]', 'AppSecure application identification and application-based policies. SecIntel cloud threat intelligence blocking malicious IPs/URLs.', '{}', 'Security Feature Comparison', 14.0, '14cc5a360a582888_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa3ea806-a254-4f11-8930-457827e2e2a0', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between Policy-based VPN and Packet Mode?', '[{"id": "A", "text": "Policy-based VPN is IPsec triggered by security policy match; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": false}, {"id": "B", "text": "Policy-based VPN is IPsec triggered by security policy match; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "C", "text": "Policy-based VPN is IPsec triggered by security policy match; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "D", "text": "Policy-based VPN is IPsec triggered by security policy match; Packet Mode is fast forwarding without stateful inspection.", "is_correct": true}]', 'Policy-based VPN IPsec triggered by security policy match. Packet Mode fast forwarding without stateful inspection.', '{}', 'Security Feature Comparison', 14.0, 'd9fc6f5867ea3e93_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('85d0c481-9573-4e00-821c-6bef34a13fee', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between IKE Phase 1 and Flow Mode?', '[{"id": "A", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": false}, {"id": "B", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Flow Mode is stateful inspection mode tracking session state.", "is_correct": true}, {"id": "C", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Flow Mode is stateful inspection mode tracking session state.", "is_correct": true}, {"id": "D", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}]', 'IKE Phase 1 authenticated ISAKMP tunnel for management traffic. Flow Mode stateful inspection mode tracking session state.', '{}', 'Security Feature Comparison', 14.0, '1fc053b86f884f1a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('09440ec2-7651-45a1-b1a5-a2f06a52b3a9', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between IDP and AppSecure?', '[{"id": "A", "text": "IDP is Intrusion Detection and Prevention; signature-based traffic inspection; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": false}, {"id": "B", "text": "IDP is Intrusion Detection and Prevention; signature-based traffic inspection; AppSecure is application identification and application-based policies.", "is_correct": true}, {"id": "C", "text": "IDP is Intrusion Detection and Prevention; signature-based traffic inspection; Fabric Link is fab1 interface for session state replication.", "is_correct": false}, {"id": "D", "text": "IDP is Intrusion Detection and Prevention; signature-based traffic inspection; Security Zone is logical interface group with common security policies.", "is_correct": false}]', 'IDP Intrusion Detection and Prevention; signature-based traffic inspection. AppSecure application identification and application-based policies.', '{}', 'Security Feature Comparison', 14.0, 'a17054116b60bd38_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f4d7572-b443-4dd5-8373-cb67826abcc5', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between IKE Phase 2 and AppSecure?', '[{"id": "A", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": false}, {"id": "B", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "C", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": false}, {"id": "D", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; AppSecure is application identification and application-based policies.", "is_correct": true}]', 'IKE Phase 2 IPsec child SA for encrypted data traffic. AppSecure application identification and application-based policies.', '{}', 'Security Feature Comparison', 14.0, 'a4cbaaac692893b7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30024555-9734-414b-938d-0f45f346c17a', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between NAT Destination and IKE Phase 1?', '[{"id": "A", "text": "NAT Destination is translating public destination IPs to private IPs; UTM is unified threat management with antivirus, filtering, and anti-spam.", "is_correct": false}, {"id": "B", "text": "NAT Destination is translating public destination IPs to private IPs; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "C", "text": "NAT Destination is translating public destination IPs to private IPs; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": true}, {"id": "D", "text": "NAT Destination is translating public destination IPs to private IPs; IKE Phase 2 is IPsec child SA for encrypted data traffic.", "is_correct": false}]', 'NAT Destination translating public destination IPs to private IPs. IKE Phase 1 authenticated ISAKMP tunnel for management traffic.', '{}', 'Security Feature Comparison', 14.0, '66f39fff5d412437_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bcfb2fa-9016-428d-9fce-661fc9d02e8a', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 3, 'understand', 'What is the difference between Chassis Cluster and Fabric Link?', '[{"id": "A", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "B", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Fabric Link is fab1 interface for session state replication.", "is_correct": true}, {"id": "C", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Control Link is fab0 interface for chassis cluster control plane IPC.", "is_correct": false}, {"id": "D", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}]', 'Chassis Cluster two SRX devices as HA pair with stateful failover. Fabric Link fab1 interface for session state replication.', '{}', 'Security Feature Comparison', 14.0, '19836c329d6c79f3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
