INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f325aee-7e1e-4f10-a388-58de03ba4004', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between Control Link and Route-based VPN?', '[{"id": "A", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "B", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": true}, {"id": "C", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; Flow Mode is stateful inspection mode tracking session state.", "is_correct": false}, {"id": "D", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; ALG is Application Layer Gateway; deep inspection for embedded IPs/ports.", "is_correct": false}]', 'Control Link fab0 interface for chassis cluster control plane IPC. Route-based VPN IPsec tunnel bound to a st0 interface for routing.', '{}', 'Concept Comparison', 14.0, 'f2fc36c6bb1616ea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4b3162c6-f22f-426a-b85d-3510696bc48f', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between Chassis Cluster and Security Zone?', '[{"id": "A", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; IKE Phase 2 is IPsec child SA for encrypted data traffic.", "is_correct": false}, {"id": "B", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Security Zone is logical interface group with common security policies.", "is_correct": true}, {"id": "C", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "D", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Inter-zone Traffic is traffic between different zones; denied by default.", "is_correct": false}]', 'Chassis Cluster two SRX devices as HA pair with stateful failover. Security Zone logical interface group with common security policies.', '{}', 'Concept Comparison', 14.0, '7c465c018b4fab9f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7d5b44a-b99c-42aa-8b82-3d2e0e87e9d1', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between Control Link and SecIntel?', '[{"id": "A", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; PAT is Port Address Translation; many-to-one with port multiplexing.", "is_correct": false}, {"id": "B", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; Screen is zone-based attack detection and prevention.", "is_correct": false}, {"id": "C", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": true}, {"id": "D", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; UserFirewall is identity-based policies using Active Directory integration.", "is_correct": false}]', 'Control Link fab0 interface for chassis cluster control plane IPC. SecIntel cloud threat intelligence blocking malicious IPs/URLs.', '{}', 'Concept Comparison', 14.0, '692ae59d49368377_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('baf86bb3-4aad-41af-94c1-7c8fba827cd5', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between PAT and IPsec VPN?', '[{"id": "A", "text": "PAT is Port Address Translation; many-to-one with port multiplexing; ALG is Application Layer Gateway; deep inspection for embedded IPs/ports.", "is_correct": false}, {"id": "B", "text": "PAT is Port Address Translation; many-to-one with port multiplexing; UTM is unified threat management with antivirus, filtering, and anti-spam.", "is_correct": false}, {"id": "C", "text": "PAT is Port Address Translation; many-to-one with port multiplexing; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": true}, {"id": "D", "text": "PAT is Port Address Translation; many-to-one with port multiplexing; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": false}]', 'PAT Port Address Translation; many-to-one with port multiplexing. IPsec VPN encrypted tunnel for site-to-site connectivity.', '{}', 'Concept Comparison', 14.0, 'b42897636717cc98_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('65c28124-3f95-4a38-9b48-0f38a7ac6d5e', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between Flow Mode and IPsec VPN?', '[{"id": "A", "text": "Flow Mode is stateful inspection mode tracking session state; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": false}, {"id": "B", "text": "Flow Mode is stateful inspection mode tracking session state; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}, {"id": "C", "text": "Flow Mode is stateful inspection mode tracking session state; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "D", "text": "Flow Mode is stateful inspection mode tracking session state; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": true}]', 'Flow Mode stateful inspection mode tracking session state. IPsec VPN encrypted tunnel for site-to-site connectivity.', '{}', 'Concept Comparison', 14.0, '4a54088faab8963f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
