INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e296e4c1-0796-4502-a53e-b9dfb5f34b5a', 'b0000000-0000-0000-0000-000000000022', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 2, 'understand', 'What is the difference between Policy-based VPN and Intra-zone Traffic?', '[{"id": "A", "text": "Policy-based VPN is IPsec triggered by security policy match; Screen is zone-based attack detection and prevention.", "is_correct": false}, {"id": "B", "text": "Policy-based VPN is IPsec triggered by security policy match; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": false}, {"id": "C", "text": "Policy-based VPN is IPsec triggered by security policy match; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": true}, {"id": "D", "text": "Policy-based VPN is IPsec triggered by security policy match; Inter-zone Traffic is traffic between different zones; denied by default.", "is_correct": false}]', 'Policy-based VPN IPsec triggered by security policy match. Intra-zone Traffic traffic within the same zone; permitted by default.', '{}', 'Concept Comparison', 14.0, 'c6f2c88165a9be6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
