INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7b83736-f777-4204-bd85-068bbd45f1cf', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "D", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'Network Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1e446dd9-db5d-44d0-9270-ce24fb54e367', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'Network Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06c84f91-fec2-48b6-be69-a3ed3011b2ba', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with GRES enabled and a route is being processed during RE switchover
RE switchover occurs during BGP convergence. What happens?', '[{"id": "A", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": true}]', 'Given: A Juniper router with GRES enabled and a route is being processed during RE switchover. RE switchover occurs during BGP convergence. Result: The forwarding table is preserved; BGP needs graceful restart to complete.', '{}', 'Network Scenarios', 14.0, 'f3a980fe2526c1ce_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ed91407-e53f-431c-abf4-909e5b8b1754', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'Network Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d35047f-6121-4e91-8365-0b2b2d5a0597', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS network with LDP and RSVP-TE both operating
The same FEC has both LDP label and RSVP-TE label assigned. What happens?', '[{"id": "A", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": true}, {"id": "B", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "C", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: An MPLS network with LDP and RSVP-TE both operating. The same FEC has both LDP label and RSVP-TE label assigned. Result: Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used.', '{}', 'Network Scenarios', 14.0, '787e12051c214ef6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa0fa591-9f01-48de-b181-17b81215a6bc', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with BGP multipath and two equal-cost eBGP paths
Two paths to the same prefix from different AS. What happens?', '[{"id": "A", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": true}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: A router with BGP multipath and two equal-cost eBGP paths. Two paths to the same prefix from different AS. Result: Both paths are installed in routing table with ECMP if load-balancing is enabled.', '{}', 'Network Scenarios', 14.0, 'c2dfd31bd6ecf86e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a082f4f6-fb03-4f19-b1a3-cb48120c27c9', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'Network Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fe6d6c9-bfd1-4736-8372-1a087170ba10', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "B", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'Network Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94a4f71f-2141-466f-a931-24a54ef86b92', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'Network Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7ea2fba-e5f5-4763-a2ae-9e4774d8ecbe', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "B", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "C", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "D", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'Network Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3de4165b-fef6-4e7f-bce4-821c62824cda', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A data center with VXLAN EVPN and symmetric IRB
A VM moves from one rack to another rack behind a different leaf. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": true}]', 'Given: A data center with VXLAN EVPN and symmetric IRB. A VM moves from one rack to another rack behind a different leaf. Result: EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows.', '{}', 'Network Scenarios', 14.0, '465f900a64924d79_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d489248-e755-47a8-b7c5-ada721402ba7', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX chassis cluster with control link failure
The control link (fab0) goes down but fabric link (fab1) remains up. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": true}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}]', 'Given: An SRX chassis cluster with control link failure. The control link (fab0) goes down but fabric link (fab1) remains up. Result: The cluster splits unless the control link recovers within the timeout.', '{}', 'Network Scenarios', 14.0, 'a9e409dea06ed9af_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c20d92b9-ee66-4ee3-9c37-01a175d3145a', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'Network Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bce6ad20-e7f6-4be3-8d5e-b60b48a130ac', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EVPN with symmetric IRB configured for inter-subnet routing
Traffic between two VLANs on different VTEPs. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": true}, {"id": "C", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "D", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}]', 'Given: An EVPN with symmetric IRB configured for inter-subnet routing. Traffic between two VLANs on different VTEPs. Result: Both ingress and egress VTEPs perform routing with VNI translation.', '{}', 'Network Scenarios', 14.0, '1bd6077f25fc11b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b74408c0-12f4-43a7-883b-6cb9afa8e1d4', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 OSPFv3 running with link-local addresses only
OSPFv3 adjacency using link-local addresses. What happens?', '[{"id": "A", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": true}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "D", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}]', 'Given: IPv6 OSPFv3 running with link-local addresses only. OSPFv3 adjacency using link-local addresses. Result: Adjacency forms using link-local FE80 addresses; global addrs in LSAs only.', '{}', 'Network Scenarios', 14.0, '35b3d258e1f65844_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df3f885e-190f-4bf5-9703-7e6905e56e80', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'Network Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('35130877-64b3-4e3f-a079-e4e40c9a68b8', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'Network Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0767c61-9680-4bd8-bb11-4ff6aacb2bea', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'Network Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cfd94c93-16ad-4693-9dde-0f9094b60326', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'Network Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fef8eba0-4767-4e72-87b9-63105b78945e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'Network Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('547bb462-bd86-4083-9283-9fe80775cbd7', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'Network Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaea91dd-5762-4ac2-aaa9-6c930e8e1172', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with IS-IS overload bit set on a router
The overloaded router still participates in IS-IS adjacencies. What happens?', '[{"id": "A", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": true}]', 'Given: A network with IS-IS overload bit set on a router. The overloaded router still participates in IS-IS adjacencies. Result: The router is bypassed for transit traffic but remains reachable for locally connected prefixes.', '{}', 'Network Scenarios', 14.0, '1467c27797cc64ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('304dfe9f-b185-4777-93a3-2a19337ace1c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'Network Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d1127ae-31a0-4551-ba4c-b77a359cc446', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX router performing inline NAT with session-based logging
NAT session limit is reached during peak traffic. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": true}, {"id": "C", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}]', 'Given: A Juniper MX router performing inline NAT with session-based logging. NAT session limit is reached during peak traffic. Result: New translation requests are dropped until existing sessions expire or are cleared.', '{}', 'Network Scenarios', 14.0, '4292b18e0ed185a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('110ead3c-f99f-4c8f-85b0-ffe4c923b1d0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'Network Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e00b28e-e817-4c75-a7fa-ef294687e07c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'Network Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('52e33aba-8874-4263-9375-3f430636f0ca', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A QFX switch with MAC learning disabled on a VXLAN VTEP
Unknown destination MAC arrives at the VTEP. What happens?', '[{"id": "A", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "B", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": true}]', 'Given: A QFX switch with MAC learning disabled on a VXLAN VTEP. Unknown destination MAC arrives at the VTEP. Result: The switch floods the packet as unknown unicast within the VNI.', '{}', 'Network Scenarios', 14.0, '9982eccfb7e4fe0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('079917bd-e667-4428-b632-090ccd49ebb1', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "C", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "D", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'Network Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2e30bfa-eed9-4152-aeb8-084fcf7dd907', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'Network Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d93806a-9666-4cda-9ea5-3be99ddcc935', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'Network Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8abf2660-6c0e-403f-a422-ff08f09bf92d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'Network Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f39b9ad2-15a8-4d95-a7d4-b95e730010f9', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Spanning tree with root guard configured on an access port
A superior BPDU arrives on the root guard port. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "C", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": true}]', 'Given: Spanning tree with root guard configured on an access port. A superior BPDU arrives on the root guard port. Result: The port is moved to root-inconsistent state blocking traffic.', '{}', 'Network Scenarios', 14.0, '5ad33a78a889c56c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d237ce8-ee0f-4cb6-b6f7-d02b173aa532', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "B", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'Network Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ef1f4c6-0dc9-4729-9943-74ef648ed640', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "C", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'Network Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f68f0149-269b-4fb0-9e14-d4be35d7380d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'Network Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('31d603b1-2537-4359-8e2d-456dca31446f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'Network Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a03e6603-d9a7-42ed-a600-a016b46a2c4e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}, {"id": "C", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'Network Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16c4397f-7853-4427-824d-4aa2bccbba9a', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Network Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('82bb0e02-0ef0-423e-b71b-66f4851df71b', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "C", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "D", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'Network Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bc5be6b-21fe-41bf-a5cc-08089d133267', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'Network Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb12ec94-4095-411d-a8f0-82c5bd1769df', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers connected via serial link with OSPF enabled
MTU mismatch between the two sides. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": true}, {"id": "D", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}]', 'Given: Two routers connected via serial link with OSPF enabled. MTU mismatch between the two sides. Result: OSPF neighbors will be stuck in INIT state.', '{}', 'Network Scenarios', 14.0, '9960ccd3a83dd2e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e131f1d5-5379-4c51-8e01-fee69758bcb5', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "B", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}, {"id": "C", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'Network Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d53f2374-6748-4fff-aba0-c1d244a7ed6e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": true}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'Network Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('add9e9cb-c238-4955-bb2f-f4bd9d3da48b', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'Network Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4789e468-90d1-4d36-8d34-62b8d7d0af98', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": true}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'Network Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d14e290-c51c-45d6-816e-8e482464b183', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'Network Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3682006c-41db-422c-9684-562231934a13', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'Network Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3317a818-d757-430c-b4bd-eafc4297d2d0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers establishing BGP with different local preference defaults
Default local pref is 100 on both sides. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "C", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": true}, {"id": "D", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}]', 'Given: Two routers establishing BGP with different local preference defaults. Default local pref is 100 on both sides. Result: Best path selection uses AS path length as tiebreaker.', '{}', 'Network Scenarios', 14.0, 'd4e7cf99e6074daf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e4cc94-9136-4fab-be32-5684af9a80d5', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'Network Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b0cb5c4b-43fd-486a-a6f7-0e3c7f9573e5', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "query not acknowledged from a neighbor", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('87688384-ed8e-4912-9854-1c3cac0256ae', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "too many concurrent translations exceeding pool size", "is_correct": true}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "C", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('17156641-3c5d-42f6-9ebc-7a48731503cd', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "B", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9bf75d28-5cdf-42e5-8865-a554f570804c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4044f13e-f194-49ac-8960-a5463f81533f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "B", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": true}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d2acc1dc-2cc6-40a9-a820-eba7498cb8a2', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": true}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43b9248d-e1b9-4fc4-a08b-2daed3b30104', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "B", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": false}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6e08c354-a0cb-4ddd-8e96-392990febe5e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "B", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73e3fb49-7822-4aad-ab37-22328c5b2dc4', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP election not working. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": true}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": false}]', 'priority same or preempt disabled on both routers. Use show vrrp, show standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'd1038abcca4baa7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73bae8a7-d7ef-4cd7-97bb-c54ae7bea660', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP stuck in active. What is the most likely cause?', '[{"id": "A", "text": "query not acknowledged from a neighbor", "is_correct": true}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'query not acknowledged from a neighbor. Use show ip eigrp topology, show log, debug eigrp packets to diagnose.', '{}', 'Troubleshooting', 14.0, '0182273873cb1545_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0a2f471d-b63c-4c0b-8533-f9855e50e0b7', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "C", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9953dfd-d5c2-42cb-8eef-4fb21bb1a232', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": false}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('520018c9-86ed-4e3b-b31a-8179b5828e91', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF neighbors stuck in INIT state. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "MTU mismatch or network type mismatch", "is_correct": true}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'MTU mismatch or network type mismatch. Use show ospf neighbor, monitor interface, check MTU to diagnose.', '{}', 'Troubleshooting', 14.0, '728dcf72679e0e0d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42ac124c-c688-486b-9fd4-29b60724e6eb', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('596b77ce-59b5-47b3-87c6-235055271e73', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: QoS marking not applied correctly. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": true}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": false}]', 'class-map not matching or policy-map not applied to interface. Use show policy-map interface, show class-map to diagnose.', '{}', 'Troubleshooting', 14.0, 'e0391e393c4fd21a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c4e34b5-37a1-495f-a340-4f8a376f06aa', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LDP session flapping. What is the most likely cause?', '[{"id": "A", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": true}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'hello interval mismatch or transport address unreachable. Use show ldp session, show route, ping transport-address to diagnose.', '{}', 'Troubleshooting', 14.0, '1bb56e98b1420486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a374762e-d838-4b31-bc66-049af6702f6f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "C", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}, {"id": "D", "text": "missing LSP or label binding", "is_correct": false}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08017863-622c-45d2-86f0-e4f998f989c1', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97bd7239-9843-4111-8c7c-1635453666f0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": true}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('be63dce2-db36-4bab-85f9-d8355ad16584', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b7381ed-54df-486a-8393-958fc938221f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: BGP path selection not optimal. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": true}, {"id": "B", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'local preference or MED configuration. Use show bgp 10.0.0.0, show route protocol bgp to diagnose.', '{}', 'Troubleshooting', 14.0, '8332bfc3943a4701_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00abca8a-0706-47ec-85f0-f43503cfbc47', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0bf5ab2-af6e-447d-98f9-6935b8fdef97', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a74bd59c-0a60-4fcf-991b-f391b21431b8', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Device not reachable via SNMP. What is the most likely cause?', '[{"id": "A", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": true}]', 'community string mismatch or ACL blocking SNMP. Use show snmp, show ip access-lists to diagnose.', '{}', 'Troubleshooting', 14.0, '4629a4f19fc9bcc8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('23f30940-f7d9-4fac-b98a-7a445935bac2', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}, {"id": "B", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "query not acknowledged from a neighbor", "is_correct": false}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21c99034-1a7f-4b03-b682-9d27abbba247', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "missing LSP or label binding", "is_correct": true}, {"id": "C", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9773c4c5-b72c-4f20-96a0-d93d4cc64d04', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Firewall filter blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "term order incorrect or missing accept term", "is_correct": true}, {"id": "B", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'term order incorrect or missing accept term. Use show firewall log, show log messages, monitor traffic to diagnose.', '{}', 'Troubleshooting', 14.0, '4c7b5ac264d85a1c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9043481e-b53a-41cd-bc94-1046b0cbf91d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: ARP cache poisoning detected. What is the most likely cause?', '[{"id": "A", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "B", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "D", "text": "attacker sending fake ARP replies", "is_correct": true}]', 'attacker sending fake ARP replies. Use show ip arp, show arp, DAI configuration check to diagnose.', '{}', 'Troubleshooting', 14.0, '5789f1b6516b4a9e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d6be5320-3497-4ad4-a1f9-c4f3670e42b9', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bbe33070-3130-4119-bd8d-efabc507824b', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: LACP bundle not coming up. What is the most likely cause?', '[{"id": "A", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "B", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": true}]', 'partner configuration mismatch or incompatible speed. Use show etherchannel summary, show lacp neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3698a852089f721_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fc79c64-fc5e-4bb4-9a27-7fabf7b09d66', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}, {"id": "B", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('210828f9-f494-4b72-99b8-15b488b849ee', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: No route to destination in routing table. What is the most likely cause?', '[{"id": "A", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "missing static route or routing policy rejecting the route", "is_correct": true}, {"id": "D", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}]', 'missing static route or routing policy rejecting the route. Use show route, show route protocol, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '9276615101c1c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0f14f231-81f7-40ce-950d-f6bae59852ca', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a16db07a-50d2-420f-9cf0-0f379216eb44', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: NAT not translating addresses. What is the most likely cause?', '[{"id": "A", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": true}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'missing ip nat inside/outside interface or overload keyword. Use show ip nat translations, debug ip nat to diagnose.', '{}', 'Troubleshooting', 14.0, 'e36837feec2e6362_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8f9d67e-0237-4e1c-8d11-fa6db7c44d4b', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing on Juniper. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled at interface level or protocol-level", "is_correct": true}, {"id": "B", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'LLDP disabled at interface level or protocol-level. Use show lldp, show lldp interface, set lldp interface to diagnose.', '{}', 'Troubleshooting', 14.0, '50832e62b4451cc9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cde1c197-eb7f-4064-ab27-8bb2f4e2a286', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}, {"id": "D", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ed71375-9b43-4744-bf7d-21be180a9cc6', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "C", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "D", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('63058ee1-4ba6-4a65-9aa8-96d55f70113f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: MLD not discovering IPv6 receivers. What is the most likely cause?', '[{"id": "A", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": true}]', 'MLD version mismatch or snooping filter. Use show ipv6 mld groups, show mld snooping to diagnose.', '{}', 'Troubleshooting', 14.0, 'b79c866d2f6de491_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9ffe57c-10eb-4af1-a085-39346c9187c8', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "B", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb3098fc-82ad-46fc-b30b-ae36252aa2cf', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c97bb59-8bb5-44c8-9b28-dcc17150472c', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d9c8917-fe53-4a14-ba48-f60d1ff33edf', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Security policy blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": true}, {"id": "B", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "C", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}]', 'missing policy or wrong zone-pair configuration. Use show security policies, show security flow session to diagnose.', '{}', 'Troubleshooting', 14.0, '0ac719102ad083ea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5722cb1-3e9e-4ab9-8adb-6d27bd6e231f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": true}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ef01be7-236b-4327-a416-0ad98dc1d956', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: 802.1X authentication failing. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": true}]', 'RADIUS server unreachable or EAP type mismatch. Use show authentication sessions, debug radius authentication to diagnose.', '{}', 'Troubleshooting', 14.0, 'bafce4e1105d5d56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7391340-93e0-449f-b4dd-b2019cce8dbe', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP/HSRP failover not working. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": true}, {"id": "D", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}]', 'priority misconfiguration or preempt disabled. Use show vrrp, show standby brief to diagnose.', '{}', 'Troubleshooting', 14.0, '9d85f7c449fe7501_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('19f8366d-3dfd-4197-b810-22958c3180ca', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "B", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a943d33f-fd18-4c69-a5f7-d5dea23b4344', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": true}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5467fc6f-9149-4e9f-8141-5fe6e1c78b7a', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 SLAAC not providing addresses. What is the most likely cause?', '[{"id": "A", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": true}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'RA suppress enabled or M/O flags incorrectly set. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, '99f92805eac8301f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b3df5044-61a9-4dd6-abdb-4a867315853e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "B", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": true}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3ca25eb-3194-44c7-a03c-9b3e78fe7c7f', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": true}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "C", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}]', 'LLDP disabled globally or per interface. Use show lldp, show lldp interface ge-0/0/0 to diagnose.', '{}', 'Troubleshooting', 14.0, '41d8508150266f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d9155c-536d-47b6-bb7c-f7660bbd78bb', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "query not acknowledged from a neighbor", "is_correct": false}, {"id": "B", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}, {"id": "C", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ceeabfe8-566b-4f2b-ad6f-28c82c984b9d', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: Interface flapping up and down. What is the most likely cause?', '[{"id": "A", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "B", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": true}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}]', 'faulty SFP, cable issue, or speed/duplex mismatch. Use show interfaces, show interfaces diagnostics optics to diagnose.', '{}', 'Troubleshooting', 14.0, 'e7762a500dbd0227_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c8b9df1-e37f-4edb-81be-f604938f33f3', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "query not acknowledged from a neighbor", "is_correct": false}, {"id": "B", "text": "missing underlay route or VNI configuration error", "is_correct": true}, {"id": "C", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "D", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a547187-2e3d-46b0-8d82-8bf73ef973e0', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP server running out of addresses. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": true}, {"id": "B", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}]', 'lease time too long or subnet too small. Use show ip dhcp pool, show ip dhcp conflict to diagnose.', '{}', 'Troubleshooting', 14.0, '0be06d09ca787cdf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('923a40fc-7394-4ab8-8b64-f4d956e1a0c2', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'To diagnose ''BGP path selection not optimal'', which tool or command should be used?', '[{"id": "A", "text": "show bgp 10.0.0.0, show route protocol bgp", "is_correct": true}, {"id": "B", "text": "show vrrp, show standby brief", "is_correct": false}, {"id": "C", "text": "show interfaces trunk, show vlan", "is_correct": false}, {"id": "D", "text": "show evpn, show ethernet-switching table, show bgp evpn", "is_correct": false}]', 'Use show bgp 10.0.0.0, show route protocol bgp to check local preference or MED configuration.', '{}', 'Troubleshooting Tools', 14.0, '390b63abc867e943_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93c05b87-0755-4541-9669-8dc86f31347e', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'To diagnose ''LACP bundle not coming up'', which tool or command should be used?', '[{"id": "A", "text": "show interfaces, show interfaces diagnostics optics", "is_correct": false}, {"id": "B", "text": "show evpn, show ethernet-switching table, show bgp evpn", "is_correct": false}, {"id": "C", "text": "show route table mpls.0, show ldp session, ping mpls", "is_correct": false}, {"id": "D", "text": "show etherchannel summary, show lacp neighbor", "is_correct": true}]', 'Use show etherchannel summary, show lacp neighbor to check partner configuration mismatch or incompatible speed.', '{}', 'Troubleshooting Tools', 14.0, '344fcfe18ba16877_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a5f20ee6-a73f-476c-8417-c1534eb984e1', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'To diagnose ''NAT not translating addresses'', which tool or command should be used?', '[{"id": "A", "text": "show crypto isakmp sa, show crypto ipsec sa", "is_correct": false}, {"id": "B", "text": "show ip nat translations, debug ip nat", "is_correct": true}, {"id": "C", "text": "show lldp, show interfaces vxlan, traceroute", "is_correct": false}, {"id": "D", "text": "show vrrp, show standby brief", "is_correct": false}]', 'Use show ip nat translations, debug ip nat to check missing ip nat inside/outside interface or overload keyword.', '{}', 'Troubleshooting Tools', 14.0, 'aef61c38529013ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3ea798e-dad1-4447-bda1-5f3c0f527c56', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'To diagnose ''No route to destination in routing table'', which tool or command should be used?', '[{"id": "A", "text": "show ipv6 mld groups, show mld snooping", "is_correct": false}, {"id": "B", "text": "show etherchannel summary, show lacp neighbor", "is_correct": false}, {"id": "C", "text": "show route, show route protocol, traceroute", "is_correct": true}, {"id": "D", "text": "show bgp summary, show log, check max-prefix", "is_correct": false}]', 'Use show route, show route protocol, traceroute to check missing static route or routing policy rejecting the route.', '{}', 'Troubleshooting Tools', 14.0, '10b7aee7e4fd08a0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12677558-c6dd-4dde-9671-4f381c5c1996', 'b0000000-0000-0000-0000-000000000020', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 3, 'apply', 'To diagnose ''Ping works but TCP connections fail'', which tool or command should be used?', '[{"id": "A", "text": "show ip access-lists, extended ping with TCP", "is_correct": true}, {"id": "B", "text": "show system processes, show log messages, show task io", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp, show policy", "is_correct": false}, {"id": "D", "text": "show spanning-tree, show interfaces counters", "is_correct": false}]', 'Use show ip access-lists, extended ping with TCP to check ACL blocking return traffic or TCP MSS issue.', '{}', 'Troubleshooting Tools', 14.0, 'b9f00a685745e941_gen_v6', true) ON CONFLICT (id) DO NOTHING;
