INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e73e9fe3-0fd9-47ad-a714-20e05bc72c6a', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the difference between Commit Scripts and Salt?', '[{"id": "A", "text": "Commit Scripts is validate or modify configuration during commit; Jinja2 is Python templating engine for config generation.", "is_correct": false}, {"id": "B", "text": "Commit Scripts is validate or modify configuration during commit; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}, {"id": "C", "text": "Commit Scripts is validate or modify configuration during commit; Salt is event-driven automation with proxy minions.", "is_correct": true}, {"id": "D", "text": "Commit Scripts is validate or modify configuration during commit; NAPALM is multi-vendor network automation library.", "is_correct": false}]', 'Commit Scripts validate or modify configuration during commit. Salt event-driven automation with proxy minions.', '{}', 'Concept Comparison', 14.0, '7269aa36e2286bb3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012c86e5-e92b-4468-85d6-262e703432fe', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the difference between Salt and Python on Junos?', '[{"id": "A", "text": "Salt is event-driven automation with proxy minions; gRPC is Google RPC for high-performance streaming telemetry.", "is_correct": false}, {"id": "B", "text": "Salt is event-driven automation with proxy minions; Python on Junos is Python interpreter running natively on Junos devices.", "is_correct": true}, {"id": "C", "text": "Salt is event-driven automation with proxy minions; Python on Junos is Python interpreter running natively on Junos devices.", "is_correct": true}, {"id": "D", "text": "Salt is event-driven automation with proxy minions; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}]', 'Salt event-driven automation with proxy minions. Python on Junos Python interpreter running natively on Junos devices.', '{}', 'Concept Comparison', 14.0, 'b41f86e9b8c186b7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('de5cf4e4-ffbc-4e89-a213-52a0ae556678', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the difference between OpenConfig and NETCONF?', '[{"id": "A", "text": "OpenConfig is vendor-neutral YANG models for multi-vendor environments; Op Scripts is on-demand operational automation scripts.", "is_correct": false}, {"id": "B", "text": "OpenConfig is vendor-neutral YANG models for multi-vendor environments; NETCONF is XML-based network config protocol over SSH (RFC 6241).", "is_correct": true}, {"id": "C", "text": "OpenConfig is vendor-neutral YANG models for multi-vendor environments; Kubernetes is container orchestration for cloud-native networking.", "is_correct": false}, {"id": "D", "text": "OpenConfig is vendor-neutral YANG models for multi-vendor environments; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}]', 'OpenConfig vendor-neutral YANG models for multi-vendor environments. NETCONF XML-based network config protocol over SSH (RFC 6241).', '{}', 'Concept Comparison', 14.0, 'ea581126d7558af2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7e636640-180e-424d-a4d5-f63c4ff2b1a2', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 2, 'understand', 'What is the difference between SLAX and Python on Junos?', '[{"id": "A", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; YANG is data modeling language for config and operational state.", "is_correct": false}, {"id": "B", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; Docker is container runtime for containerized network services.", "is_correct": false}, {"id": "C", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; OpenConfig is vendor-neutral YANG models for multi-vendor environments.", "is_correct": false}, {"id": "D", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; Python on Junos is Python interpreter running natively on Junos devices.", "is_correct": true}]', 'SLAX Junos automation language; XML-based with XSLT syntax. Python on Junos Python interpreter running natively on Junos devices.', '{}', 'Concept Comparison', 14.0, 'af7c47f78832fbd8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b1b833c7-7dc3-4bfb-a629-ea9efdbc966c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'Network Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3711f748-8380-44fc-aa7f-5e45e4fecc96', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'Network Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3f2e508-311c-498c-9b16-6e36f9902786', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "B", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'Network Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa7ae16b-9ec2-4e0d-888f-6626df10d740', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "B", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'Network Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2bd3e05-1115-4584-9699-82386372c0eb', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers establishing BGP with different local preference defaults
Default local pref is 100 on both sides. What happens?', '[{"id": "A", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": true}, {"id": "B", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "C", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "D", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}]', 'Given: Two routers establishing BGP with different local preference defaults. Default local pref is 100 on both sides. Result: Best path selection uses AS path length as tiebreaker.', '{}', 'Network Scenarios', 14.0, 'd4e7cf99e6074daf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a47b1ed9-f121-48df-8634-cbb6a15de29e', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}, {"id": "D", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'Network Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e934092-2bfb-44a4-9006-44d9c82669b1', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}, {"id": "B", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "C", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'Network Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0bec2301-a4e1-4a5c-bbbd-f6a765962f59', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "C", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'Network Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32282a5d-5a99-461a-8a69-be28fafc64ba', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A QFX switch with MAC learning disabled on a VXLAN VTEP
Unknown destination MAC arrives at the VTEP. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": true}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "C", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "D", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}]', 'Given: A QFX switch with MAC learning disabled on a VXLAN VTEP. Unknown destination MAC arrives at the VTEP. Result: The switch floods the packet as unknown unicast within the VNI.', '{}', 'Network Scenarios', 14.0, '9982eccfb7e4fe0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5233bfb1-23fc-4921-964f-bcefadde5714', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A data center with VXLAN EVPN and symmetric IRB
A VM moves from one rack to another rack behind a different leaf. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": true}, {"id": "D", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}]', 'Given: A data center with VXLAN EVPN and symmetric IRB. A VM moves from one rack to another rack behind a different leaf. Result: EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows.', '{}', 'Network Scenarios', 14.0, '465f900a64924d79_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a87dfd9-e58f-4b88-82a5-bd0ef28fb400', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}, {"id": "C", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "D", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'Network Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae2d640c-a8a4-4895-9912-f6089e7d7d52', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'Network Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06946436-4758-4f15-b0b3-b676dd9ec013', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'Network Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8dfc0a6-01dc-44b1-ba10-52cf2370c440', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}, {"id": "B", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'Network Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fab26b8-68bc-4487-89b3-5a2a15de7a4c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Spanning tree with root guard configured on an access port
A superior BPDU arrives on the root guard port. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": true}]', 'Given: Spanning tree with root guard configured on an access port. A superior BPDU arrives on the root guard port. Result: The port is moved to root-inconsistent state blocking traffic.', '{}', 'Network Scenarios', 14.0, '5ad33a78a889c56c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44bce6af-be9f-43f5-adf2-c7da48c320d0', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": true}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'Network Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b722c9a-0982-4403-9239-600ca56eb63b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "B", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'Network Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('06cedd8b-d881-4df1-9378-4f2bd0db1e26', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "B", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'Network Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db85af56-979c-4de9-9496-0d1fd7a376cf', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'Network Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e5c69f8a-c253-4258-861f-a0977df77f63', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'Network Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e75f31a7-af95-4593-9e68-0eff8fe69753', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with GRES enabled and a route is being processed during RE switchover
RE switchover occurs during BGP convergence. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": true}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "D", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}]', 'Given: A Juniper router with GRES enabled and a route is being processed during RE switchover. RE switchover occurs during BGP convergence. Result: The forwarding table is preserved; BGP needs graceful restart to complete.', '{}', 'Network Scenarios', 14.0, 'f3a980fe2526c1ce_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f657ad0-e278-4040-8eaf-90d745016d93', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'Network Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9566544-0111-40d0-b864-76209e76970b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "C", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}, {"id": "D", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'Network Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2bcdc176-40a9-441d-a5c1-00058de89381', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with BGP multipath and two equal-cost eBGP paths
Two paths to the same prefix from different AS. What happens?', '[{"id": "A", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": true}, {"id": "D", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}]', 'Given: A router with BGP multipath and two equal-cost eBGP paths. Two paths to the same prefix from different AS. Result: Both paths are installed in routing table with ECMP if load-balancing is enabled.', '{}', 'Network Scenarios', 14.0, 'c2dfd31bd6ecf86e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56a18525-1e33-4a62-b935-157a80529a10', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX chassis cluster with control link failure
The control link (fab0) goes down but fabric link (fab1) remains up. What happens?', '[{"id": "A", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": true}]', 'Given: An SRX chassis cluster with control link failure. The control link (fab0) goes down but fabric link (fab1) remains up. Result: The cluster splits unless the control link recovers within the timeout.', '{}', 'Network Scenarios', 14.0, 'a9e409dea06ed9af_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('163316ad-5fa6-49bc-acf0-a51decc6162b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "C", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'Network Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57c7f13c-eb26-4370-a373-b87368fc47cc', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with IS-IS overload bit set on a router
The overloaded router still participates in IS-IS adjacencies. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": true}]', 'Given: A network with IS-IS overload bit set on a router. The overloaded router still participates in IS-IS adjacencies. Result: The router is bypassed for transit traffic but remains reachable for locally connected prefixes.', '{}', 'Network Scenarios', 14.0, '1467c27797cc64ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('da961dab-b2a7-45bd-ab15-72053d1d8b38', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS network with LDP and RSVP-TE both operating
The same FEC has both LDP label and RSVP-TE label assigned. What happens?', '[{"id": "A", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": true}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}]', 'Given: An MPLS network with LDP and RSVP-TE both operating. The same FEC has both LDP label and RSVP-TE label assigned. Result: Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used.', '{}', 'Network Scenarios', 14.0, '787e12051c214ef6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('892adbbd-7e44-409a-91bd-9bac30e00ca0', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "B", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'Network Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c74e9d70-58e0-41c6-ac6b-27cc5131bf55', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers connected via serial link with OSPF enabled
MTU mismatch between the two sides. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": true}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: Two routers connected via serial link with OSPF enabled. MTU mismatch between the two sides. Result: OSPF neighbors will be stuck in INIT state.', '{}', 'Network Scenarios', 14.0, '9960ccd3a83dd2e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('747b31be-e70c-42aa-ae35-36200d65918f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}, {"id": "B", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'Network Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba7ecdba-6c03-441b-b038-6a5749a4a972', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": true}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'Network Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e086f3f1-e14c-4abd-a392-dc4cf3ca4e86', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'Network Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41a0da09-89b9-485c-9b12-43e051c93604', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 OSPFv3 running with link-local addresses only
OSPFv3 adjacency using link-local addresses. What happens?', '[{"id": "A", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": true}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}]', 'Given: IPv6 OSPFv3 running with link-local addresses only. OSPFv3 adjacency using link-local addresses. Result: Adjacency forms using link-local FE80 addresses; global addrs in LSAs only.', '{}', 'Network Scenarios', 14.0, '35b3d258e1f65844_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6d9a9a84-9db1-4833-b499-689ddc94c2a2', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'Network Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ac2bd73d-051a-451c-bc10-bb386d3d82bd', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'Network Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('302842af-3eae-4ee2-ba84-f6a4262b30f4', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'Network Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98cd5805-b7ea-4b01-a50f-8801ea841a5b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EVPN with symmetric IRB configured for inter-subnet routing
Traffic between two VLANs on different VTEPs. What happens?', '[{"id": "A", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": true}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "C", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "D", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}]', 'Given: An EVPN with symmetric IRB configured for inter-subnet routing. Traffic between two VLANs on different VTEPs. Result: Both ingress and egress VTEPs perform routing with VNI translation.', '{}', 'Network Scenarios', 14.0, '1bd6077f25fc11b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3190a2cb-621d-4f5c-b45c-5c99fd97464d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'Network Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('81f74cc6-b72f-4a19-8317-4711ba19c708', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "C", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Network Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66866ea5-2f5d-44b0-8156-10c5127261bf', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'Network Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d3b4ce34-29d2-4eb0-800f-595cf3aa3047', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'Network Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1aaac72e-561f-426f-a5b9-775843b1701f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}, {"id": "C", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "D", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'Network Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ccd092-9175-4122-a337-f7e6f9c4f25a', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
BGP community being used to tag customer routes
Provider sets community 64510:100 on customer routes. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": true}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}]', 'Given: BGP community being used to tag customer routes. Provider sets community 64510:100 on customer routes. Result: Peers can match this community for traffic engineering and policy.', '{}', 'Network Scenarios', 14.0, '7dceb717fbccebca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1c162cb-728f-4932-af6a-38ddc522b806', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "B", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'Network Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16986574-f2b5-4b6d-8816-19527d4141e1', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "B", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'Network Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c242d41a-e430-4092-8fee-2e37e02682db', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "D", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'Network Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8c18ca7-8b0e-44a9-90ca-9e169e5a932f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'Network Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a300dcc0-a309-4342-b18c-89f6f8cba8af', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX router performing inline NAT with session-based logging
NAT session limit is reached during peak traffic. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": true}, {"id": "C", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "D", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}]', 'Given: A Juniper MX router performing inline NAT with session-based logging. NAT session limit is reached during peak traffic. Result: New translation requests are dropped until existing sessions expire or are cleared.', '{}', 'Network Scenarios', 14.0, '4292b18e0ed185a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ea98ed1f-9d47-4556-84a9-36df744b560f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "C", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'Network Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e05fd8da-883e-47ef-ac81-2391d8687f37', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "B", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "C", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda3116a-c8ed-4f40-aaa6-c9c3eccb377a', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing on Juniper. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled at interface level or protocol-level", "is_correct": true}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}]', 'LLDP disabled at interface level or protocol-level. Use show lldp, show lldp interface, set lldp interface to diagnose.', '{}', 'Troubleshooting', 14.0, '50832e62b4451cc9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4f0ede0-6978-4e79-9fbc-ac12499da94b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP election not working. What is the most likely cause?', '[{"id": "A", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "B", "text": "priority same or preempt disabled on both routers", "is_correct": true}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}]', 'priority same or preempt disabled on both routers. Use show vrrp, show standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'd1038abcca4baa7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d93d49e-d925-4783-9ffb-bfea0438d2eb', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('58ff4b9e-0099-45af-aaa9-489836aff009', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": true}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57720cc0-1715-41de-a9c5-00547aa9b8d6', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: MLD not discovering IPv6 receivers. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": false}, {"id": "B", "text": "MLD version mismatch or snooping filter", "is_correct": true}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'MLD version mismatch or snooping filter. Use show ipv6 mld groups, show mld snooping to diagnose.', '{}', 'Troubleshooting', 14.0, 'b79c866d2f6de491_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0876dee2-c7dd-49f6-a30c-7044c68ebd8a', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "C", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba94b6eb-f075-460a-9711-39f8c34843ad', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b143d01-1072-418d-89c6-576d28bdcb92', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: QoS marking not applied correctly. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": true}]', 'class-map not matching or policy-map not applied to interface. Use show policy-map interface, show class-map to diagnose.', '{}', 'Troubleshooting', 14.0, 'e0391e393c4fd21a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3e98171-6abd-4ad8-85ff-0e6f7f8b2070', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP stuck in active. What is the most likely cause?', '[{"id": "A", "text": "query not acknowledged from a neighbor", "is_correct": true}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}]', 'query not acknowledged from a neighbor. Use show ip eigrp topology, show log, debug eigrp packets to diagnose.', '{}', 'Troubleshooting', 14.0, '0182273873cb1545_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('666d88a9-3824-4d23-b0c9-40e5d98664ff', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "C", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "D", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51eb52f1-f249-4b64-988a-2294cb9ffdf7', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62a9cd36-e876-426f-af17-efae3b81e31d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP server running out of addresses. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "B", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "lease time too long or subnet too small", "is_correct": true}]', 'lease time too long or subnet too small. Use show ip dhcp pool, show ip dhcp conflict to diagnose.', '{}', 'Troubleshooting', 14.0, '0be06d09ca787cdf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c894e6a-8073-4d00-9699-f823a3008bca', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "C", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "D", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('44d7979f-7af3-47c0-8f27-2588ffca3f39', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8454dac3-77d5-4a85-8aed-c260d6298128', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: No route to destination in routing table. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": true}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": false}]', 'missing static route or routing policy rejecting the route. Use show route, show route protocol, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '9276615101c1c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4bb2b386-2e58-4f55-bc6a-19718e24596b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}, {"id": "D", "text": "attacker sending fake ARP replies", "is_correct": false}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b17d6b-0890-4261-94bf-0afab26cff92', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Security policy blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "missing LSP or label binding", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "D", "text": "missing policy or wrong zone-pair configuration", "is_correct": true}]', 'missing policy or wrong zone-pair configuration. Use show security policies, show security flow session to diagnose.', '{}', 'Troubleshooting', 14.0, '0ac719102ad083ea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dc62170-c924-4bec-aa00-dc22ccb4c381', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "B", "text": "MLD version mismatch or snooping filter", "is_correct": false}, {"id": "C", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('80b8b6b0-f0d7-4dc3-9843-82c8d923f195', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: ARP cache poisoning detected. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": true}, {"id": "C", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "D", "text": "MTU mismatch or network type mismatch", "is_correct": false}]', 'attacker sending fake ARP replies. Use show ip arp, show arp, DAI configuration check to diagnose.', '{}', 'Troubleshooting', 14.0, '5789f1b6516b4a9e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb2b9ed-f8bc-4f4e-8932-dad41d04c2a2', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": true}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": false}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5a22730d-5494-4652-930b-0985e4047b25', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "B", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "C", "text": "missing LSP or label binding", "is_correct": true}, {"id": "D", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
