INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14c68db3-f30c-4ee8-b8e2-4d454bd24d3f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: BGP path selection not optimal. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "local preference or MED configuration", "is_correct": true}, {"id": "C", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}]', 'local preference or MED configuration. Use show bgp 10.0.0.0, show route protocol bgp to diagnose.', '{}', 'Troubleshooting', 14.0, '8332bfc3943a4701_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fb85806-0f06-430b-be74-873a081195b0', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "B", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('849e254a-df5c-4fdd-89d7-cdf92504d347', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0cf0754-769c-4147-afdb-9f0ba94e3f3d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "B", "text": "missing underlay route or VNI configuration error", "is_correct": true}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d7de73dd-08e4-4b85-ae19-ba8e36e3c843', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LDP session flapping. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": true}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'hello interval mismatch or transport address unreachable. Use show ldp session, show route, ping transport-address to diagnose.', '{}', 'Troubleshooting', 14.0, '1bb56e98b1420486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c67cea3b-9887-4687-a8af-5ea768db5934', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "kernel route table synchronization issue", "is_correct": true}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('141604b0-449c-4171-a187-ea5c67307b1c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Interface flapping up and down. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "D", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": true}]', 'faulty SFP, cable issue, or speed/duplex mismatch. Use show interfaces, show interfaces diagnostics optics to diagnose.', '{}', 'Troubleshooting', 14.0, 'e7762a500dbd0227_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fff7c9d3-5343-462f-abbc-538da72fd106', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('05470b42-a6f2-46cd-b173-b0000f72627b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "missing LSP or label binding", "is_correct": false}, {"id": "D", "text": "lease time too long or subnet too small", "is_correct": false}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('72720927-8422-41f7-88e8-47f338e75855', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Device not reachable via SNMP. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "community string mismatch or ACL blocking SNMP", "is_correct": true}, {"id": "D", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}]', 'community string mismatch or ACL blocking SNMP. Use show snmp, show ip access-lists to diagnose.', '{}', 'Troubleshooting', 14.0, '4629a4f19fc9bcc8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3782b4af-17f3-43d4-b288-a33a72616bee', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 SLAAC not providing addresses. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "B", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": true}, {"id": "C", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'RA suppress enabled or M/O flags incorrectly set. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, '99f92805eac8301f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2e7c425e-9543-4000-9942-902b85dacc6f', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: NAT not translating addresses. What is the most likely cause?', '[{"id": "A", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "B", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "C", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "D", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": true}]', 'missing ip nat inside/outside interface or overload keyword. Use show ip nat translations, debug ip nat to diagnose.', '{}', 'Troubleshooting', 14.0, 'e36837feec2e6362_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc5e2555-d849-4aa2-a57c-cc7a22e353a1', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": true}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c2ead5b-e7d0-49fc-8218-1a0c85d8416c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": false}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa13a2a1-ecf2-42d3-9eb5-7f2f8076872d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('642ac9bd-9b7e-4bd2-9427-262e286f44ff', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "B", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee71ceed-1106-4255-a00e-39bc67ac4205', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing. What is the most likely cause?', '[{"id": "A", "text": "query not acknowledged from a neighbor", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": true}]', 'LLDP disabled globally or per interface. Use show lldp, show lldp interface ge-0/0/0 to diagnose.', '{}', 'Troubleshooting', 14.0, '41d8508150266f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4ba88940-8dca-4a17-92ad-a7f8f310084c', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "B", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "C", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "D", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3fb89b24-267d-46a5-8a68-596ae58f0c2a', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Ping succeeds but traceroute fails. What is the most likely cause?', '[{"id": "A", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "B", "text": "ICMP time-exceeded blocked by ACL", "is_correct": true}, {"id": "C", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}]', 'ICMP time-exceeded blocked by ACL. Use show ip access-lists, debug ip icmp to diagnose.', '{}', 'Troubleshooting', 14.0, 'f8540ad7d543f70f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ee15ed6-29cc-45b3-8c31-159a4474960d', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "too many concurrent translations exceeding pool size", "is_correct": true}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('def315e0-fc02-4eb4-9b4b-57d88db66a2b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('071c06d4-21f4-4fe2-9a7e-bf8a5ca60548', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}, {"id": "C", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "D", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b742e51-ee42-4666-a06f-93397bea25b3', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c84afb7-13be-4e3e-b576-e44874cea32b', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c335f7b8-daad-4ec6-9c62-1ec6ecf797aa', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": true}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aca8cae5-081c-41f5-bd49-172f85345be4', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "B", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8a26abf2-8cf9-46ad-b5aa-1f4c14b353f3', 'b0000000-0000-0000-0000-000000000021', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 3, 'apply', 'To diagnose ''802.1X authentication failing'', which tool or command should be used?', '[{"id": "A", "text": "show snmp, show ip access-lists", "is_correct": false}, {"id": "B", "text": "show route table mpls.0, show ldp session, ping mpls", "is_correct": false}, {"id": "C", "text": "show ip eigrp topology, show log, debug eigrp packets", "is_correct": false}, {"id": "D", "text": "show authentication sessions, debug radius authentication", "is_correct": true}]', 'Use show authentication sessions, debug radius authentication to check RADIUS server unreachable or EAP type mismatch.', '{}', 'Troubleshooting Tools', 14.0, '9a4e33ff6259fcfa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
