INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a800cd38-7d96-4243-bf3d-2c16947c35b3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": true}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'SP Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dbac03c-9687-47a3-aec5-df85e1208ec0', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "C", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8f0c6155-66e0-4227-b020-d3d4f26e587b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Device not reachable via SNMP. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "C", "text": "community string mismatch or ACL blocking SNMP", "is_correct": true}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'community string mismatch or ACL blocking SNMP. Use show snmp, show ip access-lists to diagnose.', '{}', 'SP Troubleshooting', 14.0, '4629a4f19fc9bcc8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc9365a1-4c95-43e0-b368-fc50d1b35c21', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "B", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'SP Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d112aa3d-25f4-475e-8fc1-1295eb2f0b9e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": true}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "D", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'SP Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1df3fe2f-d73d-48f2-9b59-09489394ae62', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "B", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c64477ec-8a82-42f1-9285-68f3c0283979', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e54d15c-c0cb-4907-935f-e91466cca20b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": true}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9a6453f-f372-48fc-9a40-7ab6d1de7fa1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: ARP cache poisoning detected. What is the most likely cause?', '[{"id": "A", "text": "attacker sending fake ARP replies", "is_correct": true}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "D", "text": "priority same or preempt disabled on both routers", "is_correct": false}]', 'attacker sending fake ARP replies. Use show ip arp, show arp, DAI configuration check to diagnose.', '{}', 'SP Troubleshooting', 14.0, '5789f1b6516b4a9e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95cbc64a-cad5-49ec-9d0e-932084ffb480', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "C", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93cb3caf-59fb-4bcb-8691-2842e4166342', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "B", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('57a2888c-278c-4ee2-9477-0c7d003cbdc2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: MLD not discovering IPv6 receivers. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": true}]', 'MLD version mismatch or snooping filter. Use show ipv6 mld groups, show mld snooping to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'b79c866d2f6de491_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abdbd699-8986-41d4-9f40-3f4da85d847a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": true}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'SP Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62fcdedd-b449-432d-9443-97bbad4ee26f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": true}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'SP Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2a490832-739b-4918-9541-6007aaf18533', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'SP Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('02aa92be-30e8-4227-9ef8-6e3cc4739549', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: VRRP/HSRP failover not working. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": true}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}]', 'priority misconfiguration or preempt disabled. Use show vrrp, show standby brief to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9d85f7c449fe7501_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('20bbe6cb-0cc7-4655-9c45-f120622083a6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('812e0587-89a9-47fe-bdf4-194f97a52dc3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "C", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "D", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51dc76f8-8ab5-45e6-911b-e37ab076372e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "control link failure or threshold timeout too high", "is_correct": true}, {"id": "D", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8aa5c37d-90da-486d-8707-6b4945a2a1ec', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}, {"id": "B", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'SP Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('280e8f03-8978-42b5-89f6-f0b4095dbd48', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "missing LSP or label binding", "is_correct": true}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'SP Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cd517025-a1e5-46c2-860e-6fef484c380a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'SP Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a05e427e-ae08-4155-b0ba-d32371f5c695', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'SP Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d9dfa3a-ba46-40de-be7f-75af6bdeb8b9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "C", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "D", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1fae1e0b-5ebe-4f91-a6be-579c27819758', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": true}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'SP Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51fd11a5-f31d-4450-841d-d5e3e2eeb665', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": false}, {"id": "B", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "C", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e774b90f-35b4-4a68-955a-1adf642671a2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'SP Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb16a756-bdb8-4651-8025-c23c63988f3a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'SP Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('10dfd56c-5ea7-4813-b6b5-fc2855a3bcec', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: OSPF neighbors stuck in INIT state. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "MTU mismatch or network type mismatch", "is_correct": true}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}]', 'MTU mismatch or network type mismatch. Use show ospf neighbor, monitor interface, check MTU to diagnose.', '{}', 'SP Troubleshooting', 14.0, '728dcf72679e0e0d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42c22d35-cd18-4f55-83ff-05e8f93bf8d1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "missing LSP or label binding", "is_correct": false}, {"id": "B", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "D", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'SP Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f8e529a-9c6c-46a6-ae62-732cbed7262a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "C", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "D", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'SP Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('439eeb27-6040-4aa8-a6b3-2036f0c6431c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f9c2b60-05fb-4f2e-bffd-7ea5fc283001', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "B", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "C", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}, {"id": "D", "text": "peering receiving too many prefixes", "is_correct": false}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3139545a-2077-4520-9e02-5957e4cfbf75', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "area ID mismatch or passive interface configuration", "is_correct": true}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'SP Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ce590bb0-c59b-4949-9357-2ff2ee12f592', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "C", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'SP Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('215a6df1-9e4a-4519-9d0a-54dc8a31e263', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MBB and Auto-bandwidth?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.', '{}', 'MPLS Comparison', 14.0, '661139715dd9d34b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('74d26d9a-2f1d-4471-9d4d-7510ae87073b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MPLS Label and CSPF?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": true}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": true}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints.', '{}', 'MPLS Comparison', 14.0, '06d9670ec3894481_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('284a0049-d285-4fb3-9c81-77112fda52d3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Node Protection and FEC?', '[{"id": "A", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "B", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "C", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "D", "text": "Node Protection is FRR protecting a node failure bypassing the failed router; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}]', 'Node Protection FRR protecting a node failure bypassing the failed router. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Comparison', 14.0, '96290476a4417b9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('153a3a51-0e05-4739-8547-6b9c29771855', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Label Swap and LDP?', '[{"id": "A", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "Label Swap is replacing the outer MPLS label at transit P routers; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": true}, {"id": "C", "text": "Label Swap is replacing the outer MPLS label at transit P routers; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "D", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'Label Swap replacing the outer MPLS label at transit P routers. LDP Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.', '{}', 'MPLS Comparison', 14.0, 'd8c3d99a50c66f31_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bea9a983-cb80-44d4-b723-6bd1b299fb5a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Link Protection and IGP Shortcut?', '[{"id": "A", "text": "Link Protection is FRR protecting a specific link failure; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "B", "text": "Link Protection is FRR protecting a specific link failure; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "C", "text": "Link Protection is FRR protecting a specific link failure; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "D", "text": "Link Protection is FRR protecting a specific link failure; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}]', 'Link Protection FRR protecting a specific link failure. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Comparison', 14.0, '7ea57b8135a3bfab_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d392ecc4-3542-4f82-9792-aa4568619111', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between CSPF and Node Protection?', '[{"id": "A", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "B", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "C", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "D", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}]', 'CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'MPLS Comparison', 14.0, 'bc8c0bf5b609485c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8c131b09-f1a5-4930-b4e9-497b5ca4e669', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between IGP Shortcut and Node Protection?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'MPLS Comparison', 14.0, '4cf9b6514a45dc0a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79c77708-b736-4628-97bb-a1adbe16fcf6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MBB and LER?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. LER Label Edge Router; ingress/egress router pushing/popping labels.', '{}', 'MPLS Comparison', 14.0, '28b77408e96792dc_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('506c2d1c-4f5b-42dc-a6b7-5a2ac1169d87', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Bypass LSP and MBB?', '[{"id": "A", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "B", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "C", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "D", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}]', 'Bypass LSP FRR backup LSP protecting a set of LSPs through a point of failure. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'MPLS Comparison', 14.0, '7602be234a0b103d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ba1f465-e7c2-4aa4-844a-e992dc678519', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between PE Router and MPLS Label?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": true}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}]', 'PE Router Provider Edge router with VRF and VPN awareness. MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.', '{}', 'MPLS Comparison', 14.0, '3bb5d091680fa943_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01792262-1e3d-41b4-8a21-25597b47b051', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between LDP-over-RSVP and FEC?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Comparison', 14.0, '08a0a3fb55e9af5c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78c1deb6-551d-4968-bcd8-37a41b3f6e81', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between P Router and DiffServ-aware TE?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Comparison', 14.0, '9d3d5b56b5886baa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61cc8807-eab0-4109-b0f2-4241b7665e08', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between CSPF and MPLS-TE?', '[{"id": "A", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": true}, {"id": "B", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "C", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "D", "text": "CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": true}]', 'CSPF Constraint-based Shortest Path First; RSVP-TE path computation with constraints. MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth.', '{}', 'MPLS Comparison', 14.0, '694d0027f8994c83_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08a173fe-3257-496b-b062-0412823ecd2c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Auto-bandwidth and PE Router?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": false}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'MPLS Comparison', 14.0, '679395309ff50ea9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('302d83f3-8a68-4129-bd08-035ac0ac2103', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Label Imposition and Link Protection?', '[{"id": "A", "text": "Label Imposition is pushing a stack of multiple labels at ingress; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "B", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}, {"id": "C", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Link Protection is FRR protecting a specific link failure.", "is_correct": true}, {"id": "D", "text": "Label Imposition is pushing a stack of multiple labels at ingress; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}]', 'Label Imposition pushing a stack of multiple labels at ingress. Link Protection FRR protecting a specific link failure.', '{}', 'MPLS Comparison', 14.0, '8f0f3fb7fc859b6b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7dc466b3-6248-4436-a31d-c0a2ce8541ce', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MPLS-TE and Label Swap?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": true}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. Label Swap replacing the outer MPLS label at transit P routers.', '{}', 'MPLS Comparison', 14.0, '82a7b32f011f76c2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('588122a7-1b21-4e4d-bb3e-f663f0be42ba', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Label Swap and DiffServ-aware TE?', '[{"id": "A", "text": "Label Swap is replacing the outer MPLS label at transit P routers; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "B", "text": "Label Swap is replacing the outer MPLS label at transit P routers; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "C", "text": "Label Swap is replacing the outer MPLS label at transit P routers; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "D", "text": "Label Swap is replacing the outer MPLS label at transit P routers; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}]', 'Label Swap replacing the outer MPLS label at transit P routers. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Comparison', 14.0, '3e8c1b775bbcbbe7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5adf6c27-00fc-44be-ac4d-4d5bed428d20', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between LDP-over-RSVP and PE Router?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'MPLS Comparison', 14.0, 'c48ea08c42a9f9fe_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d99e3353-25bb-481a-bcbf-96cd8415eb03', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between IGP Shortcut and FEC?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Comparison', 14.0, 'cd8f5df390ce713a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ffbcd64-8b50-4378-a9d1-de5b9972fbe3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between PE Router and FEC?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}]', 'PE Router Provider Edge router with VRF and VPN awareness. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Comparison', 14.0, '801b8704806b87d6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('68b84efd-3c43-4f16-86b0-9c55c00fd860', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MPLS Label and FEC?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'MPLS Comparison', 14.0, '682a3513c746846c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('150a7939-9d0e-45e9-bf41-d5426e3b06e1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between FEC and DiffServ-aware TE?', '[{"id": "A", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "C", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}]', 'FEC Forwarding Equivalence Class; group of packets forwarded identically. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Comparison', 14.0, '3846d3716c01576d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43254cb7-df0d-4a1b-88cd-56a36204bc61', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Label Push and LSR?', '[{"id": "A", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "B", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "C", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}, {"id": "D", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}]', 'Label Push adding an MPLS label to a packet at the ingress LER. LSR Label Switch Router; core router performing label swapping.', '{}', 'MPLS Comparison', 14.0, '4a44bf2b60abba8c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
