INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8b481cb-72d9-431a-9625-a13040e5b4b3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Auto-bandwidth and IGP Shortcut?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": false}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Comparison', 14.0, 'e443739ced7790d6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('523d70af-8444-49a0-898f-b0391143599c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between LSR and P Router?', '[{"id": "A", "text": "LSR is Label Switch Router; core router performing label swapping; P Router is Provider core router label-switching without VPN awareness.", "is_correct": true}, {"id": "B", "text": "LSR is Label Switch Router; core router performing label swapping; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "C", "text": "LSR is Label Switch Router; core router performing label swapping; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "D", "text": "LSR is Label Switch Router; core router performing label swapping; P Router is Provider core router label-switching without VPN awareness.", "is_correct": true}]', 'LSR Label Switch Router; core router performing label swapping. P Router Provider core router label-switching without VPN awareness.', '{}', 'MPLS Comparison', 14.0, 'bb5b52f574904879_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6cc50fce-e293-4e2e-aa5d-387fa8d06b39', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between P Router and IGP Shortcut?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'MPLS Comparison', 14.0, '6a672338b40736c2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76e5593d-b9e4-473c-be07-9b0023d28897', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between PE Router and FRR?', '[{"id": "A", "text": "PE Router is Provider Edge router with VRF and VPN awareness; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "B", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": true}, {"id": "C", "text": "PE Router is Provider Edge router with VRF and VPN awareness; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "PE Router is Provider Edge router with VRF and VPN awareness; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": true}]', 'PE Router Provider Edge router with VRF and VPN awareness. FRR Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.', '{}', 'MPLS Comparison', 14.0, 'c09af82e8f93c62a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bde18caf-1543-4da6-a776-d1468d278f22', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between IGP Shortcut and Label Swap?', '[{"id": "A", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": true}, {"id": "C", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}, {"id": "D", "text": "IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}]', 'IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing. Label Swap replacing the outer MPLS label at transit P routers.', '{}', 'MPLS Comparison', 14.0, 'f7d4a1ba589dfc19_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0721336-5106-41e7-b9da-da1b0ad9acc9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between P Router and LER?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": true}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. LER Label Edge Router; ingress/egress router pushing/popping labels.', '{}', 'MPLS Comparison', 14.0, '2b5d0240306c65cf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('62ccfbd9-ac3b-4cf2-a204-cd20b44b32ee', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between LDP and DiffServ-aware TE?', '[{"id": "A", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "B", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "C", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}]', 'LDP Label Distribution Protocol; distributes labels for IGP routes hop-by-hop. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'MPLS Comparison', 14.0, 'efae35a754ef060c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('616b83df-2adc-422e-84f9-dd36652e5e46', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between MPLS-TE and LSR?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. LSR Label Switch Router; core router performing label swapping.', '{}', 'MPLS Comparison', 14.0, 'f2381adfce40351a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f664d9c-ba62-4eaf-b352-6f8070b71c72', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between FRR and MBB?', '[{"id": "A", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}, {"id": "C", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}]', 'FRR Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'MPLS Comparison', 14.0, '3ce813cde16cf816_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('47d9731d-c6f0-4c8e-bbc6-067a994d38c2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between RSVP-TE and PHP?', '[{"id": "A", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": true}, {"id": "B", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; Link Protection is FRR protecting a specific link failure.", "is_correct": false}, {"id": "C", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation; Label Push is adding an MPLS label to a packet at the ingress LER.", "is_correct": false}]', 'RSVP-TE RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation. PHP Penultimate Hop Popping; penultimate router pops label before egress.', '{}', 'MPLS Comparison', 14.0, '65ac611885b6ba09_gen_v6', true) ON CONFLICT (id) DO NOTHING;
