INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6085f172-a2b9-40fb-9808-ee7987c3a43c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MPLS-TE and RSVP-TE?', '[{"id": "A", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": true}, {"id": "C", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": true}, {"id": "D", "text": "MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}]', 'MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth. RSVP-TE RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.', '{}', 'Concept Comparison', 14.0, '54bb6551e034c36c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f5e0b8ac-ddcc-4f5c-bdff-e06b27297291', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MBB and DiffServ-aware TE?', '[{"id": "A", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "C", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "D", "text": "MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}]', 'MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'Concept Comparison', 14.0, 'e0cc8d251ee233b3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa1d9b89-f710-408c-93cb-7bd73e90ce1d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Bypass LSP and MBB?', '[{"id": "A", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "B", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}, {"id": "C", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "D", "text": "Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}]', 'Bypass LSP FRR backup LSP protecting a set of LSPs through a point of failure. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'Concept Comparison', 14.0, '7602be234a0b103d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3f184e89-60f0-4e6b-9c27-dd8884d0d693', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between PHP and MBB?', '[{"id": "A", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; Link Protection is FRR protecting a specific link failure.", "is_correct": false}, {"id": "B", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}, {"id": "C", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "D", "text": "PHP is Penultimate Hop Popping; penultimate router pops label before egress; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}]', 'PHP Penultimate Hop Popping; penultimate router pops label before egress. MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'Concept Comparison', 14.0, '00faf6265343a1b0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3d243c7e-1e6e-431d-8810-537a06a46b11', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LER and Bypass LSP?', '[{"id": "A", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "B", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "C", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; Bypass LSP is FRR backup LSP protecting a set of LSPs through a point of failure.", "is_correct": true}, {"id": "D", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}]', 'LER Label Edge Router; ingress/egress router pushing/popping labels. Bypass LSP FRR backup LSP protecting a set of LSPs through a point of failure.', '{}', 'Concept Comparison', 14.0, '1bddccfee5f33d36_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5783efcd-bb29-4ef8-afd0-d8dfb301d9e7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Auto-bandwidth and MPLS-TE?', '[{"id": "A", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}, {"id": "B", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "C", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; Link Protection is FRR protecting a specific link failure.", "is_correct": false}, {"id": "D", "text": "Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": true}]', 'Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement. MPLS-TE Traffic Engineering using RSVP for explicit path control and bandwidth.', '{}', 'Concept Comparison', 14.0, '8614698a0a3cf18c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('609bdb14-ad98-48d3-9cf2-d36eeb039ae4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Label Pop and PE Router?', '[{"id": "A", "text": "Label Pop is removing the outermost MPLS label (PHP); LSP is Label Switched Path; unidirectional MPLS tunnel path.", "is_correct": false}, {"id": "B", "text": "Label Pop is removing the outermost MPLS label (PHP); MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "C", "text": "Label Pop is removing the outermost MPLS label (PHP); PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}, {"id": "D", "text": "Label Pop is removing the outermost MPLS label (PHP); RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}]', 'Label Pop removing the outermost MPLS label (PHP). PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'Concept Comparison', 14.0, '3719061754d8eb31_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9e157ce-88c5-4703-b07a-a0b620d366ce', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Label Swap and IGP Shortcut?', '[{"id": "A", "text": "Label Swap is replacing the outer MPLS label at transit P routers; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}, {"id": "B", "text": "Label Swap is replacing the outer MPLS label at transit P routers; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "C", "text": "Label Swap is replacing the outer MPLS label at transit P routers; FRR is Fast Reroute; pre-computed backup MPLS paths for sub-50ms failover.", "is_correct": false}, {"id": "D", "text": "Label Swap is replacing the outer MPLS label at transit P routers; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": true}]', 'Label Swap replacing the outer MPLS label at transit P routers. IGP Shortcut using MPLS LSP as a direct next-hop in IGP routing.', '{}', 'Concept Comparison', 14.0, 'c6499041180f9cb9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
