INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73f4b439-b6a4-46ef-a52a-e7d3218b5d18', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between FEC and DiffServ-aware TE?', '[{"id": "A", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": true}, {"id": "B", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "C", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "D", "text": "FEC is Forwarding Equivalence Class; group of packets forwarded identically; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": false}]', 'FEC Forwarding Equivalence Class; group of packets forwarded identically. DiffServ-aware TE MPLS-TE with per-class bandwidth pools (CT0-CT7).', '{}', 'Concept Comparison', 14.0, '3846d3716c01576d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c12e622-3d7d-4409-b20c-c0360533bd1e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MPLS Label and LDP-over-RSVP?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": true}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": true}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": false}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; P Router is Provider core router label-switching without VPN awareness.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel.', '{}', 'Concept Comparison', 14.0, '51f918e0965ba2a3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5c8d5f53-1de8-4055-a70c-0faf961aaf30', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LDP-over-RSVP and MPLS Label?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.", "is_correct": true}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL.', '{}', 'Concept Comparison', 14.0, 'a7c8e206872d9e9f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e8239d37-c2de-44a6-8e89-09a2b13c28b2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LDP-over-RSVP and Label Pop?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": true}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; CSPF is Constraint-based Shortest Path First; RSVP-TE path computation with constraints.", "is_correct": false}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. Label Pop removing the outermost MPLS label (PHP).', '{}', 'Concept Comparison', 14.0, '1ab34bc3a39130b7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34dca654-49cd-40b6-b27a-d0e95659afeb', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Link Protection and LDP-over-RSVP?', '[{"id": "A", "text": "Link Protection is FRR protecting a specific link failure; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "B", "text": "Link Protection is FRR protecting a specific link failure; LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel.", "is_correct": true}, {"id": "C", "text": "Link Protection is FRR protecting a specific link failure; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "D", "text": "Link Protection is FRR protecting a specific link failure; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}]', 'Link Protection FRR protecting a specific link failure. LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel.', '{}', 'Concept Comparison', 14.0, '56ef80609c10c770_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d005df35-d745-41d9-90a4-e9f8d051d673', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Label Push and PE Router?', '[{"id": "A", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; PE Router is Provider Edge router with VRF and VPN awareness.", "is_correct": true}, {"id": "B", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "C", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": false}, {"id": "D", "text": "Label Push is adding an MPLS label to a packet at the ingress LER; Label Pop is removing the outermost MPLS label (PHP).", "is_correct": false}]', 'Label Push adding an MPLS label to a packet at the ingress LER. PE Router Provider Edge router with VRF and VPN awareness.', '{}', 'Concept Comparison', 14.0, 'f36023e0fa6749e6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af9fa28c-e6fe-4380-a71d-988ace5ba025', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LDP-over-RSVP and Auto-bandwidth?', '[{"id": "A", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}, {"id": "B", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "C", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; LSR is Label Switch Router; core router performing label swapping.", "is_correct": false}, {"id": "D", "text": "LDP-over-RSVP is LDP sessions signaled over an RSVP-TE LSP tunnel; Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": true}]', 'LDP-over-RSVP LDP sessions signaled over an RSVP-TE LSP tunnel. Auto-bandwidth RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.', '{}', 'Concept Comparison', 14.0, '49dc72401619e55c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('873d21d4-7108-49e4-9328-323525eb63d7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between MPLS Label and FEC?', '[{"id": "A", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": true}, {"id": "B", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": false}, {"id": "C", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}, {"id": "D", "text": "MPLS Label is 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL; LDP is Label Distribution Protocol; distributes labels for IGP routes hop-by-hop.", "is_correct": false}]', 'MPLS Label 4-byte shim header: 20-bit label, 3-bit EXP, 1-bit BoS, 8-bit TTL. FEC Forwarding Equivalence Class; group of packets forwarded identically.', '{}', 'Concept Comparison', 14.0, '682a3513c746846c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abdd86b3-a494-461b-aea2-2da844224f1b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LSR and Label Swap?', '[{"id": "A", "text": "LSR is Label Switch Router; core router performing label swapping; MPLS-TE is Traffic Engineering using RSVP for explicit path control and bandwidth.", "is_correct": false}, {"id": "B", "text": "LSR is Label Switch Router; core router performing label swapping; Label Imposition is pushing a stack of multiple labels at ingress.", "is_correct": false}, {"id": "C", "text": "LSR is Label Switch Router; core router performing label swapping; MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": false}, {"id": "D", "text": "LSR is Label Switch Router; core router performing label swapping; Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": true}]', 'LSR Label Switch Router; core router performing label swapping. Label Swap replacing the outer MPLS label at transit P routers.', '{}', 'Concept Comparison', 14.0, 'ac87f7eae9f325b3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e9bf9a00-79a0-435b-a08b-88f4d34de34e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between P Router and Node Protection?', '[{"id": "A", "text": "P Router is Provider core router label-switching without VPN awareness; Node Protection is FRR protecting a node failure bypassing the failed router.", "is_correct": true}, {"id": "B", "text": "P Router is Provider core router label-switching without VPN awareness; PHP is Penultimate Hop Popping; penultimate router pops label before egress.", "is_correct": false}, {"id": "C", "text": "P Router is Provider core router label-switching without VPN awareness; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "P Router is Provider core router label-switching without VPN awareness; LER is Label Edge Router; ingress/egress router pushing/popping labels.", "is_correct": false}]', 'P Router Provider core router label-switching without VPN awareness. Node Protection FRR protecting a node failure bypassing the failed router.', '{}', 'Concept Comparison', 14.0, '7d3f1899fa2bad2d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21cbad40-a506-45d4-add8-bb29d433eb86', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between LER and LSR?', '[{"id": "A", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; FEC is Forwarding Equivalence Class; group of packets forwarded identically.", "is_correct": false}, {"id": "B", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; IGP Shortcut is using MPLS LSP as a direct next-hop in IGP routing.", "is_correct": false}, {"id": "C", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; RSVP-TE is RSVP with Traffic Engineering; signals MPLS LSPs with bandwidth reservation.", "is_correct": false}, {"id": "D", "text": "LER is Label Edge Router; ingress/egress router pushing/popping labels; LSR is Label Switch Router; core router performing label swapping.", "is_correct": true}]', 'LER Label Edge Router; ingress/egress router pushing/popping labels. LSR Label Switch Router; core router performing label swapping.', '{}', 'Concept Comparison', 14.0, 'c9a509f5e9b4cc91_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fb6e1e80-e450-444f-afea-0f4fcc5f118e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', 'What is the difference between Label Pop and MBB?', '[{"id": "A", "text": "Label Pop is removing the outermost MPLS label (PHP); Auto-bandwidth is RSVP-TE automatically adjusting LSP bandwidth based on traffic measurement.", "is_correct": false}, {"id": "B", "text": "Label Pop is removing the outermost MPLS label (PHP); MBB is Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.", "is_correct": true}, {"id": "C", "text": "Label Pop is removing the outermost MPLS label (PHP); DiffServ-aware TE is MPLS-TE with per-class bandwidth pools (CT0-CT7).", "is_correct": false}, {"id": "D", "text": "Label Pop is removing the outermost MPLS label (PHP); Label Swap is replacing the outer MPLS label at transit P routers.", "is_correct": false}]', 'Label Pop removing the outermost MPLS label (PHP). MBB Make-Before-Break; signaling new LSP before removing old one to avoid traffic loss.', '{}', 'Concept Comparison', 14.0, 'a1920a96d9112d3d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('38c98534-346d-44f4-94fe-7ba80f44d6e6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A data center with VXLAN EVPN and symmetric IRB
A VM moves from one rack to another rack behind a different leaf. What happens?', '[{"id": "A", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": false}, {"id": "B", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": true}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: A data center with VXLAN EVPN and symmetric IRB. A VM moves from one rack to another rack behind a different leaf. Result: EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows.', '{}', 'Network Scenarios', 14.0, '465f900a64924d79_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b400018-2a38-43e8-99dd-5a870d57c45f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A QFX switch with MAC learning disabled on a VXLAN VTEP
Unknown destination MAC arrives at the VTEP. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": true}]', 'Given: A QFX switch with MAC learning disabled on a VXLAN VTEP. Unknown destination MAC arrives at the VTEP. Result: The switch floods the packet as unknown unicast within the VNI.', '{}', 'Network Scenarios', 14.0, '9982eccfb7e4fe0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cdf0c15-576d-413c-a575-935d170fed32', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 OSPFv3 running with link-local addresses only
OSPFv3 adjacency using link-local addresses. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": true}, {"id": "D", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}]', 'Given: IPv6 OSPFv3 running with link-local addresses only. OSPFv3 adjacency using link-local addresses. Result: Adjacency forms using link-local FE80 addresses; global addrs in LSAs only.', '{}', 'Network Scenarios', 14.0, '35b3d258e1f65844_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4490ca59-bb82-4549-9d3c-f22507c448b3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "C", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Network Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7535d8fa-bbed-4f89-8c79-5c6652eec1be', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco DHCP Snooping enabled on an access switch
An untrusted port receives a DHCP OFFER message. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": true}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: Cisco DHCP Snooping enabled on an access switch. An untrusted port receives a DHCP OFFER message. Result: The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs.', '{}', 'Network Scenarios', 14.0, 'ecb223977a92c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5ef1f0fd-a13b-475d-8fe5-02bf3c7c7b76', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Cisco port-channel configured with all active member links
One member link goes down. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": true}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: Cisco port-channel configured with all active member links. One member link goes down. Result: Traffic is rebalanced across remaining member links with minimal packet loss.', '{}', 'Network Scenarios', 14.0, '8706188557aa3406_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dda9cdb4-7e9c-4949-9917-f73317d3b5f9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers establishing BGP with different local preference defaults
Default local pref is 100 on both sides. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "D", "text": "Best path selection uses AS path length as tiebreaker", "is_correct": true}]', 'Given: Two routers establishing BGP with different local preference defaults. Default local pref is 100 on both sides. Result: Best path selection uses AS path length as tiebreaker.', '{}', 'Network Scenarios', 14.0, 'd4e7cf99e6074daf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ae1ceb4-0b67-4213-b6fa-76fd6661f355', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}, {"id": "B", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'Network Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('28656faa-9e31-4b5c-88da-e8e34c364136', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Spanning tree with root guard configured on an access port
A superior BPDU arrives on the root guard port. What happens?', '[{"id": "A", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "B", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": true}, {"id": "C", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "D", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}]', 'Given: Spanning tree with root guard configured on an access port. A superior BPDU arrives on the root guard port. Result: The port is moved to root-inconsistent state blocking traffic.', '{}', 'Network Scenarios', 14.0, '5ad33a78a889c56c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3af428f7-f8f0-49e2-acd6-40e5018b290d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}, {"id": "B", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'Network Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d46e9f6-2c02-4305-99ec-cc4bfa9d0b4a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper MX router performing inline NAT with session-based logging
NAT session limit is reached during peak traffic. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": true}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}]', 'Given: A Juniper MX router performing inline NAT with session-based logging. NAT session limit is reached during peak traffic. Result: New translation requests are dropped until existing sessions expire or are cleared.', '{}', 'Network Scenarios', 14.0, '4292b18e0ed185a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd737117-77db-4569-b2cc-3a131864cdbe', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'Network Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('69b99a43-d10d-4af3-a2b4-e71b138ceeb4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'Network Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a545cd26-adf4-4901-b286-c56b8e32441f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
MPLS VPN configured with overlapping customer IP addresses
Two customers use 10.0.0.0/8 for their internal networks. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": true}]', 'Given: MPLS VPN configured with overlapping customer IP addresses. Two customers use 10.0.0.0/8 for their internal networks. Result: Routes are kept separate using VRFs and route distinguishers.', '{}', 'Network Scenarios', 14.0, '7fecdddac5e551a1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b9162486-4b09-41bb-b2be-b12ffcd549d1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "C", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'Network Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01d47d17-a42c-4a88-b382-5c179d8c6388', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'Network Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('91b7cc6f-73d7-4c1e-9916-d058c42f2a2c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco router with BGP deterministic-med and med missing on some paths
Paths with missing MED are compared as having MED 0. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": true}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: A Cisco router with BGP deterministic-med and med missing on some paths. Paths with missing MED are compared as having MED 0. Result: With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0.', '{}', 'Network Scenarios', 14.0, 'a7530dfbebc584e0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dcae5dfc-ddd1-444a-9bca-3ef6e1b44b07', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two ISIS routers with different NET addresses in the same area
NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "C", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": true}, {"id": "D", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}]', 'Given: Two ISIS routers with different NET addresses in the same area. NET: 49.0001.0100.0000.0001.00 and 49.0001.0100.0000.0002.00. Result: Both routers establish a Level 1 adjacency in area 49.0001.', '{}', 'Network Scenarios', 14.0, 'aed30e17fb0fc036_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8ef4e85e-bc09-4613-b8bd-8f9e8f0e87c7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX chassis cluster with control link failure
The control link (fab0) goes down but fabric link (fab1) remains up. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "B", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}, {"id": "C", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": true}]', 'Given: An SRX chassis cluster with control link failure. The control link (fab0) goes down but fabric link (fab1) remains up. Result: The cluster splits unless the control link recovers within the timeout.', '{}', 'Network Scenarios', 14.0, 'a9e409dea06ed9af_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8d757bc-8528-4a5f-bb2e-9d1a323ae21f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": true}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'Network Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc86000d-38af-41a3-b4e8-678a9475ca8d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with GRES enabled and a route is being processed during RE switchover
RE switchover occurs during BGP convergence. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": true}]', 'Given: A Juniper router with GRES enabled and a route is being processed during RE switchover. RE switchover occurs during BGP convergence. Result: The forwarding table is preserved; BGP needs graceful restart to complete.', '{}', 'Network Scenarios', 14.0, 'f3a980fe2526c1ce_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a614c2c9-7561-4e8e-a11c-ec9afb1b2b7c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "C", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}, {"id": "D", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": false}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'Network Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffd25f9b-e8d3-432c-9ab9-a13a496b40ae', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'Network Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a4e479a1-8d4d-4f72-8c53-7895060c00fe', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'Network Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5731ad78-0216-4777-aec7-db423f3bb6c6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "B", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "C", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "D", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'Network Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9d0868bb-1382-4a00-8e34-7ba0bacee8a4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "B", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "C", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'Network Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98cc3c93-e9ae-48fd-856f-d2c2d0ff93f8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}, {"id": "C", "text": "The FTP data channel fails since no ALG is configured", "is_correct": false}, {"id": "D", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'Network Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e704b878-d3b8-432d-8961-885d9074e128', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A switch port configured with port-security and maximum MAC count 2
A third device attempts to connect. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": true}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}]', 'Given: A switch port configured with port-security and maximum MAC count 2. A third device attempts to connect. Result: The port enters err-disable state and blocks traffic.', '{}', 'Network Scenarios', 14.0, '11ee74e1a60a0883_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50d2ec07-89c5-4047-9281-e883a0c41a1d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
VXLAN with BGP EVPN and Type 2 routes for host reachability
Host MAC and IP are learned on a VTEP. What happens?', '[{"id": "A", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "B", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "C", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": true}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}]', 'Given: VXLAN with BGP EVPN and Type 2 routes for host reachability. Host MAC and IP are learned on a VTEP. Result: Type 2 route with MAC/IP is advertised to remote VTEPs via BGP.', '{}', 'Network Scenarios', 14.0, '3a866e8d57d5888d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e98bde79-8e8b-4203-829b-8badcf5a5d42', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EVPN with symmetric IRB configured for inter-subnet routing
Traffic between two VLANs on different VTEPs. What happens?', '[{"id": "A", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": true}, {"id": "B", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": false}]', 'Given: An EVPN with symmetric IRB configured for inter-subnet routing. Traffic between two VLANs on different VTEPs. Result: Both ingress and egress VTEPs perform routing with VNI translation.', '{}', 'Network Scenarios', 14.0, '1bd6077f25fc11b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f60e120a-94fa-4a81-9e7a-76b9f7cc063c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router with BGP multipath and two equal-cost eBGP paths
Two paths to the same prefix from different AS. What happens?', '[{"id": "A", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "B", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "C", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "D", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": true}]', 'Given: A router with BGP multipath and two equal-cost eBGP paths. Two paths to the same prefix from different AS. Result: Both paths are installed in routing table with ECMP if load-balancing is enabled.', '{}', 'Network Scenarios', 14.0, 'c2dfd31bd6ecf86e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('492d0762-5e74-4027-a473-6f27caa4ddbd', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
OSPF virtual link between two non-backbone areas through Area 0
The virtual link connects Area 1 and Area 2 through Area 0. What happens?', '[{"id": "A", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "B", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "C", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": true}]', 'Given: OSPF virtual link between two non-backbone areas through Area 0. The virtual link connects Area 1 and Area 2 through Area 0. Result: Virtual link works but both areas must connect through the same ABR for stability.', '{}', 'Network Scenarios', 14.0, '34ed4458b1192e6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fffa3aa-4174-44a6-a9db-043f91516b73', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'Network Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc42d189-dfb3-4cfa-9ba4-4a1aaab97efd', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch with DHCP snooping and DAI enabled
An attacker sends a DHCP REQUEST with a fake chaddr MAC. What happens?', '[{"id": "A", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": true}, {"id": "B", "text": "The floating static route is installed in the routing table", "is_correct": false}, {"id": "C", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: A Cisco switch with DHCP snooping and DAI enabled. An attacker sends a DHCP REQUEST with a fake chaddr MAC. Result: DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC.', '{}', 'Network Scenarios', 14.0, 'e1bcb71527de372c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('756436ac-f6eb-4c8a-b0f4-8957cb6f6087', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Junos firewall filter with multiple terms and no final default term
Traffic not matching any term in the filter. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": true}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: Junos firewall filter with multiple terms and no final default term. Traffic not matching any term in the filter. Result: The traffic is implicitly denied by the default deny-all term.', '{}', 'Network Scenarios', 14.0, 'cf95f4006bbc5edf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed97e8f8-a85b-41d7-bd7a-9e8bd7e8f580', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS LSP with RSVP-TE signaling and a link failure
The primary path link goes down. What happens?', '[{"id": "A", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": true}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "C", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: An MPLS LSP with RSVP-TE signaling and a link failure. The primary path link goes down. Result: RSVP-TE signals a new path using CSPF or uses a standby secondary path.', '{}', 'Network Scenarios', 14.0, '70bcd4471bafa52e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4896abd0-ef47-4f85-a30f-78480a72ce42', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'Network Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12d39346-9f94-4242-8fbd-49d7bee63053', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'Network Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46e19c94-9639-4888-93df-dd8f94b6778b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "B", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "C", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "D", "text": "The forwarding table is preserved; BGP needs graceful restart to complete", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'Network Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e4e7e02-4e50-4221-b7cb-7050921d0121', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "B", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'Network Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f17e602c-7752-4d2c-a6ca-5b8c30c241bf', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}, {"id": "B", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'Network Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a2a04f72-d50c-489b-a368-da92f7dba78c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
BGP community being used to tag customer routes
Provider sets community 64510:100 on customer routes. What happens?', '[{"id": "A", "text": "Peers can match this community for traffic engineering and policy", "is_correct": true}, {"id": "B", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": false}, {"id": "C", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: BGP community being used to tag customer routes. Provider sets community 64510:100 on customer routes. Result: Peers can match this community for traffic engineering and policy.', '{}', 'Network Scenarios', 14.0, '7dceb717fbccebca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0cc16228-efb6-436d-b911-ab36676ce716', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "The traffic is implicitly denied by the default deny-all term", "is_correct": false}, {"id": "B", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "C", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}, {"id": "D", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'Network Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc5c540e-312a-413a-acba-ea0473d81a1a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An MPLS network with LDP and RSVP-TE both operating
The same FEC has both LDP label and RSVP-TE label assigned. What happens?', '[{"id": "A", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": true}, {"id": "B", "text": "RSVP-TE signals a new path using CSPF or uses a standby secondary path", "is_correct": false}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}]', 'Given: An MPLS network with LDP and RSVP-TE both operating. The same FEC has both LDP label and RSVP-TE label assigned. Result: Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used.', '{}', 'Network Scenarios', 14.0, '787e12051c214ef6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('61344893-1be5-48aa-912f-539906500a28', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "B", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "C", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "D", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'Network Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4096749b-c9ce-423b-8b20-89d14cee9fed', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}, {"id": "B", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'Network Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7d10c110-3f7d-46ce-99c1-144ba2a625d4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A network with IS-IS overload bit set on a router
The overloaded router still participates in IS-IS adjacencies. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": true}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: A network with IS-IS overload bit set on a router. The overloaded router still participates in IS-IS adjacencies. Result: The router is bypassed for transit traffic but remains reachable for locally connected prefixes.', '{}', 'Network Scenarios', 14.0, '1467c27797cc64ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cee67f48-15d6-4c59-bdfb-d59ae1d72488', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "C", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": true}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'Network Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2820b54e-5081-45d2-b2f7-88c87d306401', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}, {"id": "B", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": false}, {"id": "C", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "D", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'Network Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df1dde17-ea0b-488d-9783-cc803c2b596c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', 'An engineer configures a network:
Two routers connected via serial link with OSPF enabled
MTU mismatch between the two sides. What happens?', '[{"id": "A", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": true}, {"id": "C", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "D", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}]', 'Given: Two routers connected via serial link with OSPF enabled. MTU mismatch between the two sides. Result: OSPF neighbors will be stuck in INIT state.', '{}', 'Network Scenarios', 14.0, '9960ccd3a83dd2e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8dd95e8a-2265-450e-9fe4-495f62dd5f47', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP server running out of addresses. What is the most likely cause?', '[{"id": "A", "text": "lease time too long or subnet too small", "is_correct": true}, {"id": "B", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}]', 'lease time too long or subnet too small. Use show ip dhcp pool, show ip dhcp conflict to diagnose.', '{}', 'Troubleshooting', 14.0, '0be06d09ca787cdf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fb10920-3ef2-43c9-925a-e7371280997b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Interface flapping up and down. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "D", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": true}]', 'faulty SFP, cable issue, or speed/duplex mismatch. Use show interfaces, show interfaces diagnostics optics to diagnose.', '{}', 'Troubleshooting', 14.0, 'e7762a500dbd0227_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4a16865d-d32b-457d-b4dd-57cbdcf6cf4c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "D", "text": "query not acknowledged from a neighbor", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('78aedd70-3da8-439c-b9ac-d7e10e216f23', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "D", "text": "kernel route table synchronization issue", "is_correct": true}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e900fb7-0e13-4c8e-90c5-0ff087f055ea', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b7f431b-aaa6-4b8f-b054-3ec3a76d337d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF neighbors stuck in INIT state. What is the most likely cause?', '[{"id": "A", "text": "MTU mismatch or network type mismatch", "is_correct": true}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "C", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "D", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}]', 'MTU mismatch or network type mismatch. Use show ospf neighbor, monitor interface, check MTU to diagnose.', '{}', 'Troubleshooting', 14.0, '728dcf72679e0e0d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('147f95e9-0bbf-40c4-9459-bb2968b750eb', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: OSPF database not synchronizing. What is the most likely cause?', '[{"id": "A", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "B", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": true}]', 'area ID mismatch or passive interface configuration. Use show ospf database, show ospf interface, compare area configs to diagnose.', '{}', 'Troubleshooting', 14.0, '3dd29dcd36872d8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('303d6ab8-58cd-405a-87f8-35ccdd6b3c26', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "B", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "C", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2b3afbce-4836-4bcc-92fa-ed980852a609', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": false}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50311dee-405a-4dae-ad36-e88392ed0c5a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP/HSRP failover not working. What is the most likely cause?', '[{"id": "A", "text": "priority misconfiguration or preempt disabled", "is_correct": true}, {"id": "B", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "C", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "D", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}]', 'priority misconfiguration or preempt disabled. Use show vrrp, show standby brief to diagnose.', '{}', 'Troubleshooting', 14.0, '9d85f7c449fe7501_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7df2e855-fcb9-4dbd-8c12-a29d7ae396c8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Device not reachable via SNMP. What is the most likely cause?', '[{"id": "A", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "D", "text": "community string mismatch or ACL blocking SNMP", "is_correct": true}]', 'community string mismatch or ACL blocking SNMP. Use show snmp, show ip access-lists to diagnose.', '{}', 'Troubleshooting', 14.0, '4629a4f19fc9bcc8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bddc587-0003-4d0c-84b7-c3d2f67c02d6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: ARP cache poisoning detected. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "B", "text": "missing LSP or label binding", "is_correct": false}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": true}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}]', 'attacker sending fake ARP replies. Use show ip arp, show arp, DAI configuration check to diagnose.', '{}', 'Troubleshooting', 14.0, '5789f1b6516b4a9e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('21165316-cc5d-42a5-a3af-b16ac380c48f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping succeeds but traceroute fails. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "C", "text": "ICMP time-exceeded blocked by ACL", "is_correct": true}, {"id": "D", "text": "query not acknowledged from a neighbor", "is_correct": false}]', 'ICMP time-exceeded blocked by ACL. Use show ip access-lists, debug ip icmp to diagnose.', '{}', 'Troubleshooting', 14.0, 'f8540ad7d543f70f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('56edd076-0a28-4cd6-855f-0713d67db3d9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP stuck in active. What is the most likely cause?', '[{"id": "A", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "query not acknowledged from a neighbor", "is_correct": true}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'query not acknowledged from a neighbor. Use show ip eigrp topology, show log, debug eigrp packets to diagnose.', '{}', 'Troubleshooting', 14.0, '0182273873cb1545_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6fcbf1ff-67f6-4f60-b7fb-484706127a74', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "B", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "C", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34560510-b967-446f-bbfd-ebef3ac22e28', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP session flapping. What is the most likely cause?', '[{"id": "A", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": true}, {"id": "B", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "C", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "D", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}]', 'TCP RST from connectivity issues or hold timer mismatch. Use show bgp summary, ping, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '94b0bc0fb051b37b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9676aa6-49a1-4b55-ae3f-e4fcd80c1029', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: LACP bundle not coming up. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": true}]', 'partner configuration mismatch or incompatible speed. Use show etherchannel summary, show lacp neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3698a852089f721_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abf90de3-fed2-42b0-9ab2-3f04ee500160', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: LLDP neighbor not showing. What is the most likely cause?', '[{"id": "A", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "B", "text": "LLDP disabled globally or per interface", "is_correct": true}, {"id": "C", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "D", "text": "MTU mismatch or network type mismatch", "is_correct": false}]', 'LLDP disabled globally or per interface. Use show lldp, show lldp interface ge-0/0/0 to diagnose.', '{}', 'Troubleshooting', 14.0, '41d8508150266f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e271ece4-cd28-4e20-9e51-56b2f8de9e9e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LDP session flapping. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": true}, {"id": "D", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}]', 'hello interval mismatch or transport address unreachable. Use show ldp session, show route, ping transport-address to diagnose.', '{}', 'Troubleshooting', 14.0, '1bb56e98b1420486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('37f9e767-1d3f-47ef-93b0-82c082dbef6b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "too many concurrent translations exceeding pool size", "is_correct": true}, {"id": "B", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "D", "text": "priority misconfiguration or preempt disabled", "is_correct": false}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3e0570a6-0dcb-4967-ae8f-a64ab9eb7ea3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "C", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": true}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d12d6305-497b-4494-9506-cf83abb60908', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2ef3cc38-8a38-4e93-aa14-db43870644da', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Security policy blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "B", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": true}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'missing policy or wrong zone-pair configuration. Use show security policies, show security flow session to diagnose.', '{}', 'Troubleshooting', 14.0, '0ac719102ad083ea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f0aa9f52-15d4-496c-9aa3-77a94c7638d6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP path selection not optimal. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": true}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'local preference or MED configuration. Use show bgp 10.0.0.0, show route protocol bgp to diagnose.', '{}', 'Troubleshooting', 14.0, '8332bfc3943a4701_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d031b148-483a-4b0a-b1f1-db2095092681', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails to remote subnet. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "B", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "C", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "D", "text": "missing default gateway or ACL blocking ICMP", "is_correct": true}]', 'missing default gateway or ACL blocking ICMP. Use show route, show ip access-lists, ping extended to diagnose.', '{}', 'Troubleshooting', 14.0, '914b1eff56c0d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acfabb59-ef97-4e46-a54f-05f8b2acf8bd', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "B", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}, {"id": "C", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "D", "text": "missing LSP or label binding", "is_correct": false}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e2e49821-def4-4ec9-878e-02d49faa5665', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "no ip helper-address or DHCP server unreachable", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "D", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41bce7a0-1a62-48dd-a7a8-4138fb39ae27', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": false}, {"id": "B", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5711e40-ca2b-4935-ad5f-94da4670c9f5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "B", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": true}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0ed44695-db17-471b-8465-60f007300724', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: 802.1X authentication failing. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": true}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'RADIUS server unreachable or EAP type mismatch. Use show authentication sessions, debug radius authentication to diagnose.', '{}', 'Troubleshooting', 14.0, 'bafce4e1105d5d56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0836e485-040f-4223-bdef-a80d23eded17', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6acbab0d-62a3-42f9-8162-30f7d40687c3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: QoS queue drops affecting voice. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": true}, {"id": "C", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": false}]', 'LLQ bandwidth allocation insufficient. Use show policy-map interface, show interface to diagnose.', '{}', 'Troubleshooting', 14.0, '7056c56e4dad253a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6ab9e88d-89a4-427e-9f5a-750c48c38a17', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPsec Phase 2 not completing. What is the most likely cause?', '[{"id": "A", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "B", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": true}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'proxy-ID mismatch or transform set incompatibility. Use show crypto ipsec sa, debug crypto ipsec to diagnose.', '{}', 'Troubleshooting', 14.0, 'cec4e2f8ee9c81ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96d4acd7-0e0e-477f-a2e0-a2e467b0fc29', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Firewall filter blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "B", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "C", "text": "term order incorrect or missing accept term", "is_correct": true}, {"id": "D", "text": "lease time too long or subnet too small", "is_correct": false}]', 'term order incorrect or missing accept term. Use show firewall log, show log messages, monitor traffic to diagnose.', '{}', 'Troubleshooting', 14.0, '4c7b5ac264d85a1c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3a3748c7-ecf4-4a6c-9034-5b9c406ebb0e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "missing underlay route or VNI configuration error", "is_correct": true}, {"id": "D", "text": "lease time too long or subnet too small", "is_correct": false}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ee6b309a-bc45-4dfa-8afa-e79767ddec2a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: Ping fails across MPLS cloud. What is the most likely cause?', '[{"id": "A", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "B", "text": "missing LSP or label binding", "is_correct": true}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "D", "text": "term order incorrect or missing accept term", "is_correct": false}]', 'missing LSP or label binding. Use show route table mpls.0, show ldp session, ping mpls to diagnose.', '{}', 'Troubleshooting', 14.0, '560473323c07f2a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bfefad60-1f63-4ab3-9a2b-d8a12fb29e39', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "B", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('920521c0-982d-4a64-8d20-abb48e859fe1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "B", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "C", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "D", "text": "lease time too long or subnet too small", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af6bc2a2-8387-4b3b-b9c5-103cf80de07e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: QoS marking not applied correctly. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": true}]', 'class-map not matching or policy-map not applied to interface. Use show policy-map interface, show class-map to diagnose.', '{}', 'Troubleshooting', 14.0, 'e0391e393c4fd21a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('29375c10-f630-4847-b132-377f879a6e3b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VRRP election not working. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": true}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "C", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'priority same or preempt disabled on both routers. Use show vrrp, show standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'd1038abcca4baa7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2593b4af-7489-428f-a140-78abb0717ad4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "D", "text": "native VLAN mismatch or trunk pruning", "is_correct": false}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f636c57b-1537-4d27-ac89-76dad96aa7f7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: VXLAN traffic not reaching remote VTEP. What is the most likely cause?', '[{"id": "A", "text": "missing static route or routing policy rejecting the route", "is_correct": false}, {"id": "B", "text": "missing VNI configuration or BGP EVPN session down", "is_correct": true}, {"id": "C", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'missing VNI configuration or BGP EVPN session down. Use show evpn, show ethernet-switching table, show bgp evpn to diagnose.', '{}', 'Troubleshooting', 14.0, 'd513b6be006a5e8d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('522f6bbf-acb3-4f0a-91dc-16cafb04137a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: HSRP state flapping between active/standby. What is the most likely cause?', '[{"id": "A", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": true}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}]', 'Hello timer mismatch or preempt delay misconfiguration. Use show standby brief, debug standby to diagnose.', '{}', 'Troubleshooting', 14.0, 'f0a3c77921aa3570_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c3e4723b-d22d-4b11-9c28-f48e0c6175e5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: High RE CPU on Juniper. What is the most likely cause?', '[{"id": "A", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "B", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": true}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}]', 'routing protocol churn or excessive SNMP polling. Use show system processes, show log messages, show task io to diagnose.', '{}', 'Troubleshooting', 14.0, '29d24f911f5897b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d9bfa546-d7a5-45c6-9869-78a7837f3103', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": false}, {"id": "B", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "D", "text": "peering receiving too many prefixes", "is_correct": true}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f81739c8-2606-4db8-baef-b39c67c38274', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: MLD not discovering IPv6 receivers. What is the most likely cause?', '[{"id": "A", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "B", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "C", "text": "MLD version mismatch or snooping filter", "is_correct": true}, {"id": "D", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}]', 'MLD version mismatch or snooping filter. Use show ipv6 mld groups, show mld snooping to diagnose.', '{}', 'Troubleshooting', 14.0, 'b79c866d2f6de491_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5b57fcd3-3e63-4df6-994c-d7dda378f6b7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: NAT not translating addresses. What is the most likely cause?', '[{"id": "A", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": true}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": false}]', 'missing ip nat inside/outside interface or overload keyword. Use show ip nat translations, debug ip nat to diagnose.', '{}', 'Troubleshooting', 14.0, 'e36837feec2e6362_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a8e91d39-f904-4874-861a-7aa6c52baed0', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}, {"id": "B", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fc1b392e-e926-4679-b909-1186e8b532d8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}, {"id": "B", "text": "priority same or preempt disabled on both routers", "is_correct": false}, {"id": "C", "text": "local preference or MED configuration", "is_correct": false}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c81e2606-161f-4b7e-8fc9-ab729ba16bba', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: No route to destination in routing table. What is the most likely cause?', '[{"id": "A", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "B", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "missing static route or routing policy rejecting the route", "is_correct": true}]', 'missing static route or routing policy rejecting the route. Use show route, show route protocol, traceroute to diagnose.', '{}', 'Troubleshooting', 14.0, '9276615101c1c215_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c00126f-67a6-4b6b-9eae-6110ee25c38b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}, {"id": "B", "text": "RADIUS server unreachable or EAP type mismatch", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ae9e65-2e7b-46a3-bf77-4494064702ef', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "D", "text": "LLDP disabled at interface level or protocol-level", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('855fc801-9bf8-4334-a218-4e3f2a5b5a02', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "B", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "C", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": true}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
