INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2c60e31a-1556-4486-9f0e-ec65588d6b77', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Type 2 Route and Asymmetric IRB?', '[{"id": "A", "text": "Type 2 Route is MAC/IP advertisement route for host reachability; EVI is Ethernet VPN Instance; logical EVPN entity per VNI.", "is_correct": false}, {"id": "B", "text": "Type 2 Route is MAC/IP advertisement route for host reachability; Asymmetric IRB is ingress VTEP routes; egress VTEP bridges to destination.", "is_correct": true}, {"id": "C", "text": "Type 2 Route is MAC/IP advertisement route for host reachability; Type 5 Route is IP Prefix route for inter-subnet forwarding.", "is_correct": false}, {"id": "D", "text": "Type 2 Route is MAC/IP advertisement route for host reachability; Type 1 Route is Ethernet Auto-Discovery route for aliasing and backup.", "is_correct": false}]', 'Type 2 Route MAC/IP advertisement route for host reachability. Asymmetric IRB ingress VTEP routes; egress VTEP bridges to destination.', '{}', 'EVPN Comparison', 14.0, '5f1c722754cae6aa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('037e863d-0188-409f-a434-717a3bbcbc6e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'understand', 'What is the difference between Type 3 Route and Type 1 Route?', '[{"id": "A", "text": "Type 3 Route is Inclusive Multicast Ethernet Tag for BUM traffic; Type 1 Route is Ethernet Auto-Discovery route for aliasing and backup.", "is_correct": true}, {"id": "B", "text": "Type 3 Route is Inclusive Multicast Ethernet Tag for BUM traffic; MAC Mobility is MAC address movement detection and sequence number tracking.", "is_correct": false}, {"id": "C", "text": "Type 3 Route is Inclusive Multicast Ethernet Tag for BUM traffic; DF Election is Designated Forwarder election per VLAN for multi-homed segments.", "is_correct": false}, {"id": "D", "text": "Type 3 Route is Inclusive Multicast Ethernet Tag for BUM traffic; VTEP is VXLAN Tunnel Endpoint encapsulating/decapsulating VXLAN traffic.", "is_correct": false}]', 'Type 3 Route Inclusive Multicast Ethernet Tag for BUM traffic. Type 1 Route Ethernet Auto-Discovery route for aliasing and backup.', '{}', 'EVPN Comparison', 14.0, '17bbbd70bc6c0ef0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
