INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f40f17cb-1f36-44b5-8f6e-52fc83448d5d', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is IKE?', '[{"id": "A", "text": "Internet Key Exchange; establishes IPsec security associations", "is_correct": true}, {"id": "B", "text": "sequence number window protecting against replay attacks", "is_correct": false}, {"id": "C", "text": "Virtual Tunnel Interface for route-based IPsec VPNs", "is_correct": false}, {"id": "D", "text": "keepalive mechanism detecting IPsec peer failure", "is_correct": false}]', 'IKE: Internet Key Exchange; establishes IPsec security associations.', '{}', 'IPsec VPN', 14.0, 'faf7af93fe907792_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a9f00b69-ac8f-4bf7-a55e-02894287717e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is SA?', '[{"id": "A", "text": "Authentication Header; provides integrity without encryption", "is_correct": false}, {"id": "B", "text": "Dynamic VTI for auto-creating IPsec tunnels", "is_correct": false}, {"id": "C", "text": "Security Association; simplex IPsec tunnel configuration", "is_correct": true}, {"id": "D", "text": "Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2", "is_correct": false}]', 'SA: Security Association; simplex IPsec tunnel configuration.', '{}', 'IPsec VPN', 14.0, '4e18ea2f9161d276_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4e283450-b052-48f5-b520-f0fbd54f384a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is SPD?', '[{"id": "A", "text": "Security Policy Database; defines traffic to protect via IPsec", "is_correct": true}, {"id": "B", "text": "Dynamic VTI for auto-creating IPsec tunnels", "is_correct": false}, {"id": "C", "text": "encrypts entire IP packet; new IP header added", "is_correct": false}, {"id": "D", "text": "IPsec tunnel encapsulating GRE tunnel with routing protocols", "is_correct": false}]', 'SPD: Security Policy Database; defines traffic to protect via IPsec.', '{}', 'IPsec VPN', 14.0, 'f18e02af1a668072_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9ddf5c03-2c49-46a4-a7b8-dc2311ecbf4f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is ISAKMP?', '[{"id": "A", "text": "Internet Security Association and Key Management Protocol (UDP 500)", "is_correct": true}, {"id": "B", "text": "Virtual Tunnel Interface for route-based IPsec VPNs", "is_correct": false}, {"id": "C", "text": "Dynamic VTI for auto-creating IPsec tunnels", "is_correct": false}, {"id": "D", "text": "Security Policy Database; defines traffic to protect via IPsec", "is_correct": false}]', 'ISAKMP: Internet Security Association and Key Management Protocol (UDP 500).', '{}', 'IPsec VPN', 14.0, 'd9c6d4e3528a865b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e27db41f-fb81-42b8-8de0-fcdc80d55cbd', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is IPsec Tunnel Mode?', '[{"id": "A", "text": "encrypts entire IP packet; new IP header added", "is_correct": true}, {"id": "B", "text": "Internet Key Exchange; establishes IPsec security associations", "is_correct": false}, {"id": "C", "text": "Internet Security Association and Key Management Protocol (UDP 500)", "is_correct": false}, {"id": "D", "text": "Encapsulating Security Payload; encrypts and authenticates IP packets", "is_correct": false}]', 'IPsec Tunnel Mode: encrypts entire IP packet; new IP header added.', '{}', 'IPsec VPN', 14.0, 'fe9198d4334b656e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cee22da6-f874-4e96-9ca4-4ecb69aaa9d1', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is NAT-T?', '[{"id": "A", "text": "authenticated ISAKMP tunnel for management traffic (main/aggressive mode)", "is_correct": false}, {"id": "B", "text": "IPsec child SA negotiation for encrypted data traffic", "is_correct": false}, {"id": "C", "text": "NAT Traversal; UDP 4500 encapsulation for IPsec through NAT", "is_correct": true}, {"id": "D", "text": "Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2", "is_correct": false}]', 'NAT-T: NAT Traversal; UDP 4500 encapsulation for IPsec through NAT.', '{}', 'IPsec VPN', 14.0, '5e170f73897be7aa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70502761-8fab-464c-8783-815f654e4900', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is IKE Phase 1?', '[{"id": "A", "text": "authenticated ISAKMP tunnel for management traffic (main/aggressive mode)", "is_correct": true}, {"id": "B", "text": "keepalive mechanism detecting IPsec peer failure", "is_correct": false}, {"id": "C", "text": "Dynamic VTI for auto-creating IPsec tunnels", "is_correct": false}, {"id": "D", "text": "Internet Key Exchange; establishes IPsec security associations", "is_correct": false}]', 'IKE Phase 1: authenticated ISAKMP tunnel for management traffic (main/aggressive mode).', '{}', 'IPsec VPN', 14.0, '93d6fbd3d29bebf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('962a6d26-c1c3-4f37-bad1-87d897a60d26', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is D-H Group?', '[{"id": "A", "text": "Internet Key Exchange; establishes IPsec security associations", "is_correct": false}, {"id": "B", "text": "Security Policy Database; defines traffic to protect via IPsec", "is_correct": false}, {"id": "C", "text": "Diffie-Hellman group determining key exchange strength", "is_correct": true}, {"id": "D", "text": "Virtual Tunnel Interface for route-based IPsec VPNs", "is_correct": false}]', 'D-H Group: Diffie-Hellman group determining key exchange strength.', '{}', 'IPsec VPN', 14.0, '9955d0f850018260_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('567f81bf-9ee8-4b1b-bd3f-869b924b020f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Port security violation on switch. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": true}, {"id": "B", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "missing LSP or label binding", "is_correct": false}]', 'excessive MAC addresses or sticky MAC misconfiguration. Use show port-security, show interfaces status err-disabled to diagnose.', '{}', 'Security Troubleshooting', 14.0, '3b6609ef7db000ca_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('954a4134-efa8-4eae-95a0-bc6ab81ba5d4', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: BGP path selection not optimal. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": true}, {"id": "B", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'local preference or MED configuration. Use show bgp 10.0.0.0, show route protocol bgp to diagnose.', '{}', 'Security Troubleshooting', 14.0, '8332bfc3943a4701_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d4e048b-4ac7-44c2-8521-2dcc39011cb8', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: VXLAN tunnel endpoint not reachable. What is the most likely cause?', '[{"id": "A", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "D", "text": "missing underlay route or VNI configuration error", "is_correct": true}]', 'missing underlay route or VNI configuration error. Use show lldp, show interfaces vxlan, traceroute to diagnose.', '{}', 'Security Troubleshooting', 14.0, '1d463441e39b1f6c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1418a9b7-10b0-4675-b1ec-2bcf399a7079', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: BGP next-hop unreachable. What is the most likely cause?', '[{"id": "A", "text": "local preference or MED configuration", "is_correct": false}, {"id": "B", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": true}, {"id": "D", "text": "term order incorrect or missing accept term", "is_correct": false}]', 'no route to BGP next-hop in IGP or next-hop-self missing. Use show bgp neighbor, show ip route, ping next-hop to diagnose.', '{}', 'Security Troubleshooting', 14.0, '9ed22f9b39014312_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('08a90daa-2356-49f9-91ab-407044edb7b8', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Route not in forwarding table. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": true}, {"id": "D", "text": "missing static route or routing policy rejecting the route", "is_correct": false}]', 'kernel route table synchronization issue. Use show route forwarding-table, show route extensive to diagnose.', '{}', 'Security Troubleshooting', 14.0, '44ef8a21d3c615b6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42f5aa57-2b57-4092-9592-45191e933d20', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: BGP prefix limit exceeded. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": true}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}]', 'peering receiving too many prefixes. Use show bgp summary, show log, check max-prefix to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'b03a46a1ba47ba9b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0dc300cc-39d5-43d0-9544-d8a010f78835', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: IPv6 router not advertising prefix. What is the most likely cause?', '[{"id": "A", "text": "IKE policy mismatch or pre-shared key error", "is_correct": false}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "RA suppression or no ipv6 enable on interface", "is_correct": true}]', 'RA suppression or no ipv6 enable on interface. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'd88c2b069357ac5d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dff24396-66f3-48b0-a095-98c9ffd614ab', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: EIGRP route not in topology table. What is the most likely cause?', '[{"id": "A", "text": "priority misconfiguration or preempt disabled", "is_correct": false}, {"id": "B", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "C", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "D", "text": "k-value mismatch or distribute-list filtering", "is_correct": true}]', 'k-value mismatch or distribute-list filtering. Use show ip eigrp topology, show ip protocols to diagnose.', '{}', 'Security Troubleshooting', 14.0, '7e84dd4d7d4d7426_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f03e7ff8-9487-4add-932a-265ac2062461', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: STP loop causing network outage. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}, {"id": "D", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": true}]', 'BPDU filter enabled incorrectly or non-root bridge elected. Use show spanning-tree, show interfaces counters to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'bd8e738bebd81eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('73fee0a9-5ab3-4920-b0b6-aa4a5617cb60', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: QoS marking not applied correctly. What is the most likely cause?', '[{"id": "A", "text": "class-map not matching or policy-map not applied to interface", "is_correct": true}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}, {"id": "D", "text": "ICMP time-exceeded blocked by ACL", "is_correct": false}]', 'class-map not matching or policy-map not applied to interface. Use show policy-map interface, show class-map to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'e0391e393c4fd21a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a344cd-28ad-4668-a05a-1a8d6f0d3350', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: BGP not advertising routes. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": true}, {"id": "B", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "C", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": false}, {"id": "D", "text": "CDP version mismatch or timer mismatch", "is_correct": false}]', 'missing network statement or export policy filtering routes. Use show route advertising-protocol bgp, show policy to diagnose.', '{}', 'Security Troubleshooting', 14.0, '598bcaf9c72f44c8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ad23d22e-08a0-43ed-85b7-1d9e1237c232', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Ping succeeds but traceroute fails. What is the most likely cause?', '[{"id": "A", "text": "ICMP time-exceeded blocked by ACL", "is_correct": true}, {"id": "B", "text": "term order incorrect or missing accept term", "is_correct": false}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "missing static route or routing policy rejecting the route", "is_correct": false}]', 'ICMP time-exceeded blocked by ACL. Use show ip access-lists, debug ip icmp to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'f8540ad7d543f70f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b3d06aa-633a-4fed-ab50-18204ab09e9a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Security policy blocking traffic. What is the most likely cause?', '[{"id": "A", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "B", "text": "missing policy or wrong zone-pair configuration", "is_correct": true}, {"id": "C", "text": "RA suppression or no ipv6 enable on interface", "is_correct": false}, {"id": "D", "text": "MLD version mismatch or snooping filter", "is_correct": false}]', 'missing policy or wrong zone-pair configuration. Use show security policies, show security flow session to diagnose.', '{}', 'Security Troubleshooting', 14.0, '0ac719102ad083ea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bee5c5d7-9c6b-4c1e-8316-9474ac9ab809', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: IPv6 SLAAC not providing addresses. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}, {"id": "D", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": true}]', 'RA suppress enabled or M/O flags incorrectly set. Use show ipv6 interface, debug ipv6 nd to diagnose.', '{}', 'Security Troubleshooting', 14.0, '99f92805eac8301f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('32b484f0-a76e-4580-9204-b1bb920a1379', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: EVPN Type 2 route not advertised. What is the most likely cause?', '[{"id": "A", "text": "BPDU filter enabled incorrectly or non-root bridge elected", "is_correct": false}, {"id": "B", "text": "hello interval mismatch or transport address unreachable", "is_correct": false}, {"id": "C", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": true}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}]', 'MAC not learned or EVI/VNI binding missing. Use show evpn database, show ethernet-switching table to diagnose.', '{}', 'Security Troubleshooting', 14.0, '07ff343c5deadb9a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a1bf2aae-ae0a-4124-ae26-75ab18967a6d', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: MPLS LDP session flapping. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "MTU mismatch or network type mismatch", "is_correct": false}, {"id": "C", "text": "hello interval mismatch or transport address unreachable", "is_correct": true}, {"id": "D", "text": "local preference or MED configuration", "is_correct": false}]', 'hello interval mismatch or transport address unreachable. Use show ldp session, show route, ping transport-address to diagnose.', '{}', 'Security Troubleshooting', 14.0, '1bb56e98b1420486_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7dc0300-9e8e-4d7f-8847-5eadf6669bbf', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: EIGRP stuck in active. What is the most likely cause?', '[{"id": "A", "text": "community string mismatch or ACL blocking SNMP", "is_correct": false}, {"id": "B", "text": "query not acknowledged from a neighbor", "is_correct": true}, {"id": "C", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}, {"id": "D", "text": "LLDP disabled globally or per interface", "is_correct": false}]', 'query not acknowledged from a neighbor. Use show ip eigrp topology, show log, debug eigrp packets to diagnose.', '{}', 'Security Troubleshooting', 14.0, '0182273873cb1545_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8cdb8d0-5157-4361-8986-ebf282795b7b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: PIM neighbors not forming. What is the most likely cause?', '[{"id": "A", "text": "PIM mode mismatch or RP unreachable", "is_correct": true}, {"id": "B", "text": "local preference or MED configuration", "is_correct": false}, {"id": "C", "text": "lease time too long or subnet too small", "is_correct": false}, {"id": "D", "text": "TCP RST from connectivity issues or hold timer mismatch", "is_correct": false}]', 'PIM mode mismatch or RP unreachable. Use show ip pim neighbor, show ip pim rp mapping to diagnose.', '{}', 'Security Troubleshooting', 14.0, '35d44b8da346bfea_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('88e5dcba-13b1-433a-ac3e-ff5f9c23b5dc', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: VRRP/HSRP failover not working. What is the most likely cause?', '[{"id": "A", "text": "LLDP disabled globally or per interface", "is_correct": false}, {"id": "B", "text": "priority misconfiguration or preempt disabled", "is_correct": true}, {"id": "C", "text": "missing LSP or label binding", "is_correct": false}, {"id": "D", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}]', 'priority misconfiguration or preempt disabled. Use show vrrp, show standby brief to diagnose.', '{}', 'Security Troubleshooting', 14.0, '9d85f7c449fe7501_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('16ba4c22-369f-4ec6-bbc4-d7ffcf4640a4', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: NAT pool exhausted. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "B", "text": "too many concurrent translations exceeding pool size", "is_correct": true}, {"id": "C", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "D", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": false}]', 'too many concurrent translations exceeding pool size. Use show ip nat statistics, show ip nat translations verbose to diagnose.', '{}', 'Security Troubleshooting', 14.0, '0385afc23d8c4139_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d70b2dfb-d82c-4363-a88d-3d7b173af6cf', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: DHCP clients not receiving addresses. What is the most likely cause?', '[{"id": "A", "text": "no ip helper-address or DHCP server unreachable", "is_correct": true}, {"id": "B", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}, {"id": "C", "text": "kernel route table synchronization issue", "is_correct": false}, {"id": "D", "text": "missing network statement or export policy filtering routes", "is_correct": false}]', 'no ip helper-address or DHCP server unreachable. Use show ip dhcp binding, debug ip dhcp server events to diagnose.', '{}', 'Security Troubleshooting', 14.0, '378c24bab9e30e99_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dea9eec2-5033-48e0-884c-8158b64ca7b4', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Ping between VLANs fails. What is the most likely cause?', '[{"id": "A", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "B", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": false}, {"id": "C", "text": "SVI interface disabled or VLAN ACL blocking", "is_correct": true}, {"id": "D", "text": "priority same or preempt disabled on both routers", "is_correct": false}]', 'SVI interface disabled or VLAN ACL blocking. Use show ip interface brief, show vlan to diagnose.', '{}', 'Security Troubleshooting', 14.0, '295b7a5f98220ecd_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6f6decc1-929e-483a-9345-f6cba468dc6e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: IPv4 and IPv6 OSPF not adjacent. What is the most likely cause?', '[{"id": "A", "text": "proxy-ID mismatch or transform set incompatibility", "is_correct": false}, {"id": "B", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "C", "text": "missing policy or wrong zone-pair configuration", "is_correct": false}, {"id": "D", "text": "OSPFv2 and OSPFv3 configuration mismatch", "is_correct": true}]', 'OSPFv2 and OSPFv3 configuration mismatch. Use show ospf neighbor, show ospf3 neighbor to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'c217f468a1388cf6_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db35fffb-2431-48ab-bcc6-b45a83aee0da', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: VLAN traffic not reaching across trunk. What is the most likely cause?', '[{"id": "A", "text": "native VLAN mismatch or trunk pruning", "is_correct": true}, {"id": "B", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "C", "text": "missing ip nat inside/outside interface or overload keyword", "is_correct": false}, {"id": "D", "text": "missing LSP or label binding", "is_correct": false}]', 'native VLAN mismatch or trunk pruning. Use show interfaces trunk, show vlan to diagnose.', '{}', 'Security Troubleshooting', 14.0, '9c1a0e57cccd86e1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a602e111-e009-4876-a88b-32c77ddf9b79', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Multicast receiver not receiving traffic. What is the most likely cause?', '[{"id": "A", "text": "excessive MAC addresses or sticky MAC misconfiguration", "is_correct": false}, {"id": "B", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "C", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": false}, {"id": "D", "text": "PIM RP unreachable or IGMP snooping filter", "is_correct": true}]', 'PIM RP unreachable or IGMP snooping filter. Use show pim rp, show igmp snooping, show mroute to diagnose.', '{}', 'Security Troubleshooting', 14.0, '7d913157817be419_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1171a847-c2ab-410e-8e18-39fc685a3417', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: MPLS LSP not signaling. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": true}, {"id": "C", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "D", "text": "class-map not matching or policy-map not applied to interface", "is_correct": false}]', 'RSVP-TE path computation or CSPF failure. Use show mpls lsp, show rsvp session, log messages to diagnose.', '{}', 'Security Troubleshooting', 14.0, '38551bf4caecc89f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('13e65dc3-3817-488f-a34b-2d4cbbcc3047', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: DHCP starvation attack occurring. What is the most likely cause?', '[{"id": "A", "text": "malicious client exhausting pool with fake MACs", "is_correct": true}, {"id": "B", "text": "CDP version mismatch or timer mismatch", "is_correct": false}, {"id": "C", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "D", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}]', 'malicious client exhausting pool with fake MACs. Use show ip dhcp binding, show ip dhcp conflict, IP source guard to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'f51394a5b8a39187_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5366099d-5e09-4903-889a-b20e487ee272', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: VRRP election not working. What is the most likely cause?', '[{"id": "A", "text": "priority same or preempt disabled on both routers", "is_correct": true}, {"id": "B", "text": "MAC not learned or EVI/VNI binding missing", "is_correct": false}, {"id": "C", "text": "missing default gateway or ACL blocking ICMP", "is_correct": false}, {"id": "D", "text": "area ID mismatch or passive interface configuration", "is_correct": false}]', 'priority same or preempt disabled on both routers. Use show vrrp, show standby to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'd1038abcca4baa7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f58ab8cc-605d-4f76-85c6-303f5232e57a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: IPsec tunnel not establishing. What is the most likely cause?', '[{"id": "A", "text": "control link failure or threshold timeout too high", "is_correct": false}, {"id": "B", "text": "IKE policy mismatch or pre-shared key error", "is_correct": true}, {"id": "C", "text": "area ID mismatch or passive interface configuration", "is_correct": false}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}]', 'IKE policy mismatch or pre-shared key error. Use show crypto isakmp sa, show crypto ipsec sa to diagnose.', '{}', 'Security Troubleshooting', 14.0, '3a9d9609204bdf7a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('094af778-05da-46d0-9fef-fa9ae9f83b9b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Chassis cluster failover not happening. What is the most likely cause?', '[{"id": "A", "text": "k-value mismatch or distribute-list filtering", "is_correct": false}, {"id": "B", "text": "PIM mode mismatch or RP unreachable", "is_correct": false}, {"id": "C", "text": "missing LSP or label binding", "is_correct": false}, {"id": "D", "text": "control link failure or threshold timeout too high", "is_correct": true}]', 'control link failure or threshold timeout too high. Use show chassis cluster status, show log messages to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'a3b191ebfd46ca07_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('384a3982-f995-496a-9721-ea98cceb9f82', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: LACP bundle not coming up. What is the most likely cause?', '[{"id": "A", "text": "peering receiving too many prefixes", "is_correct": false}, {"id": "B", "text": "missing underlay route or VNI configuration error", "is_correct": false}, {"id": "C", "text": "partner configuration mismatch or incompatible speed", "is_correct": true}, {"id": "D", "text": "no route to BGP next-hop in IGP or next-hop-self missing", "is_correct": false}]', 'partner configuration mismatch or incompatible speed. Use show etherchannel summary, show lacp neighbor to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'f3698a852089f721_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('dced2b82-ff32-4791-a3c4-b54f04260792', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Interface flapping up and down. What is the most likely cause?', '[{"id": "A", "text": "attacker sending fake ARP replies", "is_correct": false}, {"id": "B", "text": "RSVP-TE path computation or CSPF failure", "is_correct": false}, {"id": "C", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "D", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": true}]', 'faulty SFP, cable issue, or speed/duplex mismatch. Use show interfaces, show interfaces diagnostics optics to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'e7762a500dbd0227_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('51138091-3ef2-4087-b770-bbdf0635aa32', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: CDP neighbor inconsistent. What is the most likely cause?', '[{"id": "A", "text": "faulty SFP, cable issue, or speed/duplex mismatch", "is_correct": false}, {"id": "B", "text": "RA suppress enabled or M/O flags incorrectly set", "is_correct": false}, {"id": "C", "text": "CDP version mismatch or timer mismatch", "is_correct": true}, {"id": "D", "text": "partner configuration mismatch or incompatible speed", "is_correct": false}]', 'CDP version mismatch or timer mismatch. Use show cdp neighbors detail, show cdp interface to diagnose.', '{}', 'Security Troubleshooting', 14.0, '6a97dc7313f66366_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6d33115-f029-4caf-8098-c6f468fe481e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: High CPU utilization on router. What is the most likely cause?', '[{"id": "A", "text": "too many concurrent translations exceeding pool size", "is_correct": false}, {"id": "B", "text": "routing protocol process CPU spikes or BGP flapping", "is_correct": true}, {"id": "C", "text": "routing protocol churn or excessive SNMP polling", "is_correct": false}, {"id": "D", "text": "Hello timer mismatch or preempt delay misconfiguration", "is_correct": false}]', 'routing protocol process CPU spikes or BGP flapping. Use show processes cpu, show log, show ip bgp summary to diagnose.', '{}', 'Security Troubleshooting', 14.0, '05d7fea3b7adcf43_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('40820911-ef0d-4953-a30f-e57101905162', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer sees: Ping works but TCP connections fail. What is the most likely cause?', '[{"id": "A", "text": "missing network statement or export policy filtering routes", "is_correct": false}, {"id": "B", "text": "LLQ bandwidth allocation insufficient", "is_correct": false}, {"id": "C", "text": "ACL blocking return traffic or TCP MSS issue", "is_correct": true}, {"id": "D", "text": "malicious client exhausting pool with fake MACs", "is_correct": false}]', 'ACL blocking return traffic or TCP MSS issue. Use show ip access-lists, extended ping with TCP to diagnose.', '{}', 'Security Troubleshooting', 14.0, 'f3f82c2697e8e583_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('22da6e62-bbc6-4f45-8040-97ea879771f8', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between UTM and AppSecure?', '[{"id": "A", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; UserFirewall is identity-based policies using Active Directory integration.", "is_correct": false}, {"id": "B", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "C", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; Fabric Link is fab1 interface for session state replication.", "is_correct": false}, {"id": "D", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; AppSecure is application identification and application-based policies.", "is_correct": true}]', 'UTM unified threat management with antivirus, filtering, and anti-spam. AppSecure application identification and application-based policies.', '{}', 'Security Comparison', 14.0, '31d7ef38d7c63eb0_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4c1bceab-2120-40c4-b30a-2d25ac336d9e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Screen and Active/Active?', '[{"id": "A", "text": "Screen is zone-based attack detection and prevention; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": false}, {"id": "B", "text": "Screen is zone-based attack detection and prevention; Packet Mode is fast forwarding without stateful inspection.", "is_correct": false}, {"id": "C", "text": "Screen is zone-based attack detection and prevention; Active/Active is both nodes forwarding traffic with load balancing.", "is_correct": true}, {"id": "D", "text": "Screen is zone-based attack detection and prevention; Active/Active is both nodes forwarding traffic with load balancing.", "is_correct": true}]', 'Screen zone-based attack detection and prevention. Active/Active both nodes forwarding traffic with load balancing.', '{}', 'Security Comparison', 14.0, '9f896c3d5b6d40a7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41f54004-7a5b-456c-acc7-df3f453775fa', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between UTM and SecIntel?', '[{"id": "A", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "B", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}, {"id": "C", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": true}, {"id": "D", "text": "UTM is unified threat management with antivirus, filtering, and anti-spam; Security Policy is rules defining permitted/denied traffic between zones.", "is_correct": false}]', 'UTM unified threat management with antivirus, filtering, and anti-spam. SecIntel cloud threat intelligence blocking malicious IPs/URLs.', '{}', 'Security Comparison', 14.0, '019f96e9aad6817c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
