INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2f4491e6-c318-4321-a0be-d999eaac8c91', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between IKE Phase 2 and AppSecure?', '[{"id": "A", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": false}, {"id": "B", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "C", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": false}, {"id": "D", "text": "IKE Phase 2 is IPsec child SA for encrypted data traffic; AppSecure is application identification and application-based policies.", "is_correct": true}]', 'IKE Phase 2 IPsec child SA for encrypted data traffic. AppSecure application identification and application-based policies.', '{}', 'Security Comparison', 14.0, 'a4cbaaac692893b7_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12d8a0c7-8b6c-4649-b1b7-46ad622fd4e1', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between NAT Destination and IKE Phase 1?', '[{"id": "A", "text": "NAT Destination is translating public destination IPs to private IPs; UTM is unified threat management with antivirus, filtering, and anti-spam.", "is_correct": false}, {"id": "B", "text": "NAT Destination is translating public destination IPs to private IPs; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "C", "text": "NAT Destination is translating public destination IPs to private IPs; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": true}, {"id": "D", "text": "NAT Destination is translating public destination IPs to private IPs; IKE Phase 2 is IPsec child SA for encrypted data traffic.", "is_correct": false}]', 'NAT Destination translating public destination IPs to private IPs. IKE Phase 1 authenticated ISAKMP tunnel for management traffic.', '{}', 'Security Comparison', 14.0, '66f39fff5d412437_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2257cd56-0a3c-4b1b-ba23-1f6e94262a19', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Chassis Cluster and Fabric Link?', '[{"id": "A", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "B", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Fabric Link is fab1 interface for session state replication.", "is_correct": true}, {"id": "C", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; Control Link is fab0 interface for chassis cluster control plane IPC.", "is_correct": false}, {"id": "D", "text": "Chassis Cluster is two SRX devices as HA pair with stateful failover; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}]', 'Chassis Cluster two SRX devices as HA pair with stateful failover. Fabric Link fab1 interface for session state replication.', '{}', 'Security Comparison', 14.0, '19836c329d6c79f3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70c2bffd-ce79-459d-bfdd-29044e011abe', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between UserFirewall and Security Zone?', '[{"id": "A", "text": "UserFirewall is identity-based policies using Active Directory integration; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": false}, {"id": "B", "text": "UserFirewall is identity-based policies using Active Directory integration; Security Zone is logical interface group with common security policies.", "is_correct": true}, {"id": "C", "text": "UserFirewall is identity-based policies using Active Directory integration; NAT Source is translating private source IPs to public IPs.", "is_correct": false}, {"id": "D", "text": "UserFirewall is identity-based policies using Active Directory integration; Active/Passive is one node active forwarding traffic; standby takes over on failure.", "is_correct": false}]', 'UserFirewall identity-based policies using Active Directory integration. Security Zone logical interface group with common security policies.', '{}', 'Security Comparison', 14.0, '9c3beb4134c3d981_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('94ccc03f-0082-49a1-9070-474faf70a61a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between AppSecure and Route-based VPN?', '[{"id": "A", "text": "AppSecure is application identification and application-based policies; Screen is zone-based attack detection and prevention.", "is_correct": false}, {"id": "B", "text": "AppSecure is application identification and application-based policies; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": true}, {"id": "C", "text": "AppSecure is application identification and application-based policies; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": true}, {"id": "D", "text": "AppSecure is application identification and application-based policies; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}]', 'AppSecure application identification and application-based policies. Route-based VPN IPsec tunnel bound to a st0 interface for routing.', '{}', 'Security Comparison', 14.0, '7f76dbdb7e26346e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f38fa034-47f9-4cd3-ade1-daacb8354ca3', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between NAT Destination and Policy-based VPN?', '[{"id": "A", "text": "NAT Destination is translating public destination IPs to private IPs; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "B", "text": "NAT Destination is translating public destination IPs to private IPs; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": true}, {"id": "C", "text": "NAT Destination is translating public destination IPs to private IPs; ALG is Application Layer Gateway; deep inspection for embedded IPs/ports.", "is_correct": false}, {"id": "D", "text": "NAT Destination is translating public destination IPs to private IPs; Inter-zone Traffic is traffic between different zones; denied by default.", "is_correct": false}]', 'NAT Destination translating public destination IPs to private IPs. Policy-based VPN IPsec triggered by security policy match.', '{}', 'Security Comparison', 14.0, '233c230128206e8e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eda03ab2-0b76-4d73-9ce4-352278ae7d55', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between UserFirewall and Control Link?', '[{"id": "A", "text": "UserFirewall is identity-based policies using Active Directory integration; Fabric Link is fab1 interface for session state replication.", "is_correct": false}, {"id": "B", "text": "UserFirewall is identity-based policies using Active Directory integration; Control Link is fab0 interface for chassis cluster control plane IPC.", "is_correct": true}, {"id": "C", "text": "UserFirewall is identity-based policies using Active Directory integration; Control Link is fab0 interface for chassis cluster control plane IPC.", "is_correct": true}, {"id": "D", "text": "UserFirewall is identity-based policies using Active Directory integration; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}]', 'UserFirewall identity-based policies using Active Directory integration. Control Link fab0 interface for chassis cluster control plane IPC.', '{}', 'Security Comparison', 14.0, '6c3630e696200193_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c59928f4-6373-4c0c-a398-29258ac912be', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Control Link and Security Zone?', '[{"id": "A", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; Security Zone is logical interface group with common security policies.", "is_correct": true}, {"id": "B", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; PAT is Port Address Translation; many-to-one with port multiplexing.", "is_correct": false}, {"id": "C", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; ALG is Application Layer Gateway; deep inspection for embedded IPs/ports.", "is_correct": false}, {"id": "D", "text": "Control Link is fab0 interface for chassis cluster control plane IPC; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}]', 'Control Link fab0 interface for chassis cluster control plane IPC. Security Zone logical interface group with common security policies.', '{}', 'Security Comparison', 14.0, '9daeb14c58b0011c_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1afad3c4-013f-4935-8a68-caa118196944', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between AppSecure and Security Policy?', '[{"id": "A", "text": "AppSecure is application identification and application-based policies; Security Policy is rules defining permitted/denied traffic between zones.", "is_correct": true}, {"id": "B", "text": "AppSecure is application identification and application-based policies; Security Policy is rules defining permitted/denied traffic between zones.", "is_correct": true}, {"id": "C", "text": "AppSecure is application identification and application-based policies; Active/Passive is one node active forwarding traffic; standby takes over on failure.", "is_correct": false}, {"id": "D", "text": "AppSecure is application identification and application-based policies; Inter-zone Traffic is traffic between different zones; denied by default.", "is_correct": false}]', 'AppSecure application identification and application-based policies. Security Policy rules defining permitted/denied traffic between zones.', '{}', 'Security Comparison', 14.0, '9c0106a54a86206d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f8c32e5b-4bed-4046-9593-0131288eabc8', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Packet Mode and Security Policy?', '[{"id": "A", "text": "Packet Mode is fast forwarding without stateful inspection; UTM is unified threat management with antivirus, filtering, and anti-spam.", "is_correct": false}, {"id": "B", "text": "Packet Mode is fast forwarding without stateful inspection; Security Policy is rules defining permitted/denied traffic between zones.", "is_correct": true}, {"id": "C", "text": "Packet Mode is fast forwarding without stateful inspection; IKE Phase 2 is IPsec child SA for encrypted data traffic.", "is_correct": false}, {"id": "D", "text": "Packet Mode is fast forwarding without stateful inspection; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": false}]', 'Packet Mode fast forwarding without stateful inspection. Security Policy rules defining permitted/denied traffic between zones.', '{}', 'Security Comparison', 14.0, 'd15b69b279c963d5_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1675b5a2-918a-4094-b270-5b1820c36e71', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with VCP ports on different member links
Split between members 0-2 and 3-5 with VCP redundancy configured. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}, {"id": "B", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "C", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": true}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: A Juniper virtual chassis with VCP ports on different member links. Split between members 0-2 and 3-5 with VCP redundancy configured. Result: Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism.', '{}', 'Security Scenarios', 14.0, '447a8cf9acacdeff_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c4323f24-45ff-4f8e-be44-667a31789f22', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX chassis cluster with control link failure
The control link (fab0) goes down but fabric link (fab1) remains up. What happens?', '[{"id": "A", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "B", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": false}, {"id": "C", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": true}, {"id": "D", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": false}]', 'Given: An SRX chassis cluster with control link failure. The control link (fab0) goes down but fabric link (fab1) remains up. Result: The cluster splits unless the control link recovers within the timeout.', '{}', 'Security Scenarios', 14.0, 'a9e409dea06ed9af_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('79796f35-81e4-4eab-a1f9-cdd2ea3b123a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with PIM-DM and a single multicast receiver
The multicast source starts sending. What happens?', '[{"id": "A", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": true}, {"id": "B", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "C", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "D", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}]', 'Given: A network with PIM-DM and a single multicast receiver. The multicast source starts sending. Result: The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune.', '{}', 'Security Scenarios', 14.0, '64a3534b1339c67d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('debaf7fc-d688-4cff-b345-c385bc0e4dc6', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX security policy configured without application services
Traffic matching an ALG-dependent protocol (FTP). What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "B", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "C", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "D", "text": "The FTP data channel fails since no ALG is configured", "is_correct": true}]', 'Given: An SRX security policy configured without application services. Traffic matching an ALG-dependent protocol (FTP). Result: The FTP data channel fails since no ALG is configured.', '{}', 'Security Scenarios', 14.0, '0434e36657625f56_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('66543a26-b631-422d-b2fb-7385c9c900e0', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A trunk link between two switches with mismatched native VLANs
Native VLAN 10 on one side and 20 on the other. What happens?', '[{"id": "A", "text": "VLAN traffic may leak between VLANs unexpectedly", "is_correct": true}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}, {"id": "C", "text": "Traffic follows the RSVP-TE LSP when LDP-over-RSVP is configured; otherwise LDP forwarding is used", "is_correct": false}, {"id": "D", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}]', 'Given: A trunk link between two switches with mismatched native VLANs. Native VLAN 10 on one side and 20 on the other. Result: VLAN traffic may leak between VLANs unexpectedly.', '{}', 'Security Scenarios', 14.0, '2549e57ecd6b6fdb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('805ff74a-2869-45de-b026-4016f005b05b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router receiving the same route from OSPF (AD 110) and BGP (AD 20)
The route is to 10.0.0.0/24 with same metric. What happens?', '[{"id": "A", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "B", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "C", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "D", "text": "BGP route is preferred due to lower administrative distance", "is_correct": true}]', 'Given: A router receiving the same route from OSPF (AD 110) and BGP (AD 20). The route is to 10.0.0.0/24 with same metric. Result: BGP route is preferred due to lower administrative distance.', '{}', 'Security Scenarios', 14.0, 'cd7b8e76d54b4736_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ae823123-aee3-4eae-afc4-3f2be8935f0d', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A campus switch stack with four members configured for cross-stack EtherChannel
One member switch fails unexpectedly. What happens?', '[{"id": "A", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "B", "text": "The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links", "is_correct": true}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}, {"id": "D", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}]', 'Given: A campus switch stack with four members configured for cross-stack EtherChannel. One member switch fails unexpectedly. Result: The EtherChannel link remains active using remaining member ports; traffic redistributes across surviving links.', '{}', 'Security Scenarios', 14.0, 'b863698de6c682a2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5bc7ddf0-bddc-4b00-a307-b495c3efea6e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two routers running BFD over a multiplexed Ethernet link
Link congestion causes BFD packet loss for more than 3 intervals. What happens?', '[{"id": "A", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "B", "text": "The switch floods the packet as unknown unicast within the VNI", "is_correct": false}, {"id": "C", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": false}, {"id": "D", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": true}]', 'Given: Two routers running BFD over a multiplexed Ethernet link. Link congestion causes BFD packet loss for more than 3 intervals. Result: BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path.', '{}', 'Security Scenarios', 14.0, 'a18ce7843217598d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('46b07a68-3c39-4229-a786-dbfc84da3216', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with LACP fast rate and member link failure
One link in a port-channel fails briefly then recovers. What happens?', '[{"id": "A", "text": "The cluster splits unless the control link recovers within the timeout", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": true}]', 'Given: A network with LACP fast rate and member link failure. One link in a port-channel fails briefly then recovers. Result: LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手.', '{}', 'Security Scenarios', 14.0, '49ad0eb782fe72db_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ba978471-39e7-48f3-b538-52a56bb5b03e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An OSPF NSSA area with multiple ASBRs redistributing external routes
Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. What happens?', '[{"id": "A", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "B", "text": "Split detection via multi-member VCP; lower priority split goes into line-card mode or uses split-detection mechanism", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": true}, {"id": "D", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": false}]', 'Given: An OSPF NSSA area with multiple ASBRs redistributing external routes. Two ASBR advertise Type 7 LSAs for the same prefix with different metrics. Result: The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR.', '{}', 'Security Scenarios', 14.0, '761aa5b89161d633_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8c6cf63-4906-4f26-a1d2-45f31123efc7', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with Policy-Based Routing matching HTTP traffic
HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "The session establishes with the lower hold timer value", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": true}]', 'Given: A network with Policy-Based Routing matching HTTP traffic. HTTPS traffic needs to use the same path as HTTP but is not matched by the route-map. Result: Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table.', '{}', 'Security Scenarios', 14.0, '85f40f79aa40f08a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e21ebbff-2afc-4ded-9d02-5954fbc355b0', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1)
Adjacency attempt between the two routers. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": true}, {"id": "B", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "C", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "D", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}]', 'Given: Two EIGRP routers with different K-values (K1=1 vs K1=1 K3=1). Adjacency attempt between the two routers. Result: EIGRP adjacency fails with K-value mismatch error message in logs.', '{}', 'Security Scenarios', 14.0, 'd3132606c64f6eaa_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('897e07f8-f512-4790-871a-043aad419960', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper virtual chassis with two members split by a link failure
Split occurs between member 0 and member 1. What happens?', '[{"id": "A", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "B", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": true}, {"id": "C", "text": "Routes are kept separate using VRFs and route distinguishers", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": false}]', 'Given: A Juniper virtual chassis with two members split by a link failure. Split occurs between member 0 and member 1. Result: Both members become active and split-brain occurs without VCP redundancy.', '{}', 'Security Scenarios', 14.0, 'f074e45b788db78b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7f6e4609-15de-48b8-a468-4ef7a4b7b717', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
IPv6 router configured with SLAAC and no DHCPv6
A new Windows host connects to the network. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": true}, {"id": "B", "text": "LACP detects failure within 1 second (fast rate); the link is removed from bundle; upon recovery it rejoins after握手", "is_correct": false}, {"id": "C", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: IPv6 router configured with SLAAC and no DHCPv6. A new Windows host connects to the network. Result: The host receives an IPv6 address using the advertised prefix with EUI-64.', '{}', 'Security Scenarios', 14.0, '5ccf0abff48806d1_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97986454-5c4a-44a1-95cc-c497fd364b13', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco router with IP SLA tracking an ICMP echo to a remote target
The tracked target becomes unreachable for three consecutive probe intervals. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": true}, {"id": "B", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "C", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "D", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}]', 'Given: A Cisco router with IP SLA tracking an ICMP echo to a remote target. The tracked target becomes unreachable for three consecutive probe intervals. Result: SLA enters down state; associated object tracking triggers route removal or policy change.', '{}', 'Security Scenarios', 14.0, '2ec83fb7938617da_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b098347-4894-4e48-aad0-23f832dadd7f', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch configured with VTP transparent mode
A new VLAN is created and needs to propagate. What happens?', '[{"id": "A", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}, {"id": "B", "text": "With deterministic-med, MED comparison is done per-neighbor AS; missing MED treated as 0", "is_correct": false}, {"id": "C", "text": "VLAN changes must be configured manually on each switch", "is_correct": true}, {"id": "D", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}]', 'Given: A Cisco switch configured with VTP transparent mode. A new VLAN is created and needs to propagate. Result: VLAN changes must be configured manually on each switch.', '{}', 'Security Scenarios', 14.0, '72a9150feb928270_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('428217ed-816e-4d42-9402-0624819183be', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Cisco switch with Voice VLAN configured on an access port
A Cisco IP phone is connected with a PC behind the phone. What happens?', '[{"id": "A", "text": "The port enters err-disable state and blocks traffic", "is_correct": false}, {"id": "B", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": true}, {"id": "C", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "D", "text": "Virtual link works but both areas must connect through the same ABR for stability", "is_correct": false}]', 'Given: A Cisco switch with Voice VLAN configured on an access port. A Cisco IP phone is connected with a PC behind the phone. Result: Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking.', '{}', 'Security Scenarios', 14.0, 'b45bf10e180b0119_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('98b0241d-f180-4f12-920e-d0c142d417b6', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An EtherChannel configured with LACP active on one side and passive on the other
LACP passive side waits for negotiation. What happens?', '[{"id": "A", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": true}, {"id": "B", "text": "EVPN Type 2 route with sequence number is updated; MAC mobility sequence increments and traffic follows", "is_correct": false}, {"id": "C", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "D", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}]', 'Given: An EtherChannel configured with LACP active on one side and passive on the other. LACP passive side waits for negotiation. Result: The bundle forms successfully (active/passive is compatible).', '{}', 'Security Scenarios', 14.0, '49db397654d174cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7fda0a4d-7c8c-4291-b510-d35df91b260c', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router with BGP multipath and two equal-cost eBGP paths
Two paths to the same prefix from different AS. What happens?', '[{"id": "A", "text": "VLAN changes must be configured manually on each switch", "is_correct": false}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": true}, {"id": "D", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}]', 'Given: A router with BGP multipath and two equal-cost eBGP paths. Two paths to the same prefix from different AS. Result: Both paths are installed in routing table with ECMP if load-balancing is enabled.', '{}', 'Security Scenarios', 14.0, 'c2dfd31bd6ecf86e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a0b9b607-5948-4b43-abb8-d8f7e9b5625e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with IS-IS overload bit set on a router
The overloaded router still participates in IS-IS adjacencies. What happens?', '[{"id": "A", "text": "The router is bypassed for transit traffic but remains reachable for locally connected prefixes", "is_correct": true}, {"id": "B", "text": "Policy-based routing must explicitly match protocol TCP port 443; otherwise HTTPS uses default routing table", "is_correct": false}, {"id": "C", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "D", "text": "Both members become active and split-brain occurs without VCP redundancy", "is_correct": false}]', 'Given: A network with IS-IS overload bit set on a router. The overloaded router still participates in IS-IS adjacencies. Result: The router is bypassed for transit traffic but remains reachable for locally connected prefixes.', '{}', 'Security Scenarios', 14.0, '1467c27797cc64ae_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f95f6ffe-d171-4234-8451-28451eebc63b', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router with IP SLA tracking configured for static route failover
Tracked destination becomes unreachable. What happens?', '[{"id": "A", "text": "The message is dropped by DHCP snooping as untrusted ports cannot send OFFERs", "is_correct": false}, {"id": "B", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": false}, {"id": "C", "text": "Both paths are installed in routing table with ECMP if load-balancing is enabled", "is_correct": false}, {"id": "D", "text": "The floating static route is installed in the routing table", "is_correct": true}]', 'Given: A router with IP SLA tracking configured for static route failover. Tracked destination becomes unreachable. Result: The floating static route is installed in the routing table.', '{}', 'Security Scenarios', 14.0, '9d54c04dd639ad0e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc64ff8e-7cef-4b75-85f1-4492ea8a54f0', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
An SRX cluster in active/active mode with asymmetric routing
Reverse traffic arrives on different node than forward traffic. What happens?', '[{"id": "A", "text": "SLA enters down state; associated object tracking triggers route removal or policy change", "is_correct": false}, {"id": "B", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "C", "text": "The SRX performs flow re-assembly and session synchronization via fabric link", "is_correct": true}, {"id": "D", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}]', 'Given: An SRX cluster in active/active mode with asymmetric routing. Reverse traffic arrives on different node than forward traffic. Result: The SRX performs flow re-assembly and session synchronization via fabric link.', '{}', 'Security Scenarios', 14.0, '99253593adcbbf6f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('50c511a2-9b39-4e23-8265-2567e95db500', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A BGP session between two ISPs with different hold timers
Hold timer mismatch of 30 and 90 seconds. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "B", "text": "The bundle forms successfully (active/passive is compatible)", "is_correct": false}, {"id": "C", "text": "Traffic is rebalanced across remaining member links with minimal packet loss", "is_correct": false}, {"id": "D", "text": "The session establishes with the lower hold timer value", "is_correct": true}]', 'Given: A BGP session between two ISPs with different hold timers. Hold timer mismatch of 30 and 90 seconds. Result: The session establishes with the lower hold timer value.', '{}', 'Security Scenarios', 14.0, '5978fb6c10acbd6d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b8a51860-a814-4b1e-95f4-e5e458c2fcb2', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A network with BGP ORF (Outbound Route Filtering) configured
The BGP peer sends a prefix that should be filtered by ORF. What happens?', '[{"id": "A", "text": "New translation requests are dropped until existing sessions expire or are cleared", "is_correct": false}, {"id": "B", "text": "Both routers establish a Level 1 adjacency in area 49.0001", "is_correct": false}, {"id": "C", "text": "The port is moved to root-inconsistent state blocking traffic", "is_correct": false}, {"id": "D", "text": "ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised", "is_correct": true}]', 'Given: A network with BGP ORF (Outbound Route Filtering) configured. The BGP peer sends a prefix that should be filtered by ORF. Result: ORF is negotiated; received prefix is processed against the installed outbound filter; matching prefix is not advertised.', '{}', 'Security Scenarios', 14.0, '35c1a3d7d6ebe2d8_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2d32571-c291-4d28-a502-6d491cc400c4', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
PIM-SM with BSR mechanism for RP discovery
A new multicast source becomes active. What happens?', '[{"id": "A", "text": "The host receives an IPv6 address using the advertised prefix with EUI-64", "is_correct": false}, {"id": "B", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}, {"id": "C", "text": "The source registers with the RP; receivers join via (*,G) tree toward the RP", "is_correct": true}, {"id": "D", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}]', 'Given: PIM-SM with BSR mechanism for RP discovery. A new multicast source becomes active. Result: The source registers with the RP; receivers join via (*,G) tree toward the RP.', '{}', 'Security Scenarios', 14.0, '52a6f4de5a39f423_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7ec5eba0-d0d9-4c60-964a-cac6cf1a0e7e', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper MX with firewall filter on loopback interface
Filter term accepts SSH but rejects telnet; no final term present. What happens?', '[{"id": "A", "text": "SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected", "is_correct": true}, {"id": "B", "text": "BFD declares the session down; routing protocols react by tearing adjacencies; traffic re-routes via alternate path", "is_correct": false}, {"id": "C", "text": "Phone uses voice VLAN with CoS trust; PC uses data VLAN; both are forwarded with proper QoS marking", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: A Juniper MX with firewall filter on loopback interface. Filter term accepts SSH but rejects telnet; no final term present. Result: SSH is accepted; telnet is rejected by the implicit default discard; all other traffic to loopback is also rejected.', '{}', 'Security Scenarios', 14.0, '7f7a72bf4ab536eb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('779e895a-0677-4e76-b4e5-cf7041d720f0', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A Juniper router with multiple routing instances (VRFs)
Route leaking between VRF-A and VRF-B is required. What happens?', '[{"id": "A", "text": "BGP route is preferred due to lower administrative distance", "is_correct": false}, {"id": "B", "text": "Use rib-groups or instance-import/export policies to selectively share routes between VRFs", "is_correct": true}, {"id": "C", "text": "DHCP snooping drops the packet because the chaddr doesn''t match the ingress port''s MAC", "is_correct": false}, {"id": "D", "text": "Type 2 route with MAC/IP is advertised to remote VTEPs via BGP", "is_correct": false}]', 'Given: A Juniper router with multiple routing instances (VRFs). Route leaking between VRF-A and VRF-B is required. Result: Use rib-groups or instance-import/export policies to selectively share routes between VRFs.', '{}', 'Security Scenarios', 14.0, '905cefdb453eaecf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eadd0c6b-282e-4c49-b42f-69379ed557ed', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
IPv6 OSPFv3 running with link-local addresses only
OSPFv3 adjacency using link-local addresses. What happens?', '[{"id": "A", "text": "Both ingress and egress VTEPs perform routing with VNI translation", "is_correct": false}, {"id": "B", "text": "Adjacency forms using link-local FE80 addresses; global addrs in LSAs only", "is_correct": true}, {"id": "C", "text": "OSPF neighbors will be stuck in INIT state", "is_correct": false}, {"id": "D", "text": "The best route is selected based on lowest metric; Type 7 LSAs are translated to Type 5 by the NSSA ABR", "is_correct": false}]', 'Given: IPv6 OSPFv3 running with link-local addresses only. OSPFv3 adjacency using link-local addresses. Result: Adjacency forms using link-local FE80 addresses; global addrs in LSAs only.', '{}', 'Security Scenarios', 14.0, '35b3d258e1f65844_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1937dfa6-3526-4985-b04b-cf15f6d03b82', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'analyze', 'An engineer configures a network:
A router configured with BGP add-path and three paths to the same prefix
The router needs to advertise multiple paths to its iBGP peer. What happens?', '[{"id": "A", "text": "EIGRP adjacency fails with K-value mismatch error message in logs", "is_correct": false}, {"id": "B", "text": "Peers can match this community for traffic engineering and policy", "is_correct": false}, {"id": "C", "text": "Add-path capability allows advertising multiple best paths with unique path IDs", "is_correct": true}, {"id": "D", "text": "The first packet floods everywhere; non-RPF interfaces and no-receiver branches prune", "is_correct": false}]', 'Given: A router configured with BGP add-path and three paths to the same prefix. The router needs to advertise multiple paths to its iBGP peer. Result: Add-path capability allows advertising multiple best paths with unique path IDs.', '{}', 'Security Scenarios', 14.0, 'b22272ec7992ab80_gen_v6', true) ON CONFLICT (id) DO NOTHING;
