INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eb043b1b-7078-48c6-8c52-0cfacaf3cc30', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Active/Active and IPsec VPN?', '[{"id": "A", "text": "Active/Active is both nodes forwarding traffic with load balancing; Screen is zone-based attack detection and prevention.", "is_correct": false}, {"id": "B", "text": "Active/Active is both nodes forwarding traffic with load balancing; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "C", "text": "Active/Active is both nodes forwarding traffic with load balancing; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": true}, {"id": "D", "text": "Active/Active is both nodes forwarding traffic with load balancing; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}]', 'Active/Active both nodes forwarding traffic with load balancing. IPsec VPN encrypted tunnel for site-to-site connectivity.', '{}', 'Security Comparison', 14.0, 'e61058a30a0f0053_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('209ed567-64c4-4d8c-addd-d85f20a55976', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between IPsec VPN and IKE Phase 2?', '[{"id": "A", "text": "IPsec VPN is encrypted tunnel for site-to-site connectivity; Control Link is fab0 interface for chassis cluster control plane IPC.", "is_correct": false}, {"id": "B", "text": "IPsec VPN is encrypted tunnel for site-to-site connectivity; Fabric Link is fab1 interface for session state replication.", "is_correct": false}, {"id": "C", "text": "IPsec VPN is encrypted tunnel for site-to-site connectivity; IKE Phase 2 is IPsec child SA for encrypted data traffic.", "is_correct": true}, {"id": "D", "text": "IPsec VPN is encrypted tunnel for site-to-site connectivity; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}]', 'IPsec VPN encrypted tunnel for site-to-site connectivity. IKE Phase 2 IPsec child SA for encrypted data traffic.', '{}', 'Security Comparison', 14.0, '1538184ae5d289cf_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7001bc6e-c52b-4adf-9e50-1757f9362c1d', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Security Zone and Chassis Cluster?', '[{"id": "A", "text": "Security Zone is logical interface group with common security policies; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}, {"id": "B", "text": "Security Zone is logical interface group with common security policies; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": true}, {"id": "C", "text": "Security Zone is logical interface group with common security policies; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}, {"id": "D", "text": "Security Zone is logical interface group with common security policies; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": true}]', 'Security Zone logical interface group with common security policies. Chassis Cluster two SRX devices as HA pair with stateful failover.', '{}', 'Security Comparison', 14.0, '6dd26c26a1550617_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('aa69bc91-5e9e-46f6-b822-35e2f7a65afe', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between IKE Phase 1 and Flow Mode?', '[{"id": "A", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Fabric Link is fab1 interface for session state replication.", "is_correct": false}, {"id": "B", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; AppSecure is application identification and application-based policies.", "is_correct": false}, {"id": "C", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Packet Mode is fast forwarding without stateful inspection.", "is_correct": false}, {"id": "D", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic; Flow Mode is stateful inspection mode tracking session state.", "is_correct": true}]', 'IKE Phase 1 authenticated ISAKMP tunnel for management traffic. Flow Mode stateful inspection mode tracking session state.', '{}', 'Security Comparison', 14.0, '1fc053b86f884f1a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c7812340-aa39-4c76-b86e-07bd17e1e742', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Inter-zone Traffic and Active/Active?', '[{"id": "A", "text": "Inter-zone Traffic is traffic between different zones; denied by default; Screen is zone-based attack detection and prevention.", "is_correct": false}, {"id": "B", "text": "Inter-zone Traffic is traffic between different zones; denied by default; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": false}, {"id": "C", "text": "Inter-zone Traffic is traffic between different zones; denied by default; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "D", "text": "Inter-zone Traffic is traffic between different zones; denied by default; Active/Active is both nodes forwarding traffic with load balancing.", "is_correct": true}]', 'Inter-zone Traffic traffic between different zones; denied by default. Active/Active both nodes forwarding traffic with load balancing.', '{}', 'Security Comparison', 14.0, '145c66050ebca8d3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db4b48ac-e5c8-4da8-82d5-52091713a569', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Policy-based VPN and Screen?', '[{"id": "A", "text": "Policy-based VPN is IPsec triggered by security policy match; Screen is zone-based attack detection and prevention.", "is_correct": true}, {"id": "B", "text": "Policy-based VPN is IPsec triggered by security policy match; Route-based VPN is IPsec tunnel bound to a st0 interface for routing.", "is_correct": false}, {"id": "C", "text": "Policy-based VPN is IPsec triggered by security policy match; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": false}, {"id": "D", "text": "Policy-based VPN is IPsec triggered by security policy match; Screen is zone-based attack detection and prevention.", "is_correct": true}]', 'Policy-based VPN IPsec triggered by security policy match. Screen zone-based attack detection and prevention.', '{}', 'Security Comparison', 14.0, '8e10b5dd69c8990a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('abbc90a4-aad9-4017-93d9-cb8847b492f1', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Flow Mode and Security Policy?', '[{"id": "A", "text": "Flow Mode is stateful inspection mode tracking session state; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic.", "is_correct": false}, {"id": "B", "text": "Flow Mode is stateful inspection mode tracking session state; Security Policy is rules defining permitted/denied traffic between zones.", "is_correct": true}, {"id": "C", "text": "Flow Mode is stateful inspection mode tracking session state; Inter-zone Traffic is traffic between different zones; denied by default.", "is_correct": false}, {"id": "D", "text": "Flow Mode is stateful inspection mode tracking session state; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}]', 'Flow Mode stateful inspection mode tracking session state. Security Policy rules defining permitted/denied traffic between zones.', '{}', 'Security Comparison', 14.0, 'f730ae5bb02f9360_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a95f0bc5-163b-4378-885b-c31c5bda4074', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Security Zone and Screen?', '[{"id": "A", "text": "Security Zone is logical interface group with common security policies; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}, {"id": "B", "text": "Security Zone is logical interface group with common security policies; Policy-based VPN is IPsec triggered by security policy match.", "is_correct": false}, {"id": "C", "text": "Security Zone is logical interface group with common security policies; ALG is Application Layer Gateway; deep inspection for embedded IPs/ports.", "is_correct": false}, {"id": "D", "text": "Security Zone is logical interface group with common security policies; Screen is zone-based attack detection and prevention.", "is_correct": true}]', 'Security Zone logical interface group with common security policies. Screen zone-based attack detection and prevention.', '{}', 'Security Comparison', 14.0, 'd8f84e56357410cb_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0b3a1c61-6886-4f60-9479-5dfd08bd882a', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between NAT Source and Fabric Link?', '[{"id": "A", "text": "NAT Source is translating private source IPs to public IPs; IDP is Intrusion Detection and Prevention; signature-based traffic inspection.", "is_correct": false}, {"id": "B", "text": "NAT Source is translating private source IPs to public IPs; Fabric Link is fab1 interface for session state replication.", "is_correct": true}, {"id": "C", "text": "NAT Source is translating private source IPs to public IPs; Fabric Link is fab1 interface for session state replication.", "is_correct": true}, {"id": "D", "text": "NAT Source is translating private source IPs to public IPs; NAT Destination is translating public destination IPs to private IPs.", "is_correct": false}]', 'NAT Source translating private source IPs to public IPs. Fabric Link fab1 interface for session state replication.', '{}', 'Security Comparison', 14.0, '684ab0ffb47e1e79_gen_v6', true) ON CONFLICT (id) DO NOTHING;
