INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1f61be9c-85f8-4972-b0a2-0569db96ec2c', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between NAT Destination and Active/Passive?', '[{"id": "A", "text": "NAT Destination is translating public destination IPs to private IPs; Active/Active is both nodes forwarding traffic with load balancing.", "is_correct": false}, {"id": "B", "text": "NAT Destination is translating public destination IPs to private IPs; IPsec VPN is encrypted tunnel for site-to-site connectivity.", "is_correct": false}, {"id": "C", "text": "NAT Destination is translating public destination IPs to private IPs; Active/Passive is one node active forwarding traffic; standby takes over on failure.", "is_correct": true}, {"id": "D", "text": "NAT Destination is translating public destination IPs to private IPs; SecIntel is cloud threat intelligence blocking malicious IPs/URLs.", "is_correct": false}]', 'NAT Destination translating public destination IPs to private IPs. Active/Passive one node active forwarding traffic; standby takes over on failure.', '{}', 'Security Comparison', 14.0, 'b58f28382bb464a9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
