INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cb4e7528-fe94-4798-9c92-765299885873', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between Fabric Link and Chassis Cluster?', '[{"id": "A", "text": "Fabric Link is fab1 interface for session state replication; Active/Active is both nodes forwarding traffic with load balancing.", "is_correct": false}, {"id": "B", "text": "Fabric Link is fab1 interface for session state replication; Intra-zone Traffic is traffic within the same zone; permitted by default.", "is_correct": false}, {"id": "C", "text": "Fabric Link is fab1 interface for session state replication; AppSecure is application identification and application-based policies.", "is_correct": false}, {"id": "D", "text": "Fabric Link is fab1 interface for session state replication; Chassis Cluster is two SRX devices as HA pair with stateful failover.", "is_correct": true}]', 'Fabric Link fab1 interface for session state replication. Chassis Cluster two SRX devices as HA pair with stateful failover.', '{}', 'Security Comparison', 14.0, '72964ba1a7ebe4a9_gen_v6', true) ON CONFLICT (id) DO NOTHING;
