INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5906de58-19ff-41e6-ab0f-30eb3ce08341', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between PFS and SPD?', '[{"id": "A", "text": "PFS is Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2; IKE Phase 2 is IPsec child SA negotiation for encrypted data traffic.", "is_correct": false}, {"id": "B", "text": "PFS is Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2; SPD is Security Policy Database; defines traffic to protect via IPsec.", "is_correct": true}, {"id": "C", "text": "PFS is Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2; IPsec Tunnel Mode is encrypts entire IP packet; new IP header added.", "is_correct": false}, {"id": "D", "text": "PFS is Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2; SPD is Security Policy Database; defines traffic to protect via IPsec.", "is_correct": true}]', 'PFS Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2. SPD Security Policy Database; defines traffic to protect via IPsec.', '{}', 'IPsec Comparison', 14.0, 'b4d32c1218223770_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d3c6132-18b9-4cad-9666-c0070eb78406', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between D-H Group and IPsec Transport Mode?', '[{"id": "A", "text": "D-H Group is Diffie-Hellman group determining key exchange strength; IPsec Transport Mode is encrypts only payload; original IP header preserved.", "is_correct": true}, {"id": "B", "text": "D-H Group is Diffie-Hellman group determining key exchange strength; SA is Security Association; simplex IPsec tunnel configuration.", "is_correct": false}, {"id": "C", "text": "D-H Group is Diffie-Hellman group determining key exchange strength; NAT-T is NAT Traversal; UDP 4500 encapsulation for IPsec through NAT.", "is_correct": false}, {"id": "D", "text": "D-H Group is Diffie-Hellman group determining key exchange strength; ESP is Encapsulating Security Payload; encrypts and authenticates IP packets.", "is_correct": false}]', 'D-H Group Diffie-Hellman group determining key exchange strength. IPsec Transport Mode encrypts only payload; original IP header preserved.', '{}', 'IPsec Comparison', 14.0, '12b284c189b47c85_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('253917e1-1f1f-495d-8c76-df03712de6bf', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between IKE Phase 1 and ESP?', '[{"id": "A", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic (main/aggressive mode); GRE over IPsec is IPsec tunnel encapsulating GRE tunnel with routing protocols.", "is_correct": false}, {"id": "B", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic (main/aggressive mode); IPsec Tunnel Mode is encrypts entire IP packet; new IP header added.", "is_correct": false}, {"id": "C", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic (main/aggressive mode); ESP is Encapsulating Security Payload; encrypts and authenticates IP packets.", "is_correct": true}, {"id": "D", "text": "IKE Phase 1 is authenticated ISAKMP tunnel for management traffic (main/aggressive mode); IPsec VTI is Virtual Tunnel Interface for route-based IPsec VPNs.", "is_correct": false}]', 'IKE Phase 1 authenticated ISAKMP tunnel for management traffic (main/aggressive mode). ESP Encapsulating Security Payload; encrypts and authenticates IP packets.', '{}', 'IPsec Comparison', 14.0, '55a5726be4f7d0ed_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b44da471-ae44-4732-969a-f7a472c868ec', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between IKE Phase 2 and PFS?', '[{"id": "A", "text": "IKE Phase 2 is IPsec child SA negotiation for encrypted data traffic; IKE Phase 1 is authenticated ISAKMP tunnel for management traffic (main/aggressive mode).", "is_correct": false}, {"id": "B", "text": "IKE Phase 2 is IPsec child SA negotiation for encrypted data traffic; ESP is Encapsulating Security Payload; encrypts and authenticates IP packets.", "is_correct": false}, {"id": "C", "text": "IKE Phase 2 is IPsec child SA negotiation for encrypted data traffic; PFS is Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2.", "is_correct": true}, {"id": "D", "text": "IKE Phase 2 is IPsec child SA negotiation for encrypted data traffic; IPsec Tunnel Mode is encrypts entire IP packet; new IP header added.", "is_correct": false}]', 'IKE Phase 2 IPsec child SA negotiation for encrypted data traffic. PFS Perfect Forward Secrecy; new Diffie-Hellman key for each phase 2.', '{}', 'IPsec Comparison', 14.0, '0f29877413e31372_gen_v6', true) ON CONFLICT (id) DO NOTHING;
