INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c720889d-e505-49ab-a035-ebf1f514ae27', 'b0000000-0000-0000-0000-000000000024', 'a0000000-0000-0000-0000-000000000003', 'single-choice', 4, 'understand', 'What is the difference between SPD and D-H Group?', '[{"id": "A", "text": "SPD is Security Policy Database; defines traffic to protect via IPsec; Anti-Replay is sequence number window protecting against replay attacks.", "is_correct": false}, {"id": "B", "text": "SPD is Security Policy Database; defines traffic to protect via IPsec; D-H Group is Diffie-Hellman group determining key exchange strength.", "is_correct": true}, {"id": "C", "text": "SPD is Security Policy Database; defines traffic to protect via IPsec; ISAKMP is Internet Security Association and Key Management Protocol (UDP 500).", "is_correct": false}, {"id": "D", "text": "SPD is Security Policy Database; defines traffic to protect via IPsec; D-H Group is Diffie-Hellman group determining key exchange strength.", "is_correct": true}]', 'SPD Security Policy Database; defines traffic to protect via IPsec. D-H Group Diffie-Hellman group determining key exchange strength.', '{}', 'IPsec Comparison', 14.0, 'a838821cdc6f88c3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
