INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('266ce947-eb2c-4599-8f4d-1790731b5551', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is the difference between Overlay Network and MC-LAG?', '[{"id": "A", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); ECMP is equal-cost multi-path load balancing across parallel links.", "is_correct": false}, {"id": "B", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); MC-LAG is Multi-Chassis LAG active-active server multi-homing.", "is_correct": true}, {"id": "C", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); MC-LAG is Multi-Chassis LAG active-active server multi-homing.", "is_correct": true}, {"id": "D", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); Spine Switch is core switch interconnecting leaf switches at high speed.", "is_correct": false}]', 'Overlay Network virtual network over physical fabric (e.g. VXLAN). MC-LAG Multi-Chassis LAG active-active server multi-homing.', '{}', 'DC Comparison', 14.0, 'cab64662f9ad0b63_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('995e810c-dda9-4ccb-ae80-281ef7672852', 'b0000000-0000-0000-0000-000000000026', 'a0000000-0000-0000-0000-000000000004', 'single-choice', 4, 'understand', 'What is the difference between Overlay Network and ECMP?', '[{"id": "A", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); QFX Fabric is QFX series spine/leaf fabric automation (ZTP/ELS).", "is_correct": false}, {"id": "B", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); EVPN-VXLAN is VXLAN with BGP EVPN control plane for multi-tenancy.", "is_correct": false}, {"id": "C", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); ECMP is equal-cost multi-path load balancing across parallel links.", "is_correct": true}, {"id": "D", "text": "Overlay Network is virtual network over physical fabric (e.g. VXLAN); ECMP is equal-cost multi-path load balancing across parallel links.", "is_correct": true}]', 'Overlay Network virtual network over physical fabric (e.g. VXLAN). ECMP equal-cost multi-path load balancing across parallel links.', '{}', 'DC Comparison', 14.0, '2e7feea24c9b0f4f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
