INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6efc14a5-35ed-497b-a3cd-2a1232c31f16', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Event Scripts and NAPALM?', '[{"id": "A", "text": "Event Scripts is triggered by system events (interface down, etc.); Salt is event-driven automation with proxy minions.", "is_correct": false}, {"id": "B", "text": "Event Scripts is triggered by system events (interface down, etc.); NAPALM is multi-vendor network automation library.", "is_correct": true}, {"id": "C", "text": "Event Scripts is triggered by system events (interface down, etc.); NETCONF is XML-based network config protocol over SSH (RFC 6241).", "is_correct": false}, {"id": "D", "text": "Event Scripts is triggered by system events (interface down, etc.); JSNAPy is Junos Snapshot Administrator; automated testing.", "is_correct": false}]', 'Event Scripts triggered by system events (interface down, etc.). NAPALM multi-vendor network automation library.', '{}', 'Automation Comparison', 14.0, '90b4fa18b5043020_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a14c9e6f-3af6-4e15-b5ac-184530743acc', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between SLAX and gRPC?', '[{"id": "A", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; gRPC is Google RPC for high-performance streaming telemetry.", "is_correct": true}, {"id": "B", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}, {"id": "C", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; Python on Junos is Python interpreter running natively on Junos devices.", "is_correct": false}, {"id": "D", "text": "SLAX is Junos automation language; XML-based with XSLT syntax; NETCONF is XML-based network config protocol over SSH (RFC 6241).", "is_correct": false}]', 'SLAX Junos automation language; XML-based with XSLT syntax. gRPC Google RPC for high-performance streaming telemetry.', '{}', 'Automation Comparison', 14.0, 'f40c5d3642e15018_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f60a4d25-441d-47f2-8b13-201e416f9f81', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Event Scripts and JTI?', '[{"id": "A", "text": "Event Scripts is triggered by system events (interface down, etc.); Op Scripts is on-demand operational automation scripts.", "is_correct": false}, {"id": "B", "text": "Event Scripts is triggered by system events (interface down, etc.); JTI is Junos Telemetry Interface; streaming operational telemetry.", "is_correct": true}, {"id": "C", "text": "Event Scripts is triggered by system events (interface down, etc.); JSNAPy is Junos Snapshot Administrator; automated testing.", "is_correct": false}, {"id": "D", "text": "Event Scripts is triggered by system events (interface down, etc.); NAPALM is multi-vendor network automation library.", "is_correct": false}]', 'Event Scripts triggered by system events (interface down, etc.). JTI Junos Telemetry Interface; streaming operational telemetry.', '{}', 'Automation Comparison', 14.0, 'b8e79ffeb86d8b4e_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2349f76-c7a4-4290-99b0-d3849aa3713d', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between gRPC and PyEZ?', '[{"id": "A", "text": "gRPC is Google RPC for high-performance streaming telemetry; Salt is event-driven automation with proxy minions.", "is_correct": false}, {"id": "B", "text": "gRPC is Google RPC for high-performance streaming telemetry; PyEZ is Python library for Junos automation via NETCONF.", "is_correct": true}, {"id": "C", "text": "gRPC is Google RPC for high-performance streaming telemetry; PyEZ is Python library for Junos automation via NETCONF.", "is_correct": true}, {"id": "D", "text": "gRPC is Google RPC for high-performance streaming telemetry; Terraform is infrastructure-as-code provider for network resources.", "is_correct": false}]', 'gRPC Google RPC for high-performance streaming telemetry. PyEZ Python library for Junos automation via NETCONF.', '{}', 'Automation Comparison', 14.0, 'b95495c9d1ee8d03_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d2ce114-49c4-436a-9513-16c50de6443e', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Python on Junos and Jinja2?', '[{"id": "A", "text": "Python on Junos is Python interpreter running natively on Junos devices; Commit Scripts is validate or modify configuration during commit.", "is_correct": false}, {"id": "B", "text": "Python on Junos is Python interpreter running natively on Junos devices; Jinja2 is Python templating engine for config generation.", "is_correct": true}, {"id": "C", "text": "Python on Junos is Python interpreter running natively on Junos devices; gRPC is Google RPC for high-performance streaming telemetry.", "is_correct": false}, {"id": "D", "text": "Python on Junos is Python interpreter running natively on Junos devices; Ansible is agentless YAML playbook automation over SSH/API.", "is_correct": false}]', 'Python on Junos Python interpreter running natively on Junos devices. Jinja2 Python templating engine for config generation.', '{}', 'Automation Comparison', 14.0, '7072caa1eab8d13a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('99455a20-aedf-4ffa-85be-f4a518db3102', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between RESTCONF and Jinja2?', '[{"id": "A", "text": "RESTCONF is HTTP-based config protocol using YANG models (RFC 8040); Jinja2 is Python templating engine for config generation.", "is_correct": true}, {"id": "B", "text": "RESTCONF is HTTP-based config protocol using YANG models (RFC 8040); SLAX is Junos automation language; XML-based with XSLT syntax.", "is_correct": false}, {"id": "C", "text": "RESTCONF is HTTP-based config protocol using YANG models (RFC 8040); Ansible is agentless YAML playbook automation over SSH/API.", "is_correct": false}, {"id": "D", "text": "RESTCONF is HTTP-based config protocol using YANG models (RFC 8040); NETCONF is XML-based network config protocol over SSH (RFC 6241).", "is_correct": false}]', 'RESTCONF HTTP-based config protocol using YANG models (RFC 8040). Jinja2 Python templating engine for config generation.', '{}', 'Automation Comparison', 14.0, '25b104d3f8df936d_gen_v6', true) ON CONFLICT (id) DO NOTHING;
