INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('97a9625e-909a-4384-a9f1-af6fd3af83bf', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between YANG and RESTCONF?', '[{"id": "A", "text": "YANG is data modeling language for config and operational state; OpenConfig is vendor-neutral YANG models for multi-vendor environments.", "is_correct": false}, {"id": "B", "text": "YANG is data modeling language for config and operational state; Salt is event-driven automation with proxy minions.", "is_correct": false}, {"id": "C", "text": "YANG is data modeling language for config and operational state; Python on Junos is Python interpreter running natively on Junos devices.", "is_correct": false}, {"id": "D", "text": "YANG is data modeling language for config and operational state; RESTCONF is HTTP-based config protocol using YANG models (RFC 8040).", "is_correct": true}]', 'YANG data modeling language for config and operational state. RESTCONF HTTP-based config protocol using YANG models (RFC 8040).', '{}', 'Automation Comparison', 14.0, '365944a18107c72a_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95f5ec06-81c7-4af6-8348-e8408afced9a', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Op Scripts and JTI?', '[{"id": "A", "text": "Op Scripts is on-demand operational automation scripts; RESTCONF is HTTP-based config protocol using YANG models (RFC 8040).", "is_correct": false}, {"id": "B", "text": "Op Scripts is on-demand operational automation scripts; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}, {"id": "C", "text": "Op Scripts is on-demand operational automation scripts; JTI is Junos Telemetry Interface; streaming operational telemetry.", "is_correct": true}, {"id": "D", "text": "Op Scripts is on-demand operational automation scripts; Terraform is infrastructure-as-code provider for network resources.", "is_correct": false}]', 'Op Scripts on-demand operational automation scripts. JTI Junos Telemetry Interface; streaming operational telemetry.', '{}', 'Automation Comparison', 14.0, 'eff917cda11b027f_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('76cc5b78-4026-43a4-b71e-55908477c0fa', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Commit Scripts and NAPALM?', '[{"id": "A", "text": "Commit Scripts is validate or modify configuration during commit; Event Scripts is triggered by system events (interface down, etc.).", "is_correct": false}, {"id": "B", "text": "Commit Scripts is validate or modify configuration during commit; Docker is container runtime for containerized network services.", "is_correct": false}, {"id": "C", "text": "Commit Scripts is validate or modify configuration during commit; Kubernetes is container orchestration for cloud-native networking.", "is_correct": false}, {"id": "D", "text": "Commit Scripts is validate or modify configuration during commit; NAPALM is multi-vendor network automation library.", "is_correct": true}]', 'Commit Scripts validate or modify configuration during commit. NAPALM multi-vendor network automation library.', '{}', 'Automation Comparison', 14.0, 'c65a6275e022a4b2_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c8d41b78-f520-4164-af9f-ac9c42fa2d73', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Kubernetes and Commit Scripts?', '[{"id": "A", "text": "Kubernetes is container orchestration for cloud-native networking; SLAX is Junos automation language; XML-based with XSLT syntax.", "is_correct": false}, {"id": "B", "text": "Kubernetes is container orchestration for cloud-native networking; YANG is data modeling language for config and operational state.", "is_correct": false}, {"id": "C", "text": "Kubernetes is container orchestration for cloud-native networking; Commit Scripts is validate or modify configuration during commit.", "is_correct": true}, {"id": "D", "text": "Kubernetes is container orchestration for cloud-native networking; NAPALM is multi-vendor network automation library.", "is_correct": false}]', 'Kubernetes container orchestration for cloud-native networking. Commit Scripts validate or modify configuration during commit.', '{}', 'Automation Comparison', 14.0, '76c00396ac932eb3_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2010e3cf-8b3f-4aea-bed8-796812902878', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between JTI and PyEZ?', '[{"id": "A", "text": "JTI is Junos Telemetry Interface; streaming operational telemetry; JSNAPy is Junos Snapshot Administrator; automated testing.", "is_correct": false}, {"id": "B", "text": "JTI is Junos Telemetry Interface; streaming operational telemetry; PyEZ is Python library for Junos automation via NETCONF.", "is_correct": true}, {"id": "C", "text": "JTI is Junos Telemetry Interface; streaming operational telemetry; YANG is data modeling language for config and operational state.", "is_correct": false}, {"id": "D", "text": "JTI is Junos Telemetry Interface; streaming operational telemetry; Salt is event-driven automation with proxy minions.", "is_correct": false}]', 'JTI Junos Telemetry Interface; streaming operational telemetry. PyEZ Python library for Junos automation via NETCONF.', '{}', 'Automation Comparison', 14.0, '42ce6d0babc31263_gen_v6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('897a9921-1a11-4197-a6a8-adcf895205c7', 'b0000000-0000-0000-0000-000000000028', 'a0000000-0000-0000-0000-000000000005', 'single-choice', 4, 'understand', 'What is the difference between Event Scripts and Terraform?', '[{"id": "A", "text": "Event Scripts is triggered by system events (interface down, etc.); gRPC is Google RPC for high-performance streaming telemetry.", "is_correct": false}, {"id": "B", "text": "Event Scripts is triggered by system events (interface down, etc.); JTI is Junos Telemetry Interface; streaming operational telemetry.", "is_correct": false}, {"id": "C", "text": "Event Scripts is triggered by system events (interface down, etc.); Terraform is infrastructure-as-code provider for network resources.", "is_correct": true}, {"id": "D", "text": "Event Scripts is triggered by system events (interface down, etc.); Terraform is infrastructure-as-code provider for network resources.", "is_correct": true}]', 'Event Scripts triggered by system events (interface down, etc.). Terraform infrastructure-as-code provider for network resources.', '{}', 'Automation Comparison', 14.0, '93c28c772fe4fe2b_gen_v6', true) ON CONFLICT (id) DO NOTHING;
